    # ========================================================
    # Deterministic per-index RNG
    # ========================================================

    def _rng_for_index(
        self,
        index,
    ):

        seed = (
            self.seed
            +
            self.epoch * 1_000_003
            +
            int(index) * 97_409
        )

        return np.random.default_rng(
            seed
        )


    # ========================================================
    # RGB path handling
    # ========================================================

    def _sequence_images(
        self,
        sequence,
    ):

        sequence = str(
            sequence
        )


        if sequence in self.sequence_image_cache:

            return self.sequence_image_cache[
                sequence
            ]


        folder = (
            self.image_root /
            sequence
        )


        paths = []


        for ext in [
            "*.jpg",
            "*.jpeg",
            "*.png",
            "*.JPG",
            "*.JPEG",
            "*.PNG",
        ]:

            paths.extend(
                folder.glob(
                    ext
                )
            )


        paths = sorted(
            set(
                paths
            )
        )


        if not paths:

            raise FileNotFoundError(
                f"No RGB frames found: {folder}"
            )


        self.sequence_image_cache[
            sequence
        ] = paths


        return paths


    def _resolve_image_path(
        self,
        descriptor_index,
    ):

        row = self.meta.iloc[
            int(
                descriptor_index
            )
        ]


        sequence = str(
            row[
                "sequence"
            ]
        )

        frame_index = int(
            row[
                "frame_index"
            ]
        )


        images = self._sequence_images(
            sequence
        )


        if not (
            0
            <=
            frame_index
            <
            len(images)
        ):

            raise IndexError(
                f"{sequence}: frame_index={frame_index}, "
                f"RGB frames={len(images)}"
            )


        return images[
            frame_index
        ]


    def _load_rgb(
        self,
        descriptor_index,
    ):

        path = self._resolve_image_path(
            descriptor_index
        )


        with Image.open(
            path
        ) as image:

            image = image.convert(
                "RGB"
            )


        return (
            image,
            path
        )


    # ========================================================
    # Target pose rendering
    # ========================================================

    def _target_pose_pixels(
        self,
        descriptor_index,
    ):

        descriptor_index = int(
            descriptor_index
        )


        pose = self.pose_normalized[
            descriptor_index
        ].astype(
            np.float32
        )

        visible = self.pose_visible[
            descriptor_index
        ]

        center = self.center_xy[
            descriptor_index
        ].astype(
            np.float32
        )

        scale = float(
            self.torso_scale[
                descriptor_index
            ]
        )


        xy = (
            pose
            *
            scale
            +
            center[
                None,
                :
            ]
        )


        return (
            xy,
            visible
        )


    def _render_target_pose(
        self,
        descriptor_index,
        original_size,
    ):
        """
        White skeleton on black background.
        """

        width, height = original_size


        canvas = Image.new(
            "RGB",
            (
                width,
                height
            ),
            "black"
        )


        draw = ImageDraw.Draw(
            canvas
        )


        xy, visible = self._target_pose_pixels(
            descriptor_index
        )


        # Scale line thickness with image resolution.
        line_width = max(
            2,
            int(
                round(
                    min(
                        width,
                        height
                    )
                    /
                    220
                )
            )
        )


        joint_radius = max(
            3,
            int(
                round(
                    min(
                        width,
                        height
                    )
                    /
                    160
                )
            )
        )


        # ----------------------------------------------------
        # Skeleton
        # ----------------------------------------------------

        for a, b in POSE_EDGES:

            if not (
                visible[a]
                and
                visible[b]
            ):
                continue


            xa, ya = xy[
                a
            ]

            xb, yb = xy[
                b
            ]


            if not np.all(
                np.isfinite(
                    [
                        xa,
                        ya,
                        xb,
                        yb,
                    ]
                )
            ):
                continue


            draw.line(
                [
                    (
                        float(xa),
                        float(ya)
                    ),
                    (
                        float(xb),
                        float(yb)
                    ),
                ],
                fill="white",
                width=line_width
            )


        # ----------------------------------------------------
        # Joints
        # ----------------------------------------------------

        for joint_id in range(
            len(xy)
        ):

            if not visible[
                joint_id
            ]:
                continue


            x, y = xy[
                joint_id
            ]


            if not np.all(
                np.isfinite(
                    [
                        x,
                        y
                    ]
                )
            ):
                continue


            draw.ellipse(
                [
                    (
                        float(x - joint_radius),
                        float(y - joint_radius)
                    ),
                    (
                        float(x + joint_radius),
                        float(y + joint_radius)
                    ),
                ],
                fill="white"
            )


        return canvas


    # ========================================================
    # Tensor conversion
    # ========================================================

    def _to_tensor(
        self,
        image,
    ):

        image = image.resize(
            (
                self.image_size,
                self.image_size
            ),
            Image.Resampling.LANCZOS
        )


        tensor = TF.pil_to_tensor(
            image
        ).float()


        tensor = (
            tensor
            /
            255.0
        )


        return tensor


    def _pose_to_tensor(
        self,
        pose_image,
    ):

        pose_image = pose_image.resize(
            (
                self.image_size,
                self.image_size
            ),
            Image.Resampling.BILINEAR
        )


        tensor = TF.pil_to_tensor(
            pose_image
        ).float()


        tensor = (
            tensor
            /
            255.0
        )


        return tensor


    # ========================================================
    # Candidate sampling
    # ========================================================

    def _candidate_targets(
        self,
        source,
        bin_name,
    ):

        indptr = self.pool[
            f"{bin_name}_indptr"
        ]

        indices = self.pool[
            f"{bin_name}_indices"
        ]


        start = int(
            indptr[
                source
            ]
        )

        end = int(
            indptr[
                source + 1
            ]
        )


        return indices[
            start:end
        ]


    def _sample_train_pair(
        self,
        index,
    ):

        rng = self._rng_for_index(
            index
        )


        # ----------------------------------------------------
        # 1. sequence-balanced
        # ----------------------------------------------------

        seq_id = int(
            rng.choice(
                self.train_sequence_ids
            )
        )


        # ----------------------------------------------------
        # 2. source-uniform
        # ----------------------------------------------------

        source_pool = (
            self.train_sequence_sources[
                seq_id
            ]
        )


        source = int(
            rng.choice(
                source_pool
            )
        )


        # ----------------------------------------------------
        # 3. Natural available-bin random
        # ----------------------------------------------------

        available_ids = np.flatnonzero(
            self.available_bin_mask[
                source
            ]
        )


        if len(
            available_ids
        ) == 0:

            raise RuntimeError(
                f"Train source {source} has no candidate bin."
            )


        bin_id = int(
            rng.choice(
                available_ids
            )
        )


        bin_name = BIN_NAMES[
            bin_id
        ]


        # ----------------------------------------------------
        # 4. Degree-aware target
        # ----------------------------------------------------

        candidates = self._candidate_targets(
            source,
            bin_name
        )


        if len(
            candidates
        ) == 0:

            raise RuntimeError(
                f"Train source {source} has no "
                f"{bin_name} target."
            )


        degree = self.sampling[
            f"{bin_name}_count"
        ][
            candidates
        ].astype(
            np.float64
        )


        weights = (
            1.0
            /
            np.sqrt(
                np.maximum(
                    degree,
                    1.0
                )
            )
        )


        weights /= (
            weights.sum()
        )


        target = int(
            rng.choice(
                candidates,
                p=weights
            )
        )


        return (
            source,
            target,
            bin_name
        )


    # ========================================================
    # Get pair
    # ========================================================

    def _get_pair(
        self,
        index,
    ):

        if self.split == "train":

            return self._sample_train_pair(
                index
            )


        row = self.eval_manifest.iloc[
            int(
                index
            )
        ]


        return (
            int(
                row[
                    "source_descriptor_index"
                ]
            ),

            int(
                row[
                    "target_descriptor_index"
                ]
            ),

            str(
                row[
                    "pose_bin"
                ]
            ),
        )


    # ========================================================
    # __getitem__
    # ========================================================

    def __getitem__(
        self,
        index,
    ):

        source_idx, target_idx, pose_bin = (
            self._get_pair(
                index
            )
        )


        source_row = self.meta.iloc[
            source_idx
        ]

        target_row = self.meta.iloc[
            target_idx
        ]


        if (
            source_row[
                "sequence"
            ]
            !=
            target_row[
                "sequence"
            ]
        ):

            raise RuntimeError(
                "Cross-sequence pair detected."
            )


        # ----------------------------------------------------
        # RGB
        # ----------------------------------------------------

        source_image, source_path = self._load_rgb(
            source_idx
        )

        target_image, target_path = self._load_rgb(
            target_idx
        )


        # ----------------------------------------------------
        # Pose condition uses TARGET geometry
        # ----------------------------------------------------

        target_pose_image = self._render_target_pose(
            target_idx,
            target_image.size
        )


        # ----------------------------------------------------
        # Convert
        # ----------------------------------------------------

        source_tensor = self._to_tensor(
            source_image
        )

        target_tensor = self._to_tensor(
            target_image
        )

        pose_tensor = self._pose_to_tensor(
            target_pose_image
        )


        return {

            "source_rgb":
                source_tensor,

            "target_pose":
                pose_tensor,

            "target_rgb":
                target_tensor,

            "split":
                self.split,

            "sequence":
                str(
                    source_row[
                        "sequence"
                    ]
                ),

            "pose_bin":
                pose_bin,

            "source_descriptor_index":
                int(
                    source_idx
                ),

            "target_descriptor_index":
                int(
                    target_idx
                ),

            "source_frame_index":
                int(
                    source_row[
                        "frame_index"
                    ]
                ),

            "target_frame_index":
                int(
                    target_row[
                        "frame_index"
                    ]
                ),

            "source_path":
                str(
                    source_path
                ),

            "target_path":
                str(
                    target_path
                ),
        }

