        )


def pct(values, ps):
    if not values:
        return {}

    x = np.asarray(
        values,
        dtype=np.float32
    )

    return {
        p: float(
            np.percentile(
                x,
                p
            )
        )
        for p in ps
    }


def print_distribution(
    title,
    counts,
    all_frames=None,
):
    """
    counts:
        frame_id -> usage count

    all_frames:
        若给定，把未出现的 frame 也计为 0
    """

    if all_frames is None:
        values = list(
            counts.values()
        )
    else:
        values = [
            counts.get(
                fid,
                0
            )
            for fid in all_frames
        ]

    if not values:
        print(
            f"{title}: empty"
        )
        return

    c = Counter(
        values
    )

    q = pct(
        values,
        [
            0,
            10,
            25,
            50,
            75,
            90,
            95,
            99,
            100,
        ]
    )

    print(title)

    print(
        "  n frames:",
        len(values)
    )

    print(
        "  min/max :",
        min(values),
        "/",
        max(values)
    )

    print(
        "  mean    :",
        round(
            float(
                np.mean(values)
            ),
            4
        )
    )

    print(
        "  count=0 :",
        c.get(
            0,
            0
        )
    )

    print(
        "  count=1 :",
        c.get(
            1,
            0
        )
    )

    print(
        "  count=2 :",
        c.get(
            2,
            0
        )
    )

    print(
        "  count>=3:",
        sum(
            n
            for k, n in c.items()
            if k >= 3
        )
    )

    print(
        "  percentiles:",
        " ".join(
            f"p{p}={q[p]:.2f}"
            for p in q
        )
    )


def canonical_pair(a, b):
    return tuple(
        sorted(
            [
                a,
                b,
            ]
        )
    )


def audit_pair_rows(
    name,
    rows,
    filter_eligible=False,
):
    if filter_eligible:
        eligible_rows = []

        for r in rows:
            value = r.get(
                "pair_eligible",
                ""
            )

            if value in {
                "1",
                "True",
                "true",
            }:
                eligible_rows.append(
                    r
                )

        rows = eligible_rows

    print()
    print("=" * 96)
    print(name)
    print("=" * 96)

    print(
        "rows:",
        len(rows)
    )

    if not rows:
        return

    src_count = Counter()
    tgt_count = Counter()
    total_count = Counter()

    frame_ids = set()

    self_pairs = 0

    directed = Counter()
    undirected = Counter()

    video_cross = 0
    segment_cross = 0
    split_cross = 0

    source_to_targets = defaultdict(
        set
    )

    target_from_sources = defaultdict(
        set
    )

    for r in rows:
        s = r[
            "source_frame_id"
        ]

        t = r[
            "target_frame_id"
        ]

        src_count[
            s
        ] += 1

        tgt_count[
            t
        ] += 1

        total_count[
            s
        ] += 1

        total_count[
            t
        ] += 1

        frame_ids.add(
            s
        )

        frame_ids.add(
            t
        )

        source_to_targets[
            s
        ].add(
            t
        )

        target_from_sources[
            t
        ].add(
            s
        )

        if s == t:
            self_pairs += 1

        directed[
            (
                s,
                t
            )
        ] += 1

        undirected[
            canonical_pair(
                s,
                t
            )
        ] += 1

        # 以下字段如果有 source/target 独立字段则检查；
        # 没有就跳过
        sv = r.get(
            "source_video_id",
            ""
        )

        tv = r.get(
            "target_video_id",
            ""
        )

        if (
            sv
            and tv
            and sv != tv
        ):
            video_cross += 1

        ss = r.get(
            "source_segment_id",
            ""
        )

        ts = r.get(
            "target_segment_id",
            ""
        )

        if (
            ss
            and ts
            and ss != ts
        ):
            segment_cross += 1

        ssplit = r.get(
            "source_split",
            ""
        )

        tsplit = r.get(
            "target_split",
            ""
        )

        if (
            ssplit
            and tsplit
            and ssplit != tsplit
        ):
            split_cross += 1

    role_overlap = (
        set(
            src_count
        )
        &
        set(
            tgt_count
        )
    )

    reverse_pairs = 0

    seen = set()

    for s, t in directed:
        if (
            (t, s) in directed
            and (t, s) not in seen
        ):
            reverse_pairs += 1

        seen.add(
            (
                s,
                t
            )
        )

    duplicate_directed_rows = sum(
        n - 1
        for n in directed.values()
        if n > 1
    )

    duplicated_unordered = sum(
        n - 1
        for n in undirected.values()
        if n > 1
    )

    print(
        "unique frames:",
        len(frame_ids)
    )

    print(
        "unique sources:",
        len(src_count)
    )

    print(
        "unique targets:",
        len(tgt_count)
    )

    print(
        "frames used in BOTH roles:",
        len(role_overlap)
    )

    if frame_ids:
        print(
            "both-role ratio:",
            round(
                len(role_overlap)
                / len(frame_ids),
                4
            )
        )

    print()

    print_distribution(
        "SOURCE usage",
        src_count,
        frame_ids
    )

    print()

    print_distribution(
        "TARGET usage",
        tgt_count,
        frame_ids
    )

    print()

    print_distribution(
        "TOTAL usage (source + target)",
        total_count,
        frame_ids
    )

    print()

    print(
        "self pairs:",
        self_pairs
    )

    print(
        "duplicate directed rows:",
        duplicate_directed_rows
    )

    print(
        "reverse A->B / B->A pair sets:",
        reverse_pairs
    )

    print(
        "duplicate unordered pair rows:",
        duplicated_unordered
    )

    print(
        "cross-video:",
        video_cross
    )

    print(
        "cross-segment:",
        segment_cross
    )

    print(
        "cross-split:",
        split_cross
    )

    print()

    target_mult = Counter(
        tgt_count.values()
    )

    print(
        "TARGET multiplicity exact:"
    )

    for k in sorted(
        target_mult
    ):
        print(
            f"  used {k:2d} times : "
            f"{target_mult[k]:4d} frames"
        )

    print()

    most_targeted = sorted(
        tgt_count.items(),
        key=lambda x: (
            -x[1],
            x[0]
        )
    )[:15]

    print(
        "TOP-15 most reused TARGET frames:"
    )

    for fid, n in most_targeted:
        print(
            f"  {n:3d}x  {fid}"
        )


def audit_candidate_degree(rows):
