def read_csv(path):
    with path.open("r", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def write_csv(path, rows):
    if not rows:
        return

    path.parent.mkdir(
        parents=True,
        exist_ok=True
    )

    with path.open(
        "w",
        newline="",
        encoding="utf-8",
    ) as f:
        writer = csv.DictWriter(
            f,
            fieldnames=rows[0].keys(),
            extrasaction="ignore",
        )

        writer.writeheader()
        writer.writerows(rows)


def find_field(
    fieldnames,
    candidates,
    contains=None,
):
    for key in candidates:
        if key in fieldnames:
            return key

    if contains is not None:
        for key in fieldnames:
            if contains.lower() in key.lower():
                return key

    return None


def build_frame_index(rows):
    if not rows:
        raise RuntimeError(
            "FRAME_CSV is empty"
        )

    fields = rows[0].keys()

    npz_key = find_field(
        fields,
        [
            "npz_path",
            "dwpose_npz_path",
            "pose_npz_path",
        ],
        contains="npz",
    )

    if npz_key is None:
        raise RuntimeError(
            "Cannot find NPZ path field in frame CSV"
        )

    index = {}

    possible_keys = [
        "frame_id",
        "selected_frame_id",
        "image_id",
        "frame_path",
        "image_path",
        "selected_frame_path",
    ]

    for row in rows:
        for key in possible_keys:
            value = row.get(
                key,
                ""
            )

            if value:
                index[
                    value
                ] = row

                try:
                    index[
                        str(
                            Path(
                                value
                            ).resolve()
                        )
                    ] = row
                except Exception:
                    pass

        # 额外用 npz stem 建一个索引
        npz = row.get(
            npz_key,
            ""
        )

        if npz:
            index.setdefault(
                Path(npz).stem,
                row
            )

    return (
        index,
        npz_key,
    )


def resolve_frame_row(
    pair_row,
    role,
    frame_index,
):
    keys = [
        f"{role}_frame_id",
        f"{role}_frame_path",
    ]

    for key in keys:
        value = pair_row.get(
            key,
            ""
        )

        if not value:
            continue

        if value in frame_index:
            return frame_index[
                value
            ]

        try:
            resolved = str(
                Path(
                    value
                ).resolve()
            )

            if resolved in frame_index:
                return frame_index[
                    resolved
                ]
        except Exception:
            pass

    return None


def normalize_keypoint_arrays(
    arrays,
):
    kp = None
    scores = None

    # 优先找明显的 keypoint 数组
    preferred_kp = [
        "keypoints",
        "wholebody_keypoints",
        "pose_keypoints",
        "kpts",
        "candidate",
    ]

    for key in preferred_kp:
        if key in arrays:
            arr = np.asarray(
                arrays[key]
            )

            if (
                arr.ndim >= 2
                and
                arr.shape[-2] >= 18
                and
                arr.shape[-1] in [2, 3, 4]
            ):
                kp = arr
                break

    # 找不到时按 shape 搜
    if kp is None:
        for key in arrays.files:
            arr = np.asarray(
                arrays[key]
            )

            if (
                arr.ndim >= 2
                and
                arr.shape[-2] >= 18
                and
                arr.shape[-1] in [2, 3, 4]
            ):
                kp = arr
                break

    if kp is None:
        raise RuntimeError(
            f"Cannot find keypoint array. "
            f"NPZ keys={arrays.files}"
        )

    # 单人 [K,C] -> [1,K,C]
    if kp.ndim == 2:
        kp = kp[
            None,
            ...
        ]

    # 如果第三维自带 confidence
    if kp.shape[-1] >= 3:
        embedded_scores = (
            kp[..., 2]
            .astype(
                np.float32
            )
        )

        kp_xy = (
            kp[..., :2]
            .astype(
                np.float32
            )
        )
    else:
        embedded_scores = None
        kp_xy = (
            kp[..., :2]
            .astype(
                np.float32
            )
        )

    n_person = kp_xy.shape[0]
    n_joint = kp_xy.shape[1]

    preferred_score = [
        "scores",
        "score",
        "keypoint_scores",
        "confidences",
        "confidence",
        "subset",
    ]

    for key in preferred_score:
        if key not in arrays:
            continue

        arr = np.asarray(
            arrays[key]
        )

        if (
            arr.ndim == 1
            and
            arr.shape[0] == n_joint
        ):
            scores = arr[
                None,
                ...
            ]
            break

        if (
            arr.ndim >= 2
            and
            arr.shape[-1] == n_joint
        ):
            scores = arr.reshape(
                -1,
                n_joint
            )
            break

    if scores is None:
        for key in arrays.files:
            arr = np.asarray(
                arrays[key]
            )

            if (
                arr.ndim == 1
                and
                arr.shape[0] == n_joint
            ):
                scores = arr[
                    None,
                    ...
                ]
                break

            if (
                arr.ndim == 2
                and
                arr.shape[-1] == n_joint
            ):
                scores = arr
                break

    if scores is None:
        scores = embedded_scores

    if scores is None:
        raise RuntimeError(
            f"Cannot find score array. "
            f"NPZ keys={arrays.files}"
        )

    scores = np.asarray(
        scores,
        dtype=np.float32,
    )

    if scores.ndim == 1:
        scores = scores[
            None,
            ...
        ]

    # 人数维度不一致时尽量安全裁剪
    n = min(
        kp_xy.shape[0],
        scores.shape[0],
    )

    kp_xy = kp_xy[:n]
    scores = scores[:n]

    return (
        kp_xy,
        scores,
    )


def choose_valid_person(
    keypoints,
    scores,
):
    candidates = []

    for i in range(
        keypoints.shape[0]
    ):
        body_scores = (
            scores[
                i,
                :18
            ]
        )

        visible = int(
            np.sum(
                body_scores
                >= CONF_THR
            )
        )

        mean_conf = float(
            np.mean(
                body_scores
            )
        )

        if (
            visible >= 8
            and
            mean_conf >= 0.30
        ):
            candidates.append(
                (
                    mean_conf,
                    visible,
                    i,
                )
            )

    if not candidates:
        return None

    candidates.sort(
        reverse=True
    )

    idx = candidates[
        0
    ][2]

    return (
        keypoints[
            idx
        ],
        scores[
            idx
        ],
    )


def load_pose(
    frame_row,
    npz_key,
    cache,
):
    npz_path = frame_row.get(
        npz_key,
        ""
    )

    if not npz_path:
        raise RuntimeError(
            "empty npz_path"
        )

    if npz_path in cache:
        return cache[
            npz_path
        ]

    path = Path(
        npz_path
    )

    if not path.is_absolute():
        path = (
            ROOT
            / path
        )

    if not path.exists():
        raise FileNotFoundError(
            path
        )

    with np.load(
        path,
        allow_pickle=False,
    ) as arrays:
        keypoints, scores = (
            normalize_keypoint_arrays(
                arrays
            )
        )

    person = (
        choose_valid_person(
            keypoints,
            scores,
        )
    )

    if person is None:
        raise RuntimeError(
            f"no valid single person in {path}"
        )

    cache[
        npz_path
    ] = person

    return person


def vector_angle_deg(
    v1,
    v2,
):
    n1 = float(
        np.linalg.norm(v1)
    )

    n2 = float(
        np.linalg.norm(v2)
    )

    if (
        n1 < 1e-6
        or
        n2 < 1e-6
    ):
        return None

    cosv = float(
        np.dot(
            v1,
            v2
        )
        /
        (
            n1
            * n2
        )
    )

    cosv = float(
        np.clip(
            cosv,
            -1.0,
            1.0,
        )
    )

    return float(
        np.degrees(
            np.arccos(
                cosv
            )
        )
    )


def articulation_angle_deg(
    points,
    scores,
    a,
    b,
    c,
):
    if (
        scores[a] < CONF_THR
        or
        scores[b] < CONF_THR
        or
        scores[c] < CONF_THR
    ):
        return None

    v1 = (
        points[a]
        - points[b]
    )

    v2 = (
        points[c]
        - points[b]
    )

    return vector_angle_deg(
        v1,
        v2
    )


def analyze_pair(
    src_points,
    src_scores,
    tgt_points,
    tgt_scores,
):
    bone_changes = []

    for (
        name,
        a,
        b,
    ) in BONES:

        valid = (
            src_scores[a] >= CONF_THR
            and
            src_scores[b] >= CONF_THR
            and
            tgt_scores[a] >= CONF_THR
            and
            tgt_scores[b] >= CONF_THR
        )

        if not valid:
            continue

        src_vec = (
            src_points[b]
            - src_points[a]
        )

        tgt_vec = (
            tgt_points[b]
            - tgt_points[a]
        )

        angle = vector_angle_deg(
            src_vec,
            tgt_vec,
        )

        if angle is not None:
            bone_changes.append(
                angle
            )

    joint_changes = []

    for (
        name,
        a,
        b,
        c,
    ) in JOINT_ANGLES:

        s = articulation_angle_deg(
            src_points,
            src_scores,
            a,
            b,
            c,
        )

        t = articulation_angle_deg(
            tgt_points,
            tgt_scores,
            a,
            b,
            c,
        )

        if (
            s is None
            or
            t is None
        ):
            continue

        joint_changes.append(
            abs(
                s - t
            )
        )

    if bone_changes:
        b = np.asarray(
            bone_changes,
            dtype=np.float32,
        )

        bmean = float(
            np.mean(b)
        )

        bmed = float(
            np.median(b)
        )

        bp75 = float(
            np.percentile(
                b,
                75
            )
        )

        bp90 = float(
            np.percentile(
                b,
                90
            )
        )

        bmax = float(
            np.max(b)
        )

        b10 = int(
            np.sum(
                b >= 10
            )
        )

        b15 = int(
            np.sum(
                b >= 15
            )
        )

        b20 = int(
            np.sum(
                b >= 20
            )
        )

        b30 = int(
            np.sum(
                b >= 30
            )
        )

    else:
        bmean = bmed = bp75 = bp90 = bmax = None
        b10 = b15 = b20 = b30 = 0

    if joint_changes:
        j = np.asarray(
            joint_changes,
            dtype=np.float32,
        )

        jmean = float(
            np.mean(j)
        )

        jmed = float(
            np.median(j)
        )

        jp75 = float(
            np.percentile(
                j,
                75
            )
        )

        jmax = float(
            np.max(j)
        )

        j10 = int(
            np.sum(
                j >= 10
            )
        )

        j20 = int(
            np.sum(
                j >= 20
            )
        )

        j30 = int(
            np.sum(
                j >= 30
            )
        )

    else:
        jmean = jmed = jp75 = jmax = None
        j10 = j20 = j30 = 0

    return {
        "valid_bones":
            len(
                bone_changes
            ),

        "bone_angle_mean_deg":
            bmean,

        "bone_angle_median_deg":
            bmed,

        "bone_angle_p75_deg":
            bp75,

        "bone_angle_p90_deg":
            bp90,

        "bone_angle_max_deg":
            bmax,

        "bones_ge_10deg":
            b10,

        "bones_ge_15deg":
            b15,

        "bones_ge_20deg":
            b20,

        "bones_ge_30deg":
            b30,

        "bones_ge_15deg_ratio":
            (
                b15
                /
                len(
                    bone_changes
                )
                if bone_changes
                else 0.0
            ),

        "valid_articulations":
            len(
                joint_changes
            ),

        "joint_angle_mean_deg":
            jmean,

        "joint_angle_median_deg":
            jmed,

        "joint_angle_p75_deg":
            jp75,

        "joint_angle_max_deg":
            jmax,

        "joints_ge_10deg":
            j10,

        "joints_ge_20deg":
            j20,

        "joints_ge_30deg":
            j30,
    }


def classify_metrics(m):
    vb = int(
        m[
            "valid_bones"
        ]
    )

    va = int(
        m[
            "valid_articulations"
        ]
    )

    bmed = m[
        "bone_angle_median_deg"
    ]

    jmed = m[
        "joint_angle_median_deg"
    ]

    b20 = int(
        m[
            "bones_ge_20deg"
        ]
    )

    j20 = int(
        m[
            "joints_ge_20deg"
        ]
    )

    # 至少要有基本可计算证据
    metric_ok = (
        bmed is not None
        and
        jmed is not None
        and
        vb >= 1
        and
        va >= 1
    )

    if not metric_ok:
        return {
            "robust_evidence_ok":
                0,

            "pose_metric_uncertain":
                1,

            "robust_too_similar_v2":
                0,

            "robust_pair_eligible":
                0,

            "robust_pose_status":
                "metric_insufficient",

            "pose_change_strength":
                "unknown",
        }

    evidence_ok = (
        vb >= 6
        and
        va >= 3
    )

    too_similar = (
        evidence_ok
        and
        bmed < 8.0
        and
        b20 <= 1
        and
        j20 <= 1
        and
        jmed < 10.0
    )

    if too_similar:
        status = (
            "too_similar"
        )

        strength = (
            "too_similar"
        )

        eligible = 0

    else:
        eligible = 1

        if not evidence_ok:
            status = (
                "uncertain_valid"
            )

        else:
            status = (
                "valid_change"
            )

        if (
            bmed >= 15.0
            or
            b20 >= 3
            or
            j20 >= 2
        ):
            strength = (
                "clear"
            )

        else:
            strength = (
                "acceptable"
            )

    return {
        "robust_evidence_ok":
            int(
                evidence_ok
            ),

        "pose_metric_uncertain":
            int(
                not evidence_ok
            ),

        "robust_too_similar_v2":
            int(
                too_similar
            ),

        "robust_pair_eligible":
            int(
                eligible
            ),

        "robust_pose_status":
            status,

        "pose_change_strength":
            strength,
    }


