def person0_item(value):
    if isinstance(value, (list, tuple)):
        return np.asarray(value[0])

    arr = np.asarray(value)

    # Most 3DPW person-indexed arrays have actor as axis 0.
    if arr.ndim >= 2:
        return np.asarray(arr[0])

    return arr


def normalize_gender(x):
    if isinstance(x, bytes):
        x = x.decode(
            "utf-8",
            errors="ignore"
        )

    x = str(x).lower().strip()

    if x.startswith("m"):
        return "male"

    if x.startswith("f"):
        return "female"

    return "neutral"


def get_gender(data):
    for key in [
