def apply_transform(vertices, T):
    ones = np.ones(
        (
            len(vertices),
            1
        ),
        dtype=np.float64
    )

    vh = np.concatenate(
        [
            vertices.astype(np.float64),
            ones
        ],
        axis=1
    )

    out = (
        T
        @
        vh.T
    ).T

    return out[:, :3]


def project(vertices_cam, K, H, W):
    z = vertices_cam[:, 2]

    valid = (
        np.isfinite(vertices_cam).all(axis=1)
        &
        (z > 1e-4)
    )

    if valid.sum() < 50:
        return None

    p = vertices_cam[valid]

    x = (
        K[0, 0]
        *
        p[:, 0]
        /
        p[:, 2]
        +
        K[0, 2]
    )

    y = (
        K[1, 1]
        *
        p[:, 1]
        /
        p[:, 2]
        +
        K[1, 2]
    )

    xy = np.stack(
        [x, y],
        axis=1
    )

    finite = np.isfinite(
        xy
    ).all(axis=1)

    xy = xy[finite]

    if len(xy) < 50:
        return None

    # Robust mesh bbox. A few extreme vertices should not
    # destroy the comparison.
    x1, x2 = np.quantile(
        xy[:, 0],
        [
            0.005,
            0.995
        ]
    )

    y1, y2 = np.quantile(
        xy[:, 1],
        [
            0.005,
            0.995
        ]
    )

    bbox = np.asarray(
        [
            x1,
            y1,
            x2,
            y2
        ],
        dtype=np.float64
    )

    inside = (
        (xy[:, 0] >= 0)
        &
        (xy[:, 0] < W)
        &
        (xy[:, 1] >= 0)
        &
        (xy[:, 1] < H)
    )

    return {
        "xy": xy,
        "bbox": bbox,
        "inside_ratio": float(
            inside.mean()
        ),
        "median_z": float(
            np.median(
                p[:, 2]
            )
        ),
    }


def bbox_from_mask(mask):
    ys, xs = np.nonzero(
        mask > 0
    )

    if len(xs) == 0:
        return None

    return np.asarray(
        [
            xs.min(),
            ys.min(),
            xs.max(),
            ys.max()
        ],
        dtype=np.float64
    )


def bbox_iou(a, b):
    if a is None or b is None:
        return 0.0

    x1 = max(
        a[0],
        b[0]
    )

    y1 = max(
        a[1],
        b[1]
    )

    x2 = min(
        a[2],
        b[2]
    )

    y2 = min(
        a[3],
        b[3]
    )

    inter_w = max(
        0.0,
        x2 - x1 + 1
    )

    inter_h = max(
        0.0,
        y2 - y1 + 1
    )

    inter = (
        inter_w
        *
        inter_h
    )

    area_a = max(
        0.0,
        a[2] - a[0] + 1
    ) * max(
        0.0,
        a[3] - a[1] + 1
    )

    area_b = max(
        0.0,
        b[2] - b[0] + 1
    ) * max(
        0.0,
        b[3] - b[1] + 1
    )

    union = (
        area_a
        +
        area_b
        -
        inter
    )

    if union <= 0:
        return 0.0

    return float(
        inter
        /
        union
    )


def bbox_center_error_norm(
    a,
    b
):
    if a is None or b is None:
        return np.inf

    ca = np.asarray(
        [
            (a[0] + a[2]) / 2,
            (a[1] + a[3]) / 2
        ]
    )

    cb = np.asarray(
        [
            (b[0] + b[2]) / 2,
            (b[1] + b[3]) / 2
        ]
    )

    diag = np.linalg.norm(
        [
            b[2] - b[0],
            b[3] - b[1]
        ]
    )

    return float(
        np.linalg.norm(
            ca - cb
        )
        /
        max(
            diag,
            1.0
        )
    )


def make_model(gender, num_betas):
    return smplx.SMPL(
        model_path=str(
            SMPL_MODEL_ROOT
        ),
        gender=gender,
        num_betas=num_betas,
        batch_size=1,
        create_transl=True,
    ).eval()


def draw_projection(
    rgb,
    xy,
    mesh_bbox,
    mask_bbox,
    title,
):
    out = Image.fromarray(
        rgb
    ).convert("RGB")

    draw = ImageDraw.Draw(
        out
    )

    if xy is not None:
        # Sparse vertex overlay, only for visual audit.
        step = max(
            1,
            len(xy) // 500
        )

        for x, y in xy[::step]:
            if (
                0 <= x < out.width
                and
                0 <= y < out.height
            ):
                r = 2

                draw.ellipse(
                    [
                        x-r,
                        y-r,
                        x+r,
                        y+r
                    ],
                    fill=(
                        255,
                        0,
                        0
                    )
                )

    if mesh_bbox is not None:
        draw.rectangle(
            tuple(
                mesh_bbox.tolist()
            ),
            outline=(
                255,
                0,
                0
            ),
            width=4
        )

    if mask_bbox is not None:
        draw.rectangle(
            tuple(
                mask_bbox.tolist()
            ),
            outline=(
                0,
                255,
                0
            ),
            width=4
        )

    draw.text(
        (
            20,
            20
        ),
        title,
        fill=(
            255,
            255,
            0
        )
    )

    return out


def make_contact_sheet(records):
    if not records:
        return

    thumb_w = 240
    thumb_h = 150
    cols = 4

    rows = len(records)

    canvas = Image.new(
        "RGB",
        (
            cols * thumb_w,
            rows * thumb_h
        ),
        "white"
    )

    for r, rec in enumerate(records):
        panels = [
            rec["rgb"],
            rec["direct"],
            rec["cam_pose"],
            rec["inv_cam_pose"],
        ]

        for c, panel in enumerate(
            panels
        ):
            im = panel.copy()

            im.thumbnail(
                (
                    thumb_w,
                    thumb_h
                ),
                Image.Resampling.LANCZOS
            )

            holder = Image.new(
                "RGB",
                (
                    thumb_w,
                    thumb_h
                ),
                "white"
            )

            x = (
                thumb_w
                -
                im.width
            ) // 2

            y = (
                thumb_h
                -
                im.height
            ) // 2

            holder.paste(
                im,
                (
                    x,
                    y
                )
            )

            canvas.paste(
                holder,
                (
                    c * thumb_w,
                    r * thumb_h
                )
            )

    path = (
        OUT /
        "projection_convention_contact_sheet.jpg"
    )

    canvas.save(
        path,
        quality=92
    )

    print(
        "contact sheet:",
        path
    )


