    ).reshape(-1)

    print()
    print("RAW / EXPORTED BETA CHECK")
    print("-" * 100)

    print(
        "sequence:",
        first["sequence"]
    )

    print(
        "raw original betas shape:",
        raw_betas.shape
    )

    print(
        "saved asset betas shape  :",
        saved_betas.shape
    )

    print(
        "raw first values:",
        raw_betas[:10]
    )

    print(
        "saved first values:",
        saved_betas[:10]
    )

    if (
        raw_betas.shape
        ==
        saved_betas.shape
    ):
        print(
            "same shape:",
            True
        )

        print(
            "allclose:",
            bool(
                np.allclose(
                    raw_betas,
                    saved_betas
                )
            )
        )

    else:
        print(
            "same shape:",
            False
        )

    # --------------------------------------------------------
    # Load SMPL models lazily by gender + beta count
    # --------------------------------------------------------

    models = {}

    rows = []

    previews = []

    scores = defaultdict(list)

    beta_dims = Counter()

    for i, row in pilot.iterrows():
        split = str(
            row["split"]
        )

        sequence = str(
            row["sequence"]
        )

        frame_index = int(
            row["frame_index"]
        )

        pkl_path = find_sequence_pkl(
            split,
            sequence
        )

        data = load_pkl(
            pkl_path
        )

        pose = get_pose(
            data,
            frame_index
        )

        trans = get_trans(
            data,
            frame_index
        )

        betas = get_betas(
            data
        )

        gender = get_gender(
            data
        )

        beta_dims[
            len(betas)
        ] += 1

        model_key = (
            gender,
            len(betas)
        )

        if model_key not in models:
            try:
                models[
                    model_key
                ] = make_model(
                    gender,
                    len(betas)
                )

            except Exception as e:
                raise RuntimeError(
                    f"SMPL model cannot represent the original "
                    f"{len(betas)}-D beta vector for gender={gender}. "
                    f"Do not silently truncate GT shape parameters. "
                    f"Original error: {repr(e)}"
                ) from e

        model = models[
            model_key
        ]

        model_num_betas = int(
            model.num_betas
        )

        beta_tensor = torch.from_numpy(
            betas[
                :model_num_betas
            ][None]
        ).float()

        pose_tensor = torch.from_numpy(
            pose[None]
        ).float()

        trans_tensor = torch.from_numpy(
            trans[None]
        ).float()

        with torch.no_grad():
            out = model(
                global_orient=
                    pose_tensor[
                        :,
                        :3
                    ],

                body_pose=
                    pose_tensor[
                        :,
                        3:
                    ],

                betas=
                    beta_tensor,

                transl=
                    trans_tensor,
            )

        vertices = (
            out.vertices[
                0
            ]
            .cpu()
            .numpy()
            .astype(np.float64)
        )

        K = get_K(
            data
        )

        cam_pose = get_cam_pose(
            data,
            frame_index
        )

        rgb_path = image_path(
            sequence,
            frame_index
        )

        with Image.open(
            rgb_path
        ) as im:
            rgb = np.asarray(
                im.convert("RGB")
            )

        H, W = rgb.shape[:2]

        mpath = mask_path(
            split,
            sequence,
            frame_index
        )

        if not mpath.exists():
            raise FileNotFoundError(
                str(mpath)
            )

        mask = cv2.imread(
            str(mpath),
            cv2.IMREAD_GRAYSCALE
        )

        if mask is None:
            raise RuntimeError(
                f"Cannot read {mpath}"
            )

        mask_bbox = bbox_from_mask(
            mask
        )

        conventions = {
            # Hypothesis A:
            # pose + trans already place the SMPL in camera coords.
            "direct":
                vertices,

            # Hypothesis B:
            # cam_pose is world -> camera.
            "cam_pose":
                apply_transform(
                    vertices,
                    cam_pose
                ),

            # Hypothesis C:
            # cam_pose is camera -> world.
            "inv_cam_pose":
                apply_transform(
                    vertices,
                    np.linalg.inv(
                        cam_pose
                    )
                ),
        }

        projected = {}

        rec = {
            "split":
                split,

            "sequence":
                sequence,

            "frame_index":
                frame_index,

            "gender":
                gender,

            "raw_beta_dim":
                len(betas),

            "smpl_num_betas":
                model_num_betas,
        }

        for name, vcam in conventions.items():
            proj = project(
                vcam,
                K,
                H,
                W
            )

            projected[
                name
            ] = proj

            if proj is None:
                iou = 0.0
                center_error = np.inf
                inside_ratio = 0.0
                median_z = np.nan
                mesh_bbox = None
                xy = None

            else:
                mesh_bbox = proj[
                    "bbox"
                ]

                xy = proj[
                    "xy"
                ]

                iou = bbox_iou(
                    mesh_bbox,
                    mask_bbox
                )

                center_error = (
                    bbox_center_error_norm(
                        mesh_bbox,
                        mask_bbox
                    )
                )

                inside_ratio = proj[
                    "inside_ratio"
                ]

                median_z = proj[
                    "median_z"
                ]

            rec[
                f"{name}_bbox_iou"
            ] = iou

            rec[
                f"{name}_center_error_norm"
            ] = center_error

            rec[
                f"{name}_inside_ratio"
            ] = inside_ratio

            rec[
                f"{name}_median_z"
            ] = median_z

            scores[
                name
            ].append(
                iou
            )

        rows.append(
            rec
        )

        if len(previews) < 12:
            base = Image.fromarray(
                rgb
            ).convert("RGB")

            draw = ImageDraw.Draw(
                base
            )

            if mask_bbox is not None:
                draw.rectangle(
                    tuple(
                        mask_bbox.tolist()
                    ),
                    outline=(
                        0,
                        255,
                        0
                    ),
                    width=5
                )

            draw.text(
                (
                    20,
                    20
                ),
                (
                    f"{split}/{sequence} "
                    f"f={frame_index}"
                ),
                fill=(
                    255,
                    255,
                    0
                )
            )

            preview_rec = {
                "rgb":
                    base
            }

            for name in [
                "direct",
                "cam_pose",
                "inv_cam_pose",
            ]:
                proj = projected[
                    name
                ]

                preview_rec[
                    name
                ] = draw_projection(
                    rgb,
                    None
                    if proj is None
                    else proj["xy"],
                    None
                    if proj is None
                    else proj["bbox"],
                    mask_bbox,
                    (
                        f"{name} "
                        f"IoU={rec[f'{name}_bbox_iou']:.3f}"
                    )
                )

            previews.append(
                preview_rec
            )

    result = pd.DataFrame(
        rows
    )

    out_csv = (
        OUT /
        "projection_convention_audit.csv"
    )

    result.to_csv(
        out_csv,
        index=False
    )

    print()
    print("BETA DIMENSIONS ACROSS 31 PILOT SEQUENCES")
    print("-" * 100)

    for dim, count in sorted(
        beta_dims.items()
    ):
        print(
            f"beta_dim={dim}: "
            f"{count} sequences"
        )

    print()
    print("CAMERA CONVENTION SUMMARY")
    print("-" * 100)

    summary = []

    for name in [
        "direct",
        "cam_pose",
        "inv_cam_pose",
    ]:
        arr = np.asarray(
            scores[name],
            dtype=np.float64
        )

        center_arr = result[
            f"{name}_center_error_norm"
        ].replace(
            [
                np.inf,
                -np.inf
            ],
            np.nan
        )

        print(
            f"{name:14s} | "
            f"bbox IoU median={np.median(arr):.4f} "
            f"mean={np.mean(arr):.4f} "
            f"| center err median={center_arr.median():.4f}"
        )

        summary.append(
            (
                name,
                float(
                    np.median(arr)
                )
            )
        )

    summary.sort(
        key=lambda x: x[1],
        reverse=True
    )

    best_name = summary[0][0]

    second_name = summary[1][0]

    best_score = summary[0][1]

    second_score = summary[1][1]

    print()
    print(
        "best convention:",
        best_name
    )

    print(
        "median IoU margin:",
        best_score
        -
        second_score
    )

    make_contact_sheet(
        previews
    )

    print()
    print(
        "CSV:",
        out_csv
    )

    print()
    print(
        "✅ geometry convention audit finished"
    )


