def rel(path):
    path = Path(path)

    try:
        return str(
            path.relative_to(ROOT)
        )

    except ValueError:
        return str(path)


def image_list(sequence):
    folder = (
        IMAGE_ROOT /
        sequence
    )

    files = []

    for pattern in [
        "*.jpg",
        "*.jpeg",
        "*.png",
        "*.JPG",
        "*.JPEG",
        "*.PNG",
    ]:
        files.extend(
            folder.glob(pattern)
        )

    files = sorted(
        set(files)
    )

    if not files:
        raise RuntimeError(
            f"No RGB images found: {folder}"
        )

    return files


def find_column(
    df,
    candidates,
):
    for name in candidates:
        if name in df.columns:
            return name

    return None


def build_candidate_pose_bin_lookup():
    pool = np.load(
        CANDIDATE_NPZ,
        allow_pickle=True,
    )

    descriptor_ids = (
        pool[
            "descriptor_index"
        ]
        .astype(np.int64)
    )

    lookup = {}

    for pose_bin in [
        "small",
        "medium",
        "large",
    ]:
        indptr = (
            pool[
                f"{pose_bin}_indptr"
            ]
            .astype(np.int64)
        )

        indices = (
            pool[
                f"{pose_bin}_indices"
            ]
            .astype(np.int64)
        )

        for src_pos in range(
            len(descriptor_ids)
        ):
            source_id = int(
                descriptor_ids[
                    src_pos
                ]
            )

            begin = int(
                indptr[
                    src_pos
                ]
            )

            end = int(
                indptr[
                    src_pos + 1
                ]
            )

            for tgt_pos in indices[
                begin:end
            ]:
                target_id = int(
                    descriptor_ids[
                        int(tgt_pos)
                    ]
                )

                key = (
                    source_id,
                    target_id,
                )

                if key in lookup:
                    if lookup[key] != pose_bin:
                        raise RuntimeError(
                            f"Pair appears in multiple pose bins: "
                            f"{key}"
                        )

                lookup[
                    key
                ] = pose_bin

    print(
        "candidate pose-bin relations:",
        len(lookup)
    )

    return lookup


def normalize_pair_manifest(
    csv_path,
    split_name,
    meta,
    pose_bin_lookup,
):
    raw = pd.read_csv(
        csv_path
    )

    source_col = find_column(
        raw,
        [
            "source_descriptor_index",
            "source_index",
            "source_idx",
            "src_descriptor_index",
            "src_index",
            "src_idx",
        ],
    )

    target_col = find_column(
        raw,
        [
            "target_descriptor_index",
            "target_index",
            "target_idx",
            "tgt_descriptor_index",
            "tgt_index",
            "tgt_idx",
        ],
    )

    # --------------------------------------------------------
    # Fallback:
    # recover descriptor ID from sequence + frame index.
    # --------------------------------------------------------

    meta_key = {
        (
            str(row.sequence),
            int(row.frame_index),
        ):
        int(row.descriptor_index)

        for row in meta.itertuples(
            index=False
        )
    }

    if (
        source_col is None
        or
        target_col is None
    ):
        seq_col = find_column(
            raw,
            [
                "sequence",
                "source_sequence",
            ],
        )

        source_frame_col = find_column(
            raw,
            [
                "source_frame_index",
                "source_frame",
                "src_frame_index",
            ],
        )

        target_frame_col = find_column(
            raw,
            [
                "target_frame_index",
                "target_frame",
                "tgt_frame_index",
            ],
        )

        if (
            seq_col is None
            or
            source_frame_col is None
            or
            target_frame_col is None
        ):
            raise RuntimeError(
                f"Cannot identify source/target IDs in "
                f"{csv_path}\n"
                f"columns={list(raw.columns)}"
            )

        source_ids = []
        target_ids = []

        for row in raw.itertuples(
            index=False
        ):
            seq = str(
                getattr(
                    row,
                    seq_col
                )
            )

            source_frame = int(
                getattr(
                    row,
                    source_frame_col
                )
            )

            target_frame = int(
                getattr(
                    row,
                    target_frame_col
                )
            )

            source_ids.append(
                meta_key[
                    (
                        seq,
                        source_frame,
                    )
                ]
            )

            target_ids.append(
                meta_key[
                    (
                        seq,
                        target_frame,
                    )
                ]
            )

    else:
        source_ids = (
            raw[
                source_col
            ]
            .astype(int)
            .tolist()
        )

        target_ids = (
            raw[
                target_col
            ]
            .astype(int)
            .tolist()
        )

    pose_col = find_column(
        raw,
        [
            "pose_bin",
            "pose_change_bin",
            "bin",
        ],
    )

    rows = []

    for i, (
        source_id,
        target_id
    ) in enumerate(
        zip(
            source_ids,
            target_ids,
        )
    ):
        if pose_col is not None:
            pose_bin = str(
                raw.iloc[
                    i
                ][
                    pose_col
                ]
            )

        else:
            pose_bin = (
                pose_bin_lookup.get(
                    (
                        int(source_id),
                        int(target_id),
                    )
                )
            )

            if pose_bin is None:
                raise RuntimeError(
                    f"Cannot recover pose bin for "
                    f"{source_id}->{target_id} "
                    f"in {csv_path}"
                )

        rows.append(
            {
                "pair_id":
                    i,

                "split":
                    split_name,

                "source_descriptor_index":
                    int(source_id),

                "target_descriptor_index":
                    int(target_id),

                "pose_bin":
                    pose_bin,
            }
        )

    return pd.DataFrame(
        rows
    )


