import csv
from collections import Counter, defaultdict
from pathlib import Path


ROOT = Path("/home/shangguanrz/project/pic-edit/add")

INPUT = (
    ROOT
    / "outputs/humanvid_assets_v1/pairs_v3/"
      "humanvid_single_pair_candidates_robust_v3.csv"
)

PREVIOUS_FINAL = (
    ROOT
    / "outputs/humanvid_assets_v1/final_single_v2/"
      "humanvid_single_pairs_final_v2.csv"
)

OUT_DIR = (
    ROOT
    / "outputs/humanvid_assets_v1/pairs_v3"
)

FINAL_OUT = (
    OUT_DIR
    / "humanvid_single_pairs_final_v3.csv"
)

UNMATCHED_OUT = (
    OUT_DIR
    / "humanvid_single_unmatched_sources_v3.csv"
)

TARGET_CAPACITY = 2


def read_csv(path):
    with path.open(
        "r",
        encoding="utf-8",
    ) as f:
        return list(
            csv.DictReader(f)
        )


def write_csv(path, rows):
    if not rows:
        return

    path.parent.mkdir(
        parents=True,
        exist_ok=True
    )

    with path.open(
        "w",
        newline="",
        encoding="utf-8",
    ) as f:
        writer = csv.DictWriter(
            f,
            fieldnames=rows[0].keys(),
            extrasaction="ignore",
        )

        writer.writeheader()
        writer.writerows(rows)


def quality_rank(row):
    q = row.get(
        "pair_quality",
        ""
    )

    table = {
        "clean_clean": 0,
        "clean_risk": 1,
        "risk_clean": 1,
        "risk_risk": 2,
    }

    return table.get(
        q,
        9,
    )


def candidate_sort_key(row):
    """
    source 内候选优先级：

    1. reliable 优于 uncertain
    2. 更短时间间隔
    3. 更高图像质量
    4. clear 优于 acceptable
    5. pose change 更强一些作为最终 tie-break
    """

    uncertain = int(
        float(
            row.get(
                "pose_metric_uncertain",
                1
            )
        )
    )

    gap = float(
        row[
            "time_gap_sec"
        ]
    )

    qrank = quality_rank(
        row
    )

    strength = row.get(
        "pose_change_strength",
        ""
    )

    strength_rank = (
        0
        if strength == "clear"
        else 1
    )

    bmed = float(
        row.get(
            "bone_angle_median_deg",
            0
        )
        or 0
    )

    jmed = float(
        row.get(
            "joint_angle_median_deg",
            0
        )
        or 0
    )

    tgt_time = float(
        row.get(
            "target_timestamp_sec",
            0
        )
        or 0
    )

    return (
        uncertain,
        gap,
        qrank,
        strength_rank,
        -bmed,
        -jmed,
        tgt_time,
        row[
            "target_frame_path"
        ],
    )


def main():
    OUT_DIR.mkdir(
        parents=True,
        exist_ok=True
    )

    rows = read_csv(
        INPUT
    )

    eligible = [
        dict(r)
        for r in rows
        if r.get(
            "robust_pair_eligible",
            ""
        ) == "1"
    ]

    all_sources = sorted(
        set(
            r[
                "source_frame_path"
            ]
            for r in rows
        )
    )

    prefs = defaultdict(
        list
    )

    for row in eligible:
        prefs[
            row[
                "source_frame_path"
            ]
        ].append(
            row
        )

    # 每个 source 对候选排序并记录 rank
    for source, cand in prefs.items():
        cand.sort(
            key=candidate_sort_key
        )

        for rank, row in enumerate(
            cand,
            1
        ):
            row[
                "source_candidate_rank"
            ] = rank

    # 稀缺 source 优先开始 augmenting matching
    source_order = sorted(
        prefs.keys(),
        key=lambda s: (
            len(
                prefs[s]
            ),
            prefs[s][0].get(
                "split",
                ""
            ),
            prefs[s][0].get(
                "video_id",
                ""
            ),
            float(
                prefs[s][0].get(
                    "source_timestamp_sec",
                    0
                )
                or 0
            ),
            s,
        )
    )

    matched = {}
    target_sources = defaultdict(
        list
    )

    def try_assign(
        source,
        seen_targets,
    ):
        for edge in prefs[
            source
        ]:
            target = edge[
                "target_frame_path"
            ]

            if target in seen_targets:
                continue

            seen_targets.add(
                target
            )

            occupants = (
                target_sources[
                    target
                ]
            )

            # target 还有容量
            if (
                len(
                    occupants
                )
                < TARGET_CAPACITY
            ):
                occupants.append(
                    source
                )

                matched[
                    source
                ] = edge

                return True

            # target 满了：
            # 尝试把已有 source 挪到它们的下一个候选
            current = list(
                occupants
            )

            # 优先挪走当前使用较后候选的 source
            current.sort(
                key=lambda s:
                int(
                    matched[
                        s
                    ][
                        "source_candidate_rank"
                    ]
                ),
                reverse=True,
            )

            for old_source in current:
                if try_assign(
                    old_source,
                    seen_targets,
                ):
                    target_sources[
                        target
                    ].remove(
                        old_source
                    )

                    target_sources[
                        target
                    ].append(
                        source
                    )

                    matched[
                        source
                    ] = edge

                    return True

        return False

    for source in source_order:
        try_assign(
            source,
            set(),
        )

    final_rows = []

    # 最终 target usage
    target_usage = Counter(
        edge[
            "target_frame_path"
        ]
        for edge in matched.values()
    )

    for idx, (
        source,
        row,
    ) in enumerate(
        sorted(
            matched.items(),
            key=lambda x: (
                x[1].get(
                    "split",
                    ""
                ),
                x[1].get(
                    "video_id",
                    ""
                ),
                float(
                    x[1].get(
                        "source_timestamp_sec",
                        0
                    )
                    or 0
                ),
                x[0],
            )
        ),
        1,
    ):
        rr = dict(
            row
        )

        target = rr[
            "target_frame_path"
        ]

        rr.update({
            "final_pair_id":
                f"humanvid_single_v3_{idx:06d}",

            "matching_method":
                "capacity_bmatching",

            "source_capacity":
                1,

            "target_capacity":
                TARGET_CAPACITY,

            "target_usage_final":
                target_usage[
                    target
                ],
        })

        final_rows.append(
            rr
        )

    write_csv(
        FINAL_OUT,
        final_rows
    )

    matched_sources = set(
        matched.keys()
    )

    unmatched_rows = []

    for source in all_sources:
        if source in matched_sources:
            continue

        cand = prefs.get(
            source,
            []
        )

        if not cand:
            reason = (
                "no_robust_eligible_candidate"
            )

            split = ""
            video_id = ""
            source_frame_id = ""

            for r in rows:
                if (
                    r[
                        "source_frame_path"
                    ]
                    == source
                ):
                    split = r.get(
                        "split",
                        ""
                    )

                    video_id = r.get(
                        "video_id",
                        ""
                    )

                    source_frame_id = (
                        r.get(
                            "source_frame_id",
                            ""
                        )
                    )

                    break

        else:
            reason = (
                "capacity_unmatched"
            )

            split = cand[
                0
            ].get(
                "split",
                ""
            )

            video_id = cand[
                0
            ].get(
                "video_id",
                ""
            )

            source_frame_id = (
                cand[
                    0
                ].get(
                    "source_frame_id",
                    ""
                )
            )

        unmatched_rows.append({
            "source_frame_id":
                source_frame_id,

            "source_frame_path":
                source,

            "split":
                split,

            "video_id":
                video_id,

            "robust_candidate_count":
                len(cand),

            "unmatched_reason":
                reason,
        })

    write_csv(
        UNMATCHED_OUT,
        unmatched_rows
    )

    # --------------------------------------------------
    # Exposure audit
    # --------------------------------------------------
    source_count = Counter(
        r[
            "source_frame_path"
        ]
        for r in final_rows
    )

    target_count = Counter(
        r[
            "target_frame_path"
        ]
        for r in final_rows
    )

    all_used_frames = (
        set(
            source_count
        )
        |
        set(
            target_count
        )
    )

    total_count = {
        frame:
        (
            source_count[
                frame
            ]
            +
            target_count[
                frame
            ]
        )
        for frame in all_used_frames
    }

    source_over_1 = sum(
        v > 1
        for v in source_count.values()
    )

    target_over_2 = sum(
        v > TARGET_CAPACITY
        for v in target_count.values()
    )

    total_over_3 = sum(
        v > 3
        for v in total_count.values()
    )

    # --------------------------------------------------
    # Compare with previous V2
    # --------------------------------------------------
    previous = []

