import csv
from collections import Counter, defaultdict
from pathlib import Path


ROOT = Path("/home/shangguanrz/project/pic-edit/add")

INPUT = (
    ROOT
    / "outputs/humanvid_assets_v1/pairs_v4/"
      "humanvid_single_directed_candidates_v4.csv"
)

V2_FINAL = (
    ROOT
    / "outputs/humanvid_assets_v1/final_single_v2/"
      "humanvid_single_pairs_final_v2.csv"
)

OUT_DIR = (
    ROOT
    / "outputs/humanvid_assets_v1/pairs_v4"
)

FINAL_OUT = (
    OUT_DIR
    / "humanvid_single_pairs_final_v4.csv"
)

UNMATCHED_OUT = (
    OUT_DIR
    / "humanvid_single_unmatched_sources_v4.csv"
)

EXPOSURE_OUT = (
    OUT_DIR
    / "humanvid_single_frame_exposure_v4.csv"
)

TARGET_CAPACITY = 2


def read_csv(path):
    with path.open(
        "r",
        encoding="utf-8",
    ) as f:
        return list(
            csv.DictReader(f)
        )


def write_csv(path, rows):
    if not rows:
        return

    path.parent.mkdir(
        parents=True,
        exist_ok=True
    )

    with path.open(
        "w",
        newline="",
        encoding="utf-8",
    ) as f:
        writer = csv.DictWriter(
            f,
            fieldnames=rows[0].keys(),
            extrasaction="ignore",
        )

        writer.writeheader()
        writer.writerows(rows)


def quality_rank(row):
    table = {
        "clean_clean": 0,
        "clean_risk": 1,
        "risk_clean": 1,
        "risk_risk": 2,
    }

    return table.get(
        row.get(
            "pair_quality",
            ""
        ),
        9,
    )


def candidate_sort_key(row):
    """
    一个 source 内的 target 优先级：

    1. reliable pose metric
    2. 更短时间距离
    3. 更好的 frame quality
    4. clear 优于 acceptable
    5. 更大的 robust pose change 作 tie-break
    """

    uncertain = int(
        float(
            row.get(
                "pose_metric_uncertain",
                1
            )
            or 1
        )
    )

    gap = float(
        row.get(
            "time_gap_sec",
            999
        )
        or 999
    )

    strength_rank = (
        0
        if row.get(
            "pose_change_strength",
            ""
        ) == "clear"
        else 1
    )

    bmed = float(
        row.get(
            "bone_angle_median_deg",
            0
        )
        or 0
    )

    jmed = float(
        row.get(
            "joint_angle_median_deg",
            0
        )
        or 0
    )

    return (
        uncertain,
        gap,
        quality_rank(
            row
        ),
        strength_rank,
        -bmed,
        -jmed,
        row[
            "target_frame_path"
        ],
    )


def main():
    OUT_DIR.mkdir(
        parents=True,
        exist_ok=True
    )

    rows = read_csv(
        INPUT
    )

    eligible = [
        dict(r)
        for r in rows
        if r.get(
            "robust_pair_eligible",
            ""
        ) == "1"
    ]

    prefs = defaultdict(
        list
    )

    for row in eligible:
        source = row[
            "source_frame_path"
        ]

        target = row[
            "target_frame_path"
        ]

        if source == target:
            continue

        prefs[
            source
        ].append(
            row
        )

    # --------------------------------------------------
    # source 内排序
    # --------------------------------------------------
    for source in prefs:
        prefs[
            source
        ].sort(
            key=candidate_sort_key
        )

        for rank, row in enumerate(
            prefs[source],
            1
        ):
            row[
                "source_candidate_rank"
            ] = rank

    # 候选越少的 source 越先处理
    source_order = sorted(
        prefs.keys(),
        key=lambda s: (
            len(
                prefs[s]
            ),
            prefs[s][0].get(
                "split",
                ""
            ),
            prefs[s][0].get(
                "video_id",
                ""
            ),
            float(
                prefs[s][0].get(
                    "source_timestamp_sec",
                    0
                )
                or 0
            ),
            s,
        )
    )

    matched = {}

    target_sources = defaultdict(
        list
    )

    def try_assign(
        source,
        seen_targets,
        seen_sources,
    ):
        if source in seen_sources:
            return False

        seen_sources.add(
            source
        )

        for edge in prefs[
            source
        ]:
            target = edge[
                "target_frame_path"
            ]

            if target in seen_targets:
                continue

            seen_targets.add(
                target
            )

            occupants = (
                target_sources[
                    target
                ]
            )

            # target 还有容量
            if len(
                occupants
            ) < TARGET_CAPACITY:

                occupants.append(
                    source
                )

                matched[
                    source
                ] = edge

                return True

            # target 满：
            # 尝试把已有 source 换到下一合法 target
            old_sources = list(
                occupants
            )

            old_sources.sort(
                key=lambda s: int(
                    matched[
                        s
                    ][
                        "source_candidate_rank"
                    ]
                ),
                reverse=True,
            )

            for old_source in old_sources:
                child_seen_targets = set(
                    seen_targets
                )

                child_seen_sources = set(
                    seen_sources
                )

                if try_assign(
                    old_source,
                    child_seen_targets,
                    child_seen_sources,
                ):
                    target_sources[
                        target
                    ].remove(
                        old_source
                    )

                    target_sources[
                        target
                    ].append(
                        source
                    )

                    matched[
                        source
                    ] = edge

                    return True

        return False

    for source in source_order:
        try_assign(
            source,
            set(),
            set(),
        )

    # --------------------------------------------------
    # Final rows
    # --------------------------------------------------
    final_rows = []

    target_count = Counter(
        edge[
            "target_frame_path"
        ]
        for edge in matched.values()
    )

    ordered = sorted(
        matched.items(),
        key=lambda x: (
            x[1].get(
                "split",
                ""
            ),
            x[1].get(
                "video_id",
                ""
            ),
            x[1].get(
                "segment_id",
                ""
            ),
            float(
                x[1].get(
                    "source_timestamp_sec",
                    0
                )
                or 0
            ),
            x[0],
        )
    )

    for idx, (
        source,
        row,
    ) in enumerate(
        ordered,
        1
    ):
        rr = dict(
            row
        )

        rr.update({
            "final_pair_id":
                f"humanvid_single_v4_{idx:06d}",

            "matching_method":
                "directed_capacity_bmatching",

            "source_capacity":
                1,

            "target_capacity":
                TARGET_CAPACITY,

            "target_usage_final":
                target_count[
                    row[
                        "target_frame_path"
                    ]
                ],
        })

        final_rows.append(
            rr
        )

    write_csv(
        FINAL_OUT,
        final_rows
    )

    # --------------------------------------------------
    # Unmatched
    # --------------------------------------------------
    matched_sources = set(
        matched.keys()
    )

    unmatched_rows = []

    for source in source_order:
        if source in matched_sources:
            continue

        unmatched_rows.append({
            "source_frame_path":
                source,

            "split":
                prefs[source][0].get(
                    "split",
                    ""
                ),

            "video_id":
                prefs[source][0].get(
                    "video_id",
                    ""
                ),

            "segment_id":
                prefs[source][0].get(
                    "segment_id",
                    ""
                ),

            "robust_candidate_count":
                len(
                    prefs[source]
                ),

            "unmatched_reason":
                "capacity_unmatched",
        })

    write_csv(
        UNMATCHED_OUT,
        unmatched_rows
    )

    # --------------------------------------------------
    # Exposure
    # --------------------------------------------------
    source_count = Counter(
        r[
            "source_frame_path"
        ]
        for r in final_rows
    )

    target_count = Counter(
        r[
            "target_frame_path"
        ]
        for r in final_rows
    )

    all_used = sorted(
        set(
            source_count
        )
        |
        set(
            target_count
        )
    )

    exposure_rows = []

    for frame in all_used:
        s = source_count[
            frame
        ]

        t = target_count[
            frame
        ]

        exposure_rows.append({
            "frame_path":
                frame,

            "source_count":
                s,

            "target_count":
                t,

            "total_count":
                s + t,
        })

    write_csv(
        EXPOSURE_OUT,
        exposure_rows
    )

    source_over_1 = sum(
        r[
            "source_count"
        ] > 1
        for r in exposure_rows
    )

    target_over_2 = sum(
        r[
            "target_count"
        ] > 2
        for r in exposure_rows
    )

    total_over_3 = sum(
        r[
            "total_count"
        ] > 3
        for r in exposure_rows
    )

    # --------------------------------------------------
    # Reciprocal pair audit
    # A→B 和 B→A 都允许，但统计出来。
    # --------------------------------------------------
    pair_set = set(
        (
            r[
                "source_frame_path"
            ],
            r[
                "target_frame_path"
            ],
        )
        for r in final_rows
    )

    reciprocal_directed = sum(
        (
            b,
            a,
        )
        in pair_set
        for (
            a,
            b,
        )
        in pair_set
    )

    reciprocal_relations = (
        reciprocal_directed
        // 2
    )

    # --------------------------------------------------
    # Compare V2
    # --------------------------------------------------
    v2 = read_csv(
        V2_FINAL
    )

    old_by_source = {
        r[
            "source_frame_path"
        ]:
        r[
            "target_frame_path"
        ]
        for r in v2
    }

    new_by_source = {
        r[
            "source_frame_path"
        ]:
        r[
            "target_frame_path"
        ]
        for r in final_rows
    }

    old_sources = set(
        old_by_source
    )

    new_sources = set(
        new_by_source
    )

    common_sources = (
        old_sources
        &
        new_sources
    )

    same_target = sum(
        old_by_source[s]
        ==
        new_by_source[s]
        for s in common_sources
    )

    changed_target = (
        len(
            common_sources
        )
        -
        same_target
    )

    newly_matched = len(
        new_sources
        -
        old_sources
    )

    v2_sources_lost = len(
        old_sources
        -
        new_sources
    )

    rank_counter = Counter(
        int(
            r[
                "source_candidate_rank"
            ]
        )
        for r in final_rows
    )

    print("=" * 80)
    print(
        "HumanVid Final Directed Capacity Matching V4"
    )
    print("=" * 80)

    print(
        "directed candidates     :",
        len(rows)
    )

    print(
        "robust eligible edges   :",
        len(eligible)
    )

    print(
        "sources with candidates :",
        len(prefs)
    )

    print(
        "matched sources         :",
        len(final_rows)
    )

    print(
        "capacity unmatched      :",
        len(unmatched_rows)
    )

    print()

    print(
        "candidate rank used:"
    )

    for rank in sorted(
        rank_counter
    )[:10]:
        print(
            f"  rank {rank}:",
            rank_counter[
                rank
            ]
        )

    print(
        "  rank >=3:",
        sum(
            count
            for rank, count
            in rank_counter.items()
            if rank >= 3
        )
    )

    print()

    print(
        "target usage:"
    )

    usage = Counter(
        target_count.values()
    )

    for n in sorted(
        usage
    ):
        print(
            f"  used {n}x:",
            usage[n],
            "targets"
        )

    print(
        "  max:",
