def get_targets(
    source,
    bin_name,
):

    indptr = pool[
        f"{bin_name}_indptr"
    ]

    indices = pool[
        f"{bin_name}_indices"
    ]

    start = int(
        indptr[source]
    )

    end = int(
        indptr[source + 1]
    )

    return indices[
        start:end
    ].astype(
        np.int64,
        copy=False
    )


