# ============================================================
# DWPose raw-row mapping
#
# raw.npz rows follow the sorted render-frame list in the
# existing handoff pipeline.
#
# Before relying on it for new pairs, validate this assumption
# against ALL 525 retained validation pairs.
# ============================================================

dwpose_row_cache = {}


def get_dwpose_row_map(
    split,
    seq,
):

    key = (
        split,
        seq
    )

    if key in dwpose_row_cache:
        return dwpose_row_cache[
            key
        ]

    render_dir = (
        DWPOSE_ROOT /
        split /
        seq /
        "renders"
    )

    files = sorted(
        render_dir.glob(
            "*.png"
        ),
        key=lambda p: int(
            p.stem
        )
    )

    if not files:
        raise RuntimeError(
            f"No DWPose renders: {render_dir}"
        )

    mapping = {
        int(p.stem): i
        for i, p
        in enumerate(files)
    }

    dwpose_row_cache[
        key
    ] = mapping

    return mapping


