# Old version repeatedly scanned all candidates for every one
# of the 75 replacements. That was correct but extremely slow.
# ------------------------------------------------------------

candidate_cache = {}

sequence_bin_sources = {
    seq: {
        bin_name: []
        for bin_name in BINS
    }
    for seq in sequences
}

print()
print(
    "Precomputing eligible validation candidates..."
)

total_cached_edges = 0

for seq_i, seq in enumerate(
    sequences,
    1
):

    for source in sequence_sources[
        seq
    ]:

        source = int(
            source
        )

        for bin_name in BINS:

            targets = get_targets(
                source,
                bin_name
            )

            if len(targets) == 0:
                continue

            targets = np.asarray(
                targets,
                dtype=np.int64
            )

            good = (
                eligible_mask[
                    targets
                ]
                &
                (
                    split_arr[
                        targets
                    ]
                    ==
                    "validation"
                )
                &
                (
                    sequence_arr[
                        targets
                    ]
                    ==
                    seq
                )
                &
                (
                    targets
                    !=
                    source
                )
            )

            targets = targets[
                good
            ]

            if len(targets) == 0:
                continue

            candidate_cache[
                (
                    source,
                    bin_name
                )
            ] = targets

            sequence_bin_sources[
                seq
            ][
                bin_name
            ].append(
                source
            )

            total_cached_edges += int(
                len(
                    targets
                )
            )

    print(
        f"  [{seq_i:02d}/{len(sequences):02d}] "
        f"{seq}"
    )


print(
    "cached source/bin entries:",
    len(candidate_cache)
)

print(
    "cached candidate edges:",
    total_cached_edges
