def filtered_targets(
    source,
    bin_name,
):

    targets = candidate_cache.get(
        (
            int(source),
            str(bin_name)
        )
    )

    if targets is None:
        return np.empty(
            0,
            dtype=np.int64
        )

    # Only pair_usage changes during replacement.
    # Everything else has already been prefiltered.
    if not pair_usage:
        return targets

    keep = np.fromiter(
        (
            (
                int(source),
                int(t)
            )
            not in pair_usage

            for t in targets
        ),
        dtype=bool,
        count=len(targets)
    )

    return targets[
        keep
    ]


def choose_replacement(
    bin_name,
):

    # --------------------------------------------------------
    # Find sequences that actually support this pose bin.
    # Candidate existence itself is already precomputed.
    # --------------------------------------------------------

    viable_sequences = [
        seq
        for seq in sequences
        if len(
            sequence_bin_sources[
                seq
            ][
                bin_name
            ]
        ) > 0
    ]

    if not viable_sequences:
        raise RuntimeError(
            f"No viable sequence for bin={bin_name}"
        )

    # --------------------------------------------------------
    # Keep replacement load balanced across remaining
    # validation sequences.
    # --------------------------------------------------------

    min_seq_usage = min(
        sequence_pair_usage[
            seq
        ]
        for seq in viable_sequences
    )

    seq_candidates = [
        seq
        for seq in viable_sequences
        if sequence_pair_usage[
            seq
        ]
        ==
        min_seq_usage
    ]

    rng.shuffle(
        seq_candidates
    )

    # Normally the first sequence works.
    # Try the others as a safe fallback.
    for seq in seq_candidates:

        sources = list(
            sequence_bin_sources[
                seq
            ][
                bin_name
            ]
        )

        if not sources:
            continue

        # ----------------------------------------------------
        # Original policy:
        # prefer source with minimum current reuse.
        # ----------------------------------------------------

        min_source_usage = min(
            source_usage[
                int(s)
            ]
            for s in sources
        )

        preferred_sources = [
            int(s)
            for s in sources
            if source_usage[
                int(s)
            ]
            ==
            min_source_usage
        ]

        rng.shuffle(
            preferred_sources
        )

        # If a rare source happens to have all its directed
        # candidate pairs already used, try another source.
        for source in preferred_sources:

            targets = filtered_targets(
                source,
                bin_name
            )

            if len(targets) == 0:
                continue

            # -----------------------------------------------
            # Original policy:
            # prefer least-used target.
            # -----------------------------------------------

            target_use = np.fromiter(
                (
                    target_usage[
                        int(t)
                    ]
                    for t in targets
                ),
                dtype=np.int64,
                count=len(targets)
            )

            min_target_usage = int(
                target_use.min()
            )

            preferred_targets = targets[
                target_use
                ==
                min_target_usage
            ].copy()

            rng.shuffle(
                preferred_targets
            )

            target = int(
                preferred_targets[
                    0
                ]
            )

            return (
                seq,
                source,
                target,
            )

    # --------------------------------------------------------
    # Extremely conservative fallback:
    # try every viable sequence/source if the min-usage group
    # happened to be exhausted.
    # --------------------------------------------------------

    all_sequences = viable_sequences.copy()

    rng.shuffle(
        all_sequences
    )

    for seq in all_sequences:

        sources = list(
            sequence_bin_sources[
                seq
            ][
                bin_name
            ]
        )

        sources.sort(
            key=lambda s: source_usage[
                int(s)
            ]
        )

        for source in sources:

            source = int(
                source
            )

            targets = filtered_targets(
                source,
                bin_name
            )

            if len(targets) == 0:
                continue

            target_use = np.fromiter(
                (
                    target_usage[
                        int(t)
                    ]
                    for t in targets
                ),
                dtype=np.int64,
                count=len(targets)
            )

            min_target_usage = int(
                target_use.min()
            )

            preferred_targets = targets[
                target_use
                ==
                min_target_usage
            ].copy()

            rng.shuffle(
                preferred_targets
            )

            return (
                seq,
                source,
                int(
                    preferred_targets[
                        0
                    ]
                ),
            )

    raise RuntimeError(
        f"Could not choose replacement "
        f"for bin={bin_name}"
    )


# ============================================================
# Build 75 replacements
