        spec[
            "source_frame_index"
        ]
    )

    tf = int(
        spec[
            "target_frame_index"
        ]
    )

    split = "validation"

    dw_map = get_dwpose_row_map(
        split,
        seq
    )

    if sf not in dw_map:
        raise RuntimeError(
            f"DWPose source missing: "
            f"{seq} frame={sf}"
        )

    if tf not in dw_map:
        raise RuntimeError(
            f"DWPose target missing: "
            f"{seq} frame={tf}"
        )

    row = {
        "pair_id":
            pair_id,

        "split":
            split,

        "sequence":
            seq,

        "pose_bin":
            pose_bin,

        "source_descriptor_index":
            sd,

        "target_descriptor_index":
            td,

        "source_frame_index":
            sf,

