            ),

        "source_dwpose_render":
            rel(
                DWPOSE_ROOT /
                split /
                seq /
                "renders" /
                f"{sf:06d}.png"
            ),

        "target_dwpose_render":
            rel(
                DWPOSE_ROOT /
                split /
                seq /
                "renders" /
                f"{tf:06d}.png"
            ),

        "source_dwpose_raw_npz":
            rel(
                DWPOSE_ROOT /
                split /
                seq /
                "raw.npz"
            ),

        "source_dwpose_raw_row":
            int(
                dw_map[
                    sf
                ]
            ),

        "target_dwpose_raw_npz":
            rel(
                DWPOSE_ROOT /
                split /
                seq /
                "raw.npz"
            ),

        "target_dwpose_raw_row":
            int(
