def add_geometry_paths(
    df,
):

    out = df.copy()

    s_depth = []
    t_depth = []

    s_normal = []
    t_normal = []

    provenance = []

    for r in out.itertuples(
        index=False
    ):

        split = str(
            r.split
        )

        seq = str(
            r.sequence
        )

        sf = int(
            r.source_frame_index
        )

        tf = int(
            r.target_frame_index
        )

        sdp = (
            GEOM_ROOT /
            "depth_mm" /
            split /
            seq /
            f"{sf:06d}.png"
        )

        tdp = (
            GEOM_ROOT /
            "depth_mm" /
            split /
            seq /
            f"{tf:06d}.png"
        )

        snp = (
            GEOM_ROOT /
            "normal" /
            split /
            seq /
            f"{sf:06d}.png"
        )

        tnp = (
            GEOM_ROOT /
            "normal" /
            split /
            seq /
            f"{tf:06d}.png"
        )

        for p in [
            sdp,
            tdp,
            snp,
            tnp,
        ]:

            if not p.exists():
                raise FileNotFoundError(
                    p
                )

        s_depth.append(
            rel(
                sdp
            )
        )

        t_depth.append(
            rel(
                tdp
            )
        )

        s_normal.append(
            rel(
                snp
            )
        )

        t_normal.append(
            rel(
                tnp
            )
        )

        provenance.append(
            "3dpw_official_smpl_camera"
        )

    out[
        "source_depth"
    ] = s_depth

    out[
        "target_depth"
    ] = t_depth

    out[
        "source_normal"
    ] = s_normal

    out[
        "target_normal"
    ] = t_normal

    out[
        "geometry_provenance"
    ] = provenance

    return out


