def verify_manifest(
    name,
    df,
):

    missing = []

    for col in asset_cols:

        if col not in df.columns:
            raise RuntimeError(
                f"{name}: missing column {col}"
            )

        for i, x in enumerate(
            df[
                col
            ].astype(str)
        ):

            p = ROOT / x

            if not p.exists():

                missing.append(
                    (
                        i,
                        col,
                        x,
                    )
                )

                if len(missing) >= 20:
                    break

        if len(missing) >= 20:
            break

    if missing:

        print(
            f"{name} first missing files:"
        )

        for x in missing:
            print(x)

        raise RuntimeError(
            f"{name}: missing assets"
        )

    print(
        f"✅ {name}: all referenced assets exist "
        f"({len(df)} pairs)"
    )


