rows = []

sequence_rows = []

global_counts = Counter()

for seq_idx, (
    split,
    pkl_path
) in enumerate(
    sequences,
    1
):
    with open(
        pkl_path,
        "rb"
    ) as f:
        data = pickle.load(
            f,
            encoding="latin1"
        )

    sequence = str(
        data["sequence"]
    )

    frame_ids = np.asarray(
        data["img_frame_ids"]
    )

    poses2d = np.asarray(
        data["poses2d"][0]
    )

    campose_valid = np.asarray(
        data["campose_valid"][0]
    ).reshape(-1)

    images = get_images(
        sequence
    )

    lookup = make_image_lookup(
        images
    )

    paths = []

    valid_indices = []

    for frame_index, frame_id in enumerate(
        frame_ids
    ):
        path = resolve_image_path(
            frame_id,
            frame_index,
            images,
            lookup
        )

        if (
            path is not None
            and os.path.isfile(path)
        ):
            paths.append(
                path
            )

            valid_indices.append(
                frame_index
            )

    print(
        f"[{seq_idx:02d}/{len(sequences)}] "
        f"{split:10s} "
        f"{sequence:35s} "
        f"frames={len(paths)}"
    )

    seq_rows = []

    for chunk_start in range(
        0,
        len(paths),
        BATCH_SIZE
    ):
        chunk_paths = paths[
            chunk_start:
            chunk_start
            + BATCH_SIZE
        ]

        chunk_indices = valid_indices[
            chunk_start:
            chunk_start
            + BATCH_SIZE
        ]

        results = model.predict(
            source=chunk_paths,
            classes=[0],
            conf=YOLO_CONF,
            iou=YOLO_IOU,
            imgsz=YOLO_IMGSZ,
            device=DEVICE,
            half=bool(
                torch.cuda.is_available()
            ),
            verbose=False,
            save=False,
        )

        for frame_index, path, result in zip(
            chunk_indices,
            chunk_paths,
            results
        ):
            image = result.orig_img

            height, width = image.shape[
                :2
            ]

            frame_id = int(
                frame_ids[
                    frame_index
                ]
            )

            pose2d = (
                poses2d[
                    frame_index
                ]
                if frame_index
                < len(
                    poses2d
                )
                else None
            )

            pose = pose_information(
                pose2d,
                width,
                height
            )

            if result.boxes is not None:
                boxes = (
                    result.boxes.xyxy
                    .detach()
                    .cpu()
                    .numpy()
                )

                confs = (
                    result.boxes.conf
                    .detach()
                    .cpu()
                    .numpy()
                )
            else:
                boxes = np.empty(
                    (
                        0,
                        4
                    ),
                    dtype=float
                )

                confs = np.empty(
                    (
                        0,
                    ),
                    dtype=float
                )

            detected_people = len(
                boxes
            )

            main_idx, match_iou = (
                choose_main_person(
                    boxes,
                    pose[
                        "pose_bbox"
                    ]
                )
            )

            main_bbox = None

            main_conf = np.nan

            area_ratio = np.nan

            border_touch = False

            person_sharpness = np.nan

            head_sharpness = np.nan

            if main_idx is not None:
                main_bbox = boxes[
                    main_idx
                ]

                main_conf = float(
                    confs[
                        main_idx
                    ]
                )

                area_ratio = (
                    bbox_area(
                        main_bbox
                    )
                    / float(
                        width * height
                    )
                )

                x1, y1, x2, y2 = clamp_bbox(
                    main_bbox,
                    width,
                    height
                )

                edge_x = (
                    0.02 * width
                )

                edge_y = (
                    0.02 * height
                )

                border_touch = bool(
                    x1 <= edge_x
                    or y1 <= edge_y
                    or x2 >= (
                        width - edge_x
                    )
                    or y2 >= (
                        height - edge_y
                    )
                )

                person_crop = image[
                    y1:y2,
                    x1:x2
                ]

                person_sharpness = (
                    laplacian_variance(
                        person_crop
                    )
                )

                # 用 person bbox 顶部 30%
                # 作为稳定的 head proxy
                head_y2 = y1 + int(
                    0.30 * (
                        y2 - y1
                    )
                )

                head_y2 = max(
                    y1 + 1,
                    head_y2
                )

                head_crop = image[
                    y1:head_y2,
                    x1:x2
                ]

                head_sharpness = (
                    laplacian_variance(
                        head_crop
                    )
                )

            campose_ok = (
                int(
                    campose_valid[
                        frame_index
                    ]
                    > 0
                )
                if frame_index
                < len(
                    campose_valid
                )
                else -1
            )

            reasons = []

            if detected_people == 0:
                reasons.append(
                    "no_person_detected"
                )

            if detected_people >= 2:
                reasons.append(
                    "multiple_people_detected"
                )

            if (
                np.isfinite(
                    area_ratio
                )
                and area_ratio
                < MIN_PERSON_AREA
            ):
                reasons.append(
                    "person_too_small"
                )

            if (
                pose[
                    "visible_body_joints"
                ]
                < MIN_BODY_JOINTS
            ):
                reasons.append(
                    "low_pose_visibility"
                )

            if (
                pose[
                    "limb_coverage"
                ]
                < MIN_LIMB_COVERAGE
            ):
                reasons.append(
                    "low_limb_coverage"
                )

            structural_candidate = int(
                detected_people == 1
                and main_idx is not None
                and np.isfinite(
                    area_ratio
                )
                and area_ratio
                >= MIN_PERSON_AREA
                and pose[
                    "visible_body_joints"
                ]
                >= MIN_BODY_JOINTS
                and pose[
                    "limb_coverage"
                ]
                >= MIN_LIMB_COVERAGE
            )

            row = {
                "split": split,
                "sequence": sequence,
                "frame_index": frame_index,
                "frame_id": frame_id,
                "image_path": path,

                "width": width,
                "height": height,

                "detected_people": (
                    detected_people
                ),

                "main_person_conf": (
                    round(
                        main_conf,
                        6
                    )
                    if np.isfinite(
                        main_conf
                    )
                    else ""
                ),

                "main_pose_bbox_iou": (
                    round(
                        match_iou,
                        6
                    )
                    if np.isfinite(
                        match_iou
                    )
                    else ""
                ),

                "person_area_ratio": (
                    round(
                        area_ratio,
                        6
                    )
                    if np.isfinite(
                        area_ratio
                    )
                    else ""
                ),

                "border_touch": int(
                    border_touch
                ),

                "visible_joints": pose[
                    "visible_joints"
                ],

                "visible_body_joints": pose[
                    "visible_body_joints"
                ],

                "limb_coverage": round(
                    pose[
                        "limb_coverage"
                    ],
                    6
                ),

                "wrists_visible": pose[
                    "wrists_visible"
                ],

                "ankles_visible": pose[
                    "ankles_visible"
                ],

                "person_sharpness": (
                    round(
                        person_sharpness,
                        4
                    )
                    if np.isfinite(
                        person_sharpness
                    )
                    else ""
                ),

                "head_sharpness": (
                    round(
                        head_sharpness,
                        4
                    )
                    if np.isfinite(
                        head_sharpness
                    )
                    else ""
                ),

                "campose_valid": (
                    campose_ok
                ),

                "structural_candidate": (
                    structural_candidate
                ),

                "basic_reject_reason": (
                    ";".join(
                        reasons
                    )
                ),
            }

            rows.append(
                row
            )

            seq_rows.append(
                row
