def safe_mean(values):
    values = np.asarray(
        values,
        dtype=np.float64,
    )

    values = values[
        np.isfinite(values)
    ]

    if len(values) == 0:
        return float("nan")

    return float(
        np.mean(values)
    )


def safe_median(values):
    values = np.asarray(
        values,
        dtype=np.float64,
    )

    values = values[
        np.isfinite(values)
    ]

    if len(values) == 0:
        return float("nan")

    return float(
        np.median(values)
    )


def safe_percentile(
    values,
    q,
):
    values = np.asarray(
        values,
        dtype=np.float64,
    )

    values = values[
        np.isfinite(values)
    ]

    if len(values) == 0:
        return float("nan")

    return float(
        np.percentile(
            values,
            q,
        )
    )


def find_human_model_root():
    candidates = [
        SMPL_ROOT / "human_model_files",
        SMPL_ROOT / "human_models",
        SMPL_ROOT / "pretrained_models/human_model_files",
        SMPL_ROOT / "common/utils/human_model_files",
    ]

    for root in candidates:
        marker = (
            root
            / "smplx"
            / "SMPLX_to_J14.pkl"
        )

        if marker.exists():
            return root

    # Fallback: search only inside SMPLest-X.
    for marker in SMPL_ROOT.rglob(
        "SMPLX_to_J14.pkl"
    ):
        if (
            marker.parent.name.lower()
            == "smplx"
        ):
            return marker.parent.parent

    raise RuntimeError(
        "Cannot locate SMPL-X human_model_files"
    )


def select_valid_dwpose_person(
    keypoints,
    scores,
):
    valid = []

    for person_idx in range(
        keypoints.shape[0]
    ):
        body_scores = scores[
            person_idx,
            :18,
        ]

        body_visible_03 = int(
            (
                body_scores
                >= 0.30
            ).sum()
        )

        body_mean_conf = float(
            np.mean(
                body_scores
            )
        )

        is_valid = (
            body_visible_03 >= 8
            and
            body_mean_conf >= 0.30
        )

        if is_valid:
            valid.append(
                person_idx
            )

    if len(valid) != 1:
        raise RuntimeError(
            "Expected exactly one valid "
            f"DWPose person, got {valid}"
        )

    idx = valid[0]

    return (
        keypoints[idx],
        scores[idx],
        idx,
    )


def load_dwpose(path):
    d = np.load(
        path,
        allow_pickle=True,
    )

    xy = np.asarray(
        d["keypoints"],
        dtype=np.float32,
    )

    scores = np.asarray(
        d["scores"],
        dtype=np.float32,
    )

    if (
        xy.ndim != 3
        or xy.shape[1:] != (
            134,
            2,
        )
    ):
        raise RuntimeError(
            f"Unexpected keypoint shape: "
            f"{xy.shape} @ {path}"
        )

    if (
        scores.ndim != 2
        or scores.shape[1] != 134
    ):
        raise RuntimeError(
            f"Unexpected score shape: "
            f"{scores.shape}"
        )

    return select_valid_dwpose_person(
        xy,
        scores,
    )


def build_pose_index(rows):
    result = {}

    for row in rows:
        npz_path = row.get(
            "npz_path",
            "",
        )

        if not npz_path:
            continue

        stem = Path(
            npz_path
        ).stem

        result[
            stem
        ] = row

    return result


def visible_person_scale(
    xy,
    score,
):
    valid = []

    # body + feet
    for idx in range(24):
        if (
            score[idx]
            >= DWPOSE_CONF
            and np.isfinite(
                xy[idx]
            ).all()
        ):
            valid.append(
                idx
            )

    if len(valid) < 2:
        return float("nan")

    pts = xy[
        valid
    ]

    x0 = float(
        pts[:, 0].min()
    )

    x1 = float(
        pts[:, 0].max()
    )

    y0 = float(
        pts[:, 1].min()
    )

    y1 = float(
        pts[:, 1].max()
    )

    return float(
        np.hypot(
            x1 - x0,
            y1 - y0,
        )
    )


def reconstruct_native_smpl_joints(
    params,
):
    sys.path.insert(
        0,
        str(
            SMPL_ROOT
        ),
    )

    from human_models.human_models import SMPLX

    human_model_root = (
        find_human_model_root()
    )

    print(
        "human model root:",
        human_model_root,
    )

    smpl_obj = SMPLX(
        str(
            human_model_root
        )
    )

    layer = (
        smpl_obj
        .layer["neutral"]
        .cuda()
        .eval()
    )

    device = torch.device(
        "cuda:0"
    )

    global_orient = (
        params["global_orient"]
        .to(device)
    )

    body_pose = (
        params["body_pose"]
        .to(device)
    )

    left_hand_pose = (
        params["left_hand_pose"]
        .to(device)
    )

    right_hand_pose = (
        params["right_hand_pose"]
        .to(device)
    )

    jaw_pose = (
        params["jaw_pose"]
        .to(device)
    )

    betas = (
        params["betas"]
        .to(device)
    )

    expression = (
        params["expression"]
        .to(device)
    )

    transl = (
        params["transl"]
        .to(device)
    )

    n = global_orient.shape[0]

    eye_pose = torch.zeros(
        (
            n,
            3,
        ),
        device=device,
        dtype=torch.float32,
    )

    with torch.no_grad():
        out = layer(
            betas=betas,
            body_pose=body_pose,
            global_orient=
                global_orient,
            left_hand_pose=
                left_hand_pose,
            right_hand_pose=
                right_hand_pose,
            jaw_pose=jaw_pose,
            leye_pose=eye_pose,
            reye_pose=eye_pose,
            expression=expression,
            transl=transl,
        )

    reconstructed_mesh = (
        out.vertices
        .detach()
        .cpu()
    )

    saved_mesh = (
        params[
            "mesh_cam"
        ]
        .detach()
        .cpu()
    )

    mesh_error = torch.linalg.norm(
        reconstructed_mesh
        - saved_mesh,
        dim=-1,
    )

    print()
    print(
        "SMPL-X reconstruction sanity:"
    )

    print(
        "  mesh median error:",
        float(
            mesh_error.median()
        )
    )

    print(
        "  mesh max error   :",
        float(
            mesh_error.max()
        )
    )

    # Same joint selection used by
    # official SMPLest-X get_coord().
    joints_cam = (
        out.joints[
            :,
            smpl_obj.joint_idx,
            :,
        ]
        .detach()
        .cpu()
        .numpy()
        .astype(
            np.float32
        )
    )

    if joints_cam.shape[1] != 137:
        raise RuntimeError(
            f"Expected 137 SMPLest-X "
            f"joints, got {joints_cam.shape}"
        )

    focal = (
        params[
            "focal_length_xy"
        ]
        .detach()
        .cpu()
        .numpy()
        .astype(
            np.float32
        )
    )

    princpt = (
        params[
            "princpt"
        ]
        .detach()
        .cpu()
        .numpy()
        .astype(
            np.float32
        )
    )

    z = (
        joints_cam[
            :,
            :,
            2,
        ]
        + 1e-4
    )

    x = (
        joints_cam[
            :,
            :,
            0,
        ]
        / z
        * focal[
            :,
            None,
            0,
        ]
        + princpt[
            :,
            None,
            0,
        ]
    )

    y = (
        joints_cam[
            :,
            :,
            1,
        ]
        / z
        * focal[
            :,
            None,
            1,
        ]
        + princpt[
            :,
            None,
            1,
        ]
    )

    native_xy = np.stack(
        [
            x,
            y,
        ],
        axis=-1,
    ).astype(
        np.float32
    )

    joint_name_to_idx = {
        name: idx
        for idx, name
        in enumerate(
            smpl_obj.joints_name
        )
    }

    return (
        native_xy,
        joint_name_to_idx,
    )


def draw_preview(
    image,
    dw_xy,
    dw_score,
    smpl_xy,
    smpl_name_to_idx,
    out_path,
):
    vis = image.copy()

    for (
        group,
        name,
        dw_idx,
        smpl_name,
    ) in MAPPING:

        if (
            dw_score[
                dw_idx
            ]
            < DWPOSE_CONF
        ):
            continue

        sm_idx = smpl_name_to_idx[
            smpl_name
        ]

        p_dw = dw_xy[
            dw_idx
        ]

        p_sm = smpl_xy[
            sm_idx
        ]

        if (
            not np.isfinite(
                p_dw
            ).all()
            or not np.isfinite(
                p_sm
            ).all()
        ):
            continue

        a = tuple(
            np.rint(
                p_dw
            ).astype(
                int
            )
        )

        b = tuple(
            np.rint(
                p_sm
            ).astype(
                int
            )
        )

        # correspondence
        cv2.line(
            vis,
            a,
            b,
            (
                0,
                255,
                255,
            ),
            2,
            cv2.LINE_AA,
        )

        # DWPose = green
        cv2.circle(
            vis,
            a,
            6,
            (
                0,
                255,
                0,
            ),
            -1,
            cv2.LINE_AA,
        )

        # SMPLest-X = magenta
        cv2.circle(
            vis,
            b,
            7,
            (
                255,
                0,
                255,
            ),
            2,
            cv2.LINE_AA,
        )

    cv2.imwrite(
        str(
            out_path
        ),
        vis,
        [
            int(
                cv2.IMWRITE_JPEG_QUALITY
            ),
            95,
        ],
    )


