#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
HumanVid SINGLE native geometry full build v1

Input
-----
Frozen retained-frame pool:
    humanvid_single_pose_coverage_v1.csv

Formal assets
-------------
1. Native RGB reference
2. DWPose raw 134-keypoint NPZ reference
3. Full SMPL-X params
4. Camera parameters inside params.pt
5. Native-resolution normal PNG
6. Native-resolution float32 camera-space depth NPY

Explicitly NOT formal assets
----------------------------
- part_14
- human_mask
- pose heatmaps
- smplx_global derived vector
- smplx_mask
- depth visualization

Generation
----------
Reuse the already validated:
    tools/SMPLest-X/scripts/build_tiktok_3d_assets_512.py

Despite its historical filename, the current builder preserves native
HumanVid image resolution.

Design
------
- 40 frames per batch by default
- symlink-only RGB input
- no RGB duplication
- deterministic asset IDs
- resumable by batch
- no modification of frozen retained pool
- one geometry asset per retained frame
"""

from __future__ import annotations

import argparse
import csv
