]


def parse_args():
    p = argparse.ArgumentParser()

    p.add_argument(
        "--batch-size",
        type=int,
        default=40,
    )

    p.add_argument(
        "--batch",
        type=int,
        default=None,
        help=(
            "Run only one zero-based batch. "
            "Example: --batch 0"
        ),
    )

    p.add_argument(
        "--start-batch",
        type=int,
        default=None,
    )

    p.add_argument(
        "--end-batch",
        type=int,
        default=None,
        help="Inclusive.",
    )

    p.add_argument(
        "--force",
        action="store_true",
        help="Rebuild selected completed batch(es).",
    )

    return p.parse_args()


def ensure_dir(path: Path):
    path.mkdir(
        parents=True,
        exist_ok=True,
    )


def read_csv(path: Path):
    with path.open(
        "r",
        encoding="utf-8",
    ) as f:
        return list(
            csv.DictReader(f)
        )


def write_csv(
    path: Path,
    rows: list[dict],
):
    if not rows:
        return

    ensure_dir(
        path.parent
    )

    with path.open(
        "w",
        newline="",
        encoding="utf-8",
    ) as f:
        w = csv.DictWriter(
            f,
            fieldnames=list(
                rows[0].keys()
            ),
        )

        w.writeheader()
        w.writerows(
            rows
        )


def write_json(
    path: Path,
    obj,
):
    ensure_dir(
        path.parent
    )

    with path.open(
        "w",
        encoding="utf-8",
    ) as f:
        json.dump(
            obj,
            f,
            ensure_ascii=False,
            indent=2,
        )


def source_rgb_path(row):
    """
    The frozen pose-coverage CSV uses frame_path.

    frame_id is preserved as dataset identity metadata and
    is not assumed to be the storage column.
    """
    candidates = [
        row.get(
            "frame_path",
            "",
        ).strip(),
        row.get(
            "frame_id",
            "",
        ).strip(),
    ]

    for s in candidates:
        if not s:
            continue

        p = Path(
            s
        ).expanduser()

        if p.is_file():
            return p.resolve()

    raise FileNotFoundError(
        "No readable RGB path for row: "
        + str(
            row.get(
                "frame_id",
                "",
            )
        )
    )


def make_asset_id(
    global_index: int,
):
    return (
        f"humanvid_full_"
        f"{global_index + 1:06d}"
    )


def safe_remove(
    p: Path,
):
    if p.is_symlink() or p.is_file():
        p.unlink()
    elif p.is_dir():
        shutil.rmtree(
            p
        )


def prepare_batch_input(
    batch_id: int,
    indexed_rows,
):
    seq = (
        f"batch_{batch_id:03d}"
    )

    seq_input_root = (
        INPUT_ROOT
        / seq
    )

    image_dir = (
        seq_input_root
        / "images"
    )

    if image_dir.exists():
        shutil.rmtree(
            image_dir
        )

    ensure_dir(
        image_dir
    )

    mapping = []

    for local_index, (
        global_index,
        row,
    ) in enumerate(
        indexed_rows
    ):
        src = source_rgb_path(
            row
        )

        img = cv2.imread(
            str(src),
            cv2.IMREAD_COLOR,
        )

        if img is None:
            raise RuntimeError(
                f"Cannot decode RGB: {src}"
            )

        h, w = img.shape[:2]

        asset_id = make_asset_id(
            global_index
        )

        suffix = (
            src.suffix.lower()
        )

        if suffix not in {
            ".jpg",
            ".jpeg",
            ".png",
            ".bmp",
            ".webp",
        }:
            suffix = ".jpg"

        link_name = (
            asset_id
            + suffix
        )

        dst = (
            image_dir
            / link_name
        )

        os.symlink(
            src,
            dst,
        )

        mapping.append({
            "global_index":
                global_index,

            "local_index":
                local_index,

            "asset_id":
                asset_id,

            "builder_stem":
                Path(
                    link_name
                ).stem,

            "frame_id":
                row.get(
                    "frame_id",
                    "",
                ),

            "video_id":
                row.get(
                    "video_id",
                    "",
                ),

            "segment_id":
                row.get(
                    "segment_id",
                    "",
                ),

            "native_rgb_path":
                str(src),

            "width":
                int(w),

            "height":
                int(h),

            "dwpose_npz_path":
                row.get(
                    "npz_path",
                    "",
                ),

            "quality_group":
                row.get(
                    "quality_group",
                    "",
                ),

            "quality_status":
                row.get(
                    "quality_status",
                    "",
                ),

            "pose_cluster_id":
                row.get(
                    "pose_cluster_id",
                    "",
                ),
        })

    return (
        seq,
        mapping,
    )


def validate_params(
    params_path: Path,
    mapping,
):
    obj = torch.load(
        params_path,
        map_location="cpu",
        weights_only=False,
    )

    if not isinstance(
        obj,
        dict,
    ):
        raise RuntimeError(
            "params.pt is not a dict"
        )

    missing = [
        k
        for k in EXPECTED_PARAM_KEYS
        if k not in obj
    ]

    if missing:
        raise RuntimeError(
            "Missing SMPL-X parameter keys: "
            + ", ".join(
                missing
            )
        )

    n = len(
        mapping
    )

    for key in EXPECTED_PARAM_KEYS:
        value = obj[
            key
        ]

        if not torch.is_tensor(
            value
        ):
            raise RuntimeError(
                f"{key} is not tensor"
            )

        if value.shape[0] != n:
            raise RuntimeError(
                f"{key}: first dim "
                f"{value.shape[0]} != {n}"
            )

        if not torch.isfinite(
            value
        ).all():
            raise RuntimeError(
                f"{key} contains non-finite values"
            )

    # Width/height are already part of the successful
    # pilot contract. Verify against native RGB.
    for item in mapping:
        i = item[
            "local_index"
        ]

        pw = float(
            obj["width"][i]
            .reshape(-1)[0]
        )

        ph = float(
            obj["height"][i]
            .reshape(-1)[0]
        )

        if (
            abs(
                pw
                - item["width"]
            ) > 1
            or
            abs(
                ph
                - item["height"]
            ) > 1
        ):
            raise RuntimeError(
                f"{item['asset_id']}: "
                f"params W/H=({pw},{ph}) "
                f"but RGB=({item['width']},"
                f"{item['height']})"
            )

    return obj


def validate_normal(
    path: Path,
    expected_h: int,
    expected_w: int,
):
    img = cv2.imread(
        str(path),
        cv2.IMREAD_UNCHANGED,
    )

    if img is None:
        return (
            False,
            "normal_decode_failed",
        )

    if img.shape[:2] != (
        expected_h,
        expected_w,
    ):
        return (
            False,
            (
                "normal_shape_"
                f"{img.shape[:2]}"
            ),
        )

    if img.size == 0:
        return (
            False,
            "normal_empty",
        )

    return (
        True,
        "",
    )


def validate_depth(
    path: Path,
    expected_h: int,
    expected_w: int,
):
    try:
        d = np.load(
            path,
            allow_pickle=False,
        )
    except Exception as e:
        return (
            False,
            "depth_load_failed:"
            + repr(e),
        )

    if d.shape != (
        expected_h,
        expected_w,
    ):
        return (
            False,
            (
                "depth_shape_"
                f"{d.shape}"
            ),
        )

    if d.dtype != np.float32:
        return (
            False,
            (
                "depth_dtype_"
                f"{d.dtype}"
            ),
        )

    finite = np.isfinite(
        d
    )

    if not finite.all():
        return (
            False,
            "depth_nonfinite",
        )

    # No arbitrary quality threshold:
    # only ensure the renderer produced positive geometry.
    if not np.any(
        d > 0
    ):
        return (
            False,
            "depth_no_positive_geometry",
        )

    return (
        True,
        "",
    )


def batch_paths(
    seq,
):
    seq_out = (
        BUILDER_OUTPUT
        / seq
    )

    return {
        "seq_out":
            seq_out,

        "params":
            (
                seq_out
                / "smplestx"
                / "params.pt"
            ),

        "frame_map":
            (
                seq_out
                / "smplestx"
                / "frame_map.json"
            ),
    }


def build_batch_manifest(
    batch_id: int,
    seq: str,
    mapping,
):
    paths = batch_paths(
        seq
    )

    params_path = paths[
        "params"
    ]

    frame_map_path = paths[
        "frame_map"
    ]

    if not params_path.is_file():
        raise RuntimeError(
            f"Missing params.pt: "
            f"{params_path}"
        )

    if not frame_map_path.is_file():
        raise RuntimeError(
            f"Missing frame_map.json: "
            f"{frame_map_path}"
        )

    validate_params(
        params_path,
        mapping,
    )

    rows = []

    for item in mapping:
        stem = item[
            "builder_stem"
        ]

        normal_path = (
            paths[
                "seq_out"
            ]
            / "normal"
            / f"{stem}.png"
        )

        depth_path = (
            paths[
                "seq_out"
            ]
            / "depth_npy"
            / f"{stem}.npy"
        )

        errors = []

        if not normal_path.is_file():
            errors.append(
                "missing_normal"
            )
        else:
            ok, error = (
                validate_normal(
                    normal_path,
                    item["height"],
                    item["width"],
                )
            )

            if not ok:
                errors.append(
                    error
                )

        if not depth_path.is_file():
            errors.append(
                "missing_depth"
            )
        else:
            ok, error = (
                validate_depth(
                    depth_path,
                    item["height"],
                    item["width"],
                )
            )

            if not ok:
                errors.append(
                    error
                )

        geometry_status = (
            "ok"
            if not errors
            else "failed"
        )

        rows.append({
            "asset_id":
                item[
                    "asset_id"
                ],

            "frame_id":
                item[
                    "frame_id"
                ],

            "video_id":
                item[
                    "video_id"
                ],

            "segment_id":
                item[
                    "segment_id"
                ],

            "native_rgb_path":
                item[
                    "native_rgb_path"
                ],

            "width":
                item[
                    "width"
                ],

            "height":
                item[
                    "height"
                ],

            "dwpose_npz_path":
                item[
                    "dwpose_npz_path"
                ],

            "quality_group":
                item[
                    "quality_group"
                ],

            "quality_status":
                item[
                    "quality_status"
                ],

            "pose_cluster_id":
                item[
                    "pose_cluster_id"
                ],

            "asset_batch_id":
                seq,

            "smplx_params_path":
                str(
                    params_path
                ),

            "smplx_frame_index":
                item[
                    "local_index"
                ],

            "smplx_frame_map_path":
                str(
                    frame_map_path
                ),

            "normal_path":
                str(
                    normal_path
                ),

            "depth_path":
                str(
                    depth_path
                ),

            "geometry_status":
                geometry_status,

            "qc_status":
                (
                    "structural_pass"
                    if not errors
                    else "structural_fail"
                ),

            "error":
                ";".join(
                    errors
                ),
        })

    return rows


def batch_manifest_path(
    batch_id: int,
):
    return (
        BATCH_MANIFEST_DIR
        / (
            f"batch_{batch_id:03d}.csv"
        )
    )


def batch_state_path(
    batch_id: int,
):
    return (
        STATE_DIR
        / (
            f"batch_{batch_id:03d}.json"
        )
    )


def completed_batch(
    batch_id: int,
    expected_count: int,
):
    p = batch_manifest_path(
        batch_id
    )

    if not p.is_file():
        return False

    try:
        rows = read_csv(
            p
        )
    except Exception:
        return False

    if len(rows) != expected_count:
        return False

    return all(
        r.get(
            "geometry_status"
        ) == "ok"
        for r in rows
    )


def run_batch(
    batch_id: int,
    indexed_rows,
    force=False,
):
    expected_count = len(
        indexed_rows
    )

    if (
        not force
        and completed_batch(
            batch_id,
            expected_count,
        )
    ):
        print(
            f"[batch {batch_id:03d}] "
            f"SKIP: already complete "
            f"({expected_count} frames)"
        )

        return

    seq = (
        f"batch_{batch_id:03d}"
    )

    state_path = (
        batch_state_path(
            batch_id
        )
    )

    state = {
        "batch_id":
            batch_id,

        "sequence":
            seq,

        "expected_frames":
            expected_count,

        "status":
            "running",

        "started_at":
            datetime.now()
            .isoformat(
                timespec="seconds"
            ),

        "finished_at":
            None,

        "error":
            "",
    }

    write_json(
        state_path,
        state,
    )

    print()
    print("=" * 80)
    print(
        f"BATCH {batch_id:03d}"
    )
    print("=" * 80)

    print(
        "frames:",
        expected_count,
    )

    seq, mapping = (
        prepare_batch_input(
            batch_id,
            indexed_rows,
        )
    )

    mapping_path = (
        MANIFEST_DIR
        / (
            f"humanvid_full_"
            f"{seq}_input_map.json"
        )
    )

    write_json(
        mapping_path,
        mapping,
    )

    if force:
        seq_out = (
            BUILDER_OUTPUT
            / seq
        )

        if seq_out.exists():
            print(
                "force remove:",
                seq_out,
            )

            shutil.rmtree(
                seq_out
            )

    cmd = [
        sys.executable,
        str(
            BUILDER
        ),

        "--dataset",
        str(
            INPUT_ROOT
        ),

        "--output",
        str(
            BUILDER_OUTPUT
        ),

        "--sequence",
        seq,

        "--save-depth-npy",
    ]

    print(
        "RUN:"
    )
    print(
        " ".join(
            cmd
        )
    )
    print()

    try:
        subprocess.run(
            cmd,
            check=True,
            cwd=str(
                BASE
            ),
        )

        out_rows = (
            build_batch_manifest(
                batch_id,
                seq,
                mapping,
            )
        )

        failed = [
            x
            for x in out_rows
            if x[
                "geometry_status"
            ] != "ok"
        ]

        write_csv(
            batch_manifest_path(
                batch_id
            ),
            out_rows,
        )

        if failed:
            raise RuntimeError(
                f"{len(failed)}/"
                f"{len(out_rows)} "
                "frames failed structural QC"
            )

        state[
            "status"
        ] = "complete"

        state[
            "finished_at"
        ] = (
            datetime.now()
            .isoformat(
                timespec="seconds"
            )
        )

        write_json(
            state_path,
            state,
        )

        print(
            f"✅ batch {batch_id:03d}: "
            f"{len(out_rows)}/"
            f"{len(out_rows)} PASS"
        )

    except Exception as e:
        state[
            "status"
        ] = "failed"

        state[
            "finished_at"
        ] = (
            datetime.now()
            .isoformat(
                timespec="seconds"
            )
        )

        state[
            "error"
        ] = repr(
            e
        )

        write_json(
            state_path,
            state,
        )

        print(
            f"❌ batch {batch_id:03d} failed:"
        )

        print(
            repr(e)
        )

        print(
            f"⚠️ batch {batch_id:03d} recorded and skipped; "
            "continuing with next batch."
        )

        return False


def rebuild_final_manifest():
    manifests = sorted(
        BATCH_MANIFEST_DIR.glob(
            "batch_*.csv"
        )
    )

    rows = []

    for p in manifests:
        rows.extend(
            read_csv(
                p
            )
        )

    if not rows:
        return

    rows.sort(
        key=lambda x: int(
            x[
                "asset_id"
            ].rsplit(
                "_",
                1,
            )[-1]
        )
    )

    write_csv(
        FINAL_MANIFEST,
        rows,
    )


def main():
    args = parse_args()

    if not SOURCE_CSV.is_file():
        raise FileNotFoundError(
            SOURCE_CSV
        )

    if not BUILDER.is_file():
        raise FileNotFoundError(
            BUILDER
        )

    if args.batch_size <= 0:
        raise ValueError(
            "--batch-size must be > 0"
        )

    ensure_dir(
        INPUT_ROOT
    )

    ensure_dir(
        BUILDER_OUTPUT
    )

    ensure_dir(
        BATCH_MANIFEST_DIR
    )

    ensure_dir(
        STATE_DIR
    )

    ensure_dir(
        MANIFEST_DIR
    )

    rows = read_csv(
        SOURCE_CSV
    )

    print("=" * 80)
    print(
        "HumanVid Native Assets FULL V1"
    )
    print("=" * 80)

    print(
        "retained frames:",
        len(rows),
    )

    print(
        "batch size     :",
        args.batch_size,
    )

    # Frozen Step12 pool is currently expected to contain 992.
    # Warn rather than silently alter anything.
    if len(rows) != 991:
        print(
            "WARNING: expected frozen retained pool "
            f"of 991 rows, got {len(rows)}"
        )

    # Basic uniqueness check.
    rgb_paths = []

    for r in rows:
        rgb_paths.append(
            str(
                source_rgb_path(
                    r
                )
            )
        )

    if len(
        set(
            rgb_paths
        )
    ) != len(
        rgb_paths
    ):
        raise RuntimeError(
            "Frozen retained pool contains duplicate RGB paths. "
            "Refusing to silently deduplicate."
        )

    indexed = list(
        enumerate(
            rows
        )
    )

    batches = [
        indexed[
            i:
            i + args.batch_size
        ]
        for i in range(
            0,
            len(indexed),
            args.batch_size,
        )
    ]

    print(
        "total batches  :",
        len(
            batches
        ),
    )

    if args.batch is not None:
        selected = [
            args.batch
        ]

    else:
        start = (
            0
            if args.start_batch is None
            else args.start_batch
        )

        end = (
            len(
                batches
            ) - 1
            if args.end_batch is None
            else args.end_batch
        )

        selected = list(
            range(
                start,
                end + 1,
            )
        )

    for batch_id in selected:
        if not (
            0
            <= batch_id
            < len(
                batches
            )
        ):
            raise ValueError(
                f"Invalid batch {batch_id}; "
                f"valid range=0.."
                f"{len(batches)-1}"
            )

    print(
        "selected       :",
        selected,
    )

    print()

    for batch_id in selected:
        run_batch(
            batch_id,
            batches[
                batch_id
            ],
            force=args.force,
        )

        rebuild_final_manifest()

    rebuild_final_manifest()

    if FINAL_MANIFEST.is_file():
        final_rows = read_csv(
            FINAL_MANIFEST
        )

        ok = sum(
            r[
                "geometry_status"
            ] == "ok"
            for r in final_rows
        )

        print()
        print("=" * 80)
        print("CURRENT FULL MANIFEST")
        print("=" * 80)

        print(
            "rows :",
            len(
                final_rows
            ),
        )

        print(
            "ok   :",
            ok,
        )

        print(
            "file :",
            FINAL_MANIFEST,
        )


if __name__ == "__main__":
    main()

