    )


def letterbox_rgb(
    img,
    size=PANEL_SIZE,
    bg=255,
):
    h, w = img.shape[:2]

    scale = min(
        size / w,
        size / h,
    )

    nw = max(
        1,
        round(
            w * scale
        ),
    )

    nh = max(
        1,
        round(
            h * scale
        ),
    )

    resized = cv2.resize(
        img,
        (nw, nh),
        interpolation=(
            cv2.INTER_AREA
            if scale < 1
            else cv2.INTER_LINEAR
        ),
    )

    canvas = np.full(
        (
            size,
            size,
            3,
        ),
        bg,
        dtype=np.uint8,
    )

    x = (
        size - nw
    ) // 2

    y = (
        size - nh
    ) // 2

    canvas[
        y:y + nh,
        x:x + nw,
    ] = resized

    return canvas


def find_dwpose_arrays(npz_path):
    data = np.load(
        npz_path,
        allow_pickle=True,
    )

    coords = None
    scores = None

    # First handle explicit common keys.
    coord_keys = [
        "candidate",
        "candidates",
        "keypoints",
        "coords",
        "points",
    ]

    score_keys = [
        "subset",
        "scores",
        "score",
        "confidence",
        "conf",
    ]

    for k in coord_keys:
        if k in data:
            a = np.asarray(
                data[k]
            )

            if (
                a.ndim == 3
                and a.shape[-2] >= 134
                and a.shape[-1] >= 2
            ):
                coords = a[
                    ...,
                    :2,
                ]
                break

    for k in score_keys:
        if k in data:
            a = np.asarray(
                data[k]
            )

            if (
                a.ndim == 2
                and a.shape[-1] >= 134
            ):
                scores = a
                break

    # Generic fallback.
    if coords is None:
        for k in data.files:
            a = np.asarray(
                data[k]
            )

            if (
                a.ndim == 3
                and a.shape[-2] >= 134
                and a.shape[-1] >= 2
            ):
                coords = a[
                    ...,
                    :2,
                ]

                # If third channel looks like score.
                if (
                    scores is None
                    and a.shape[-1] >= 3
                ):
                    scores = a[
                        ...,
                        2,
                    ]

                break

    if scores is None:
        for k in data.files:
            a = np.asarray(
                data[k]
            )

            if (
                a.ndim == 2
                and a.shape[-1] >= 134
            ):
                scores = a
                break

    if coords is None:
        raise RuntimeError(
            f"cannot locate DWPose coordinates: "
            f"{npz_path}, keys={data.files}"
        )

    coords = np.asarray(
        coords,
        dtype=np.float32,
    )

    if scores is None:
        scores = np.ones(
            coords.shape[:-1],
            dtype=np.float32,
        )
    else:
        scores = np.asarray(
            scores,
            dtype=np.float32,
        )

    return (
        coords,
        scores,
    )


def normalize_dwpose_xy(
    xy,
    width,
    height,
):
    out = xy.copy()

    finite = np.isfinite(
        out
    )

    valid_values = out[
        finite
    ]

    if valid_values.size == 0:
        return out

    # DWPose may be stored normalized to 0..1.
    mx = float(
        np.nanmax(
            np.abs(
                valid_values
            )
        )
    )

    if mx <= 2.0:
        out[
            ...,
            0
        ] *= width

        out[
            ...,
            1
        ] *= height

    return out


def draw_dwpose(
    rgb,
    npz_path,
):
    canvas = rgb.copy()

    h, w = canvas.shape[:2]

    xy, scores = find_dwpose_arrays(
        npz_path
    )

    xy = normalize_dwpose_xy(
        xy,
        w,
        h,
    )

    # Expected SINGLE person.
    # If multiple are stored, use the highest body-confidence person.
    if xy.shape[0] > 1:
        body_mean = np.nanmean(
            scores[
                :,
                :18,
            ],
            axis=1,
        )

        person = int(
            np.nanargmax(
                body_mean
            )
        )
    else:
        person = 0

    pts = xy[
        person
    ]

    sc = scores[
        person
    ]

    scale = max(
        1.0,
        min(
            w,
            h,
        ) / 700.0,
    )

    line_t = max(
        2,
        round(
            2.5 * scale
        ),
    )

    radius = max(
        3,
        round(
            3.0 * scale
        ),
    )

    def valid(i):
        if i >= len(pts):
            return False

        x, y = pts[i]

        return (
            np.isfinite(x)
            and np.isfinite(y)
            and sc[i] >= SCORE_THR
            and x >= 0
            and y >= 0
            and x < w
            and y < h
        )

    # body
    for a, b in BODY18_EDGES:
        if valid(a) and valid(b):
            pa = tuple(
                np.round(
                    pts[a]
                ).astype(int)
            )

            pb = tuple(
                np.round(
                    pts[b]
                ).astype(int)
            )

            cv2.line(
                canvas,
                pa,
                pb,
                (255, 220, 0),
                line_t,
                cv2.LINE_AA,
            )

    # hand skeletons
    for offset in [
        92,
        113,
    ]:
        for a, b in HAND21_EDGES:
            aa = offset + a
            bb = offset + b

            if valid(aa) and valid(bb):
                pa = tuple(
                    np.round(
                        pts[aa]
                    ).astype(int)
                )

                pb = tuple(
                    np.round(
                        pts[bb]
                    ).astype(int)
                )

                cv2.line(
                    canvas,
                    pa,
                    pb,
                    (0, 255, 255),
                    line_t,
                    cv2.LINE_AA,
                )

    # all visible points:
    # body + feet + face + hands
    n = min(
        134,
        len(pts),
    )

    for i in range(n):
        if not valid(i):
            continue

        p = tuple(
            np.round(
                pts[i]
            ).astype(int)
        )

        if i < 24:
            color = (
                255,
                80,
                30,
            )
        elif i < 92:
            color = (
                60,
                255,
                100,
            )
        else:
            color = (
                255,
                60,
                230,
            )

        cv2.circle(
            canvas,
            p,
            radius,
            color,
            -1,
            cv2.LINE_AA,
        )

    return canvas


def load_normal(path):
    img = cv2.imread(
        str(path),
        cv2.IMREAD_COLOR,
    )

    if img is None:
        raise RuntimeError(
            f"cannot read normal: {path}"
        )

    return cv2.cvtColor(
        img,
        cv2.COLOR_BGR2RGB,
    )


def depth_visualization(path):
    d = np.load(
        path,
        allow_pickle=False,
    ).astype(
        np.float32
    )

    valid = (
        np.isfinite(d)
        & (d > 0)
    )

    out = np.zeros(
        d.shape,
        dtype=np.uint8,
    )

    if valid.any():
        vals = d[
            valid
        ]

        lo = float(
            np.percentile(
                vals,
                2,
            )
        )

        hi = float(
            np.percentile(
                vals,
                98,
            )
        )

        if hi <= lo:
            hi = lo + 1e-6

        normalized = (
            d - lo
        ) / (
            hi - lo
        )

        normalized = np.clip(
            normalized,
            0,
            1,
        )

        # Near = brighter/hotter.
        normalized = (
            1.0 - normalized
        )

        out[
            valid
        ] = (
            normalized[
                valid
            ]
            * 255
        ).astype(
            np.uint8
        )

    colored = cv2.applyColorMap(
        out,
        cv2.COLORMAP_TURBO,
    )

    colored[
        ~valid
    ] = 0

    return cv2.cvtColor(
        colored,
        cv2.COLOR_BGR2RGB,
    )


def panel(
    image,
    title,
):
    body = letterbox_rgb(
        image
    )

    canvas = Image.new(
        "RGB",
        (
            PANEL_SIZE,
            PANEL_SIZE
            + HEADER_H,
        ),
        "white",
    )

    canvas.paste(
        Image.fromarray(body),
        (
            0,
            HEADER_H,
        ),
    )

    draw = ImageDraw.Draw(
        canvas
    )

    box = draw.textbbox(
        (0, 0),
        title,
        font=FONT,
    )

    tw = (
        box[2]
        - box[0]
    )

    draw.text(
        (
            (
                PANEL_SIZE
                - tw
            ) // 2,
            8,
        ),
        title,
        fill="black",
        font=FONT,
    )

    return canvas


def choose_samples(df):
    df = df.copy()

    if (
        "geometry_status"
        in df.columns
    ):
        df = df[
            df[
                "geometry_status"
            ] == "ok"
        ].copy()

    if len(df) < N:
        raise RuntimeError(
            f"only {len(df)} valid rows"
        )

    rng = random.Random(
        SEED
    )

    # clean first, then risk.
    if (
        "quality_status"
        in df.columns
    ):
        df[
            "_quality_rank"
        ] = (
            df[
                "quality_status"
            ]
            .astype(str)
            .map({
                "clean": 0,
                "ok": 0,
                "risk": 1,
            })
            .fillna(2)
        )
    else:
        df[
            "_quality_rank"
        ] = 0

    rows = (
        df
        .to_dict(
            "records"
        )
    )

    rng.shuffle(
        rows
    )

    rows.sort(
        key=lambda x: (
            x[
                "_quality_rank"
            ],
        )
    )

    selected = []
    used_video = set()
    used_asset = set()

    # Pass 1: strict unique video_id.
    for row in rows:
        v = str(
            row.get(
                "video_id",
                "",
            )
        )

        a = str(
            row.get(
                "asset_id",
                "",
            )
        )

        if (
            v in used_video
            or a in used_asset
        ):
            continue

        selected.append(
            row
        )

        used_video.add(
            v
        )

        used_asset.add(
            a
        )

        if len(
            selected
        ) >= N:
            break

    # Fallback only if fewer than 40 unique videos exist.
    if len(selected) < N:
        for row in rows:
            a = str(
                row.get(
                    "asset_id",
                    "",
                )
            )

            if a in used_asset:
                continue

            selected.append(
                row
            )

            used_asset.add(
                a
            )

            if len(
                selected
            ) >= N:
                break

    return selected


def make_sheet(
    row,
    rank,
):
    rgb = load_rgb(
        Path(
            row[
                "native_rgb_path"
            ]
        )
    )

    dwpose = draw_dwpose(
        rgb,
        Path(
            row[
                "dwpose_npz_path"
            ]
        ),
    )

    normal = load_normal(
        Path(
            row[
                "normal_path"
            ]
        )
    )

    depth = depth_visualization(
        Path(
            row[
                "depth_path"
            ]
        )
    )

    panels = [
        panel(
            rgb,
            "RGB",
        ),
        panel(
            dwpose,
            "DWPose",
        ),
        panel(
            normal,
            "SMPL-X Normal",
        ),
        panel(
            depth,
            "SMPL-X Depth",
        ),
    ]

    width = (
        PANEL_SIZE
        * len(panels)
    )

    height = (
        PANEL_SIZE
        + HEADER_H
        + FOOTER_H
    )

    sheet = Image.new(
        "RGB",
        (
            width,
            height,
        ),
        "white",
    )

    x = 0

    for p in panels:
        sheet.paste(
            p,
            (
                x,
                0,
            ),
        )

        x += PANEL_SIZE

    draw = ImageDraw.Draw(
        sheet
    )

    asset_id = str(
        row.get(
            "asset_id",
            "",
        )
    )

    video_id = str(
        row.get(
            "video_id",
            "",
        )
    )

    segment_id = str(
        row.get(
            "segment_id",
            "",
        )
    )

    w = row.get(
        "width",
        "",
    )

    h = row.get(
        "height",
        "",
    )

    smpl_index = row.get(
        "smplx_frame_index",
        "",
    )

    footer1 = (
        f"#{rank:02d}  "
        f"asset={asset_id}    "
        f"video={video_id}    "
        f"segment={segment_id}"
    )

    footer2 = (
        f"native={w}x{h}    "
        f"SMPL-X frame index={smpl_index}"
    )

    draw.text(
        (
            18,
            PANEL_SIZE
            + HEADER_H
            + 8,
        ),
        footer1,
        fill="black",
        font=SMALL_FONT,
    )

    draw.text(
        (
            18,
            PANEL_SIZE
            + HEADER_H
            + 36,
        ),
        footer2,
        fill="black",
        font=SMALL_FONT,
    )

    safe_video = (
        video_id
        .replace(
            "/",
            "_",
        )
    )

    safe_asset = (
        asset_id
        .replace(
            "/",
            "_",
        )
    )

    out = (
        OUT_ROOT
        / (
            f"{rank:03d}_"
            f"video_{safe_video}_"
            f"{safe_asset}.jpg"
        )
    )

    sheet.save(
        out,
        quality=95,
        subsampling=0,
    )

    return out


def main():
    ensure_dir(
