def norm(x):
    x = str(x).strip()

    if not x or x.lower() == "nan":
        return ""

    return x


def find_col(
    columns,
    candidates,
):
    lower = {
        str(c).lower(): c
        for c in columns
    }

    for c in candidates:
        if c.lower() in lower:
            return lower[c.lower()]

    return None


def detect_split(name):
    name = name.lower()

    if "train" in name:
        return "train"

    if "val" in name:
        return "val"

    if "test" in name:
        return "test"

    return ""


# ============================================================
# Source RGB lookup:
# frozen retained frame pool, geometry NOT required.
# ============================================================

def build_rgb_lookup():
    df = pd.read_csv(
        FRAME_POOL
    )

    lookup = {}

    basename_count = {}

    rows = df.to_dict(
        "records"
    )

    for row in rows:
        paths = [
            norm(
                row.get(
                    "frame_id",
                    "",
                )
            ),
            norm(
                row.get(
                    "frame_path",
                    "",
                )
            ),
        ]

        actual = ""

        for p in paths:
            if (
                p
                and Path(p).is_file()
            ):
                actual = str(
                    Path(p).resolve()
                )
                break

        if not actual:
            continue

        item = {
            "frame_id":
                norm(
                    row.get(
                        "frame_id",
                        "",
                    )
                ),

            "native_rgb_path":
                actual,

            "video_id":
                norm(
                    row.get(
                        "video_id",
                        "",
                    )
                ),

            "segment_id":
                norm(
                    row.get(
                        "segment_id",
                        "",
                    )
                ),
        }

        for key in paths + [actual]:
            if not key:
                continue

            lookup[key] = item

            base = Path(
                key
            ).name

            basename_count[
                base
            ] = (
                basename_count.get(
                    base,
                    0,
                )
                + 1
            )

    # Unique basename fallback.
    for key, item in list(
        lookup.items()
    ):
        base = Path(
            key
        ).name

        if (
            basename_count.get(
                base,
                0,
            )
            == 1
        ):
            lookup.setdefault(
                base,
                item,
            )

    return lookup


# ============================================================
# Target geometry lookup.
# ============================================================

def build_target_lookup():
    df = pd.read_csv(
        ASSET_MANIFEST
    )

    df = df[
        df[
            "geometry_status"
        ] == "ok"
    ].copy()

    lookup = {}
    basename_count = {}

    rows = df.to_dict(
        "records"
    )

    for row in rows:
        for c in [
            "frame_id",
            "native_rgb_path",
        ]:
            key = norm(
                row.get(
                    c,
                    "",
                )
            )

            if not key:
                continue

            lookup[key] = row

            base = Path(
                key
            ).name

            basename_count[
                base
            ] = (
                basename_count.get(
                    base,
                    0,
                )
                + 1
            )

    for row in rows:
        for c in [
            "frame_id",
            "native_rgb_path",
        ]:
            key = norm(
                row.get(
                    c,
                    "",
                )
            )

            if not key:
                continue

            base = Path(
                key
            ).name

            if (
                basename_count.get(
                    base,
                    0,
                )
                == 1
            ):
                lookup.setdefault(
                    base,
                    row,
                )

    return lookup


def lookup(
    table,
    key,
):
    key = norm(
        key
    )

    if key in table:
        return table[key]

    if key:
        return table.get(
            Path(key).name
        )

    return None


# ============================================================
# Load final source-target pairs.
# ============================================================

def load_pairs():
    rgb_lookup = (
        build_rgb_lookup()
    )

    target_lookup = (
        build_target_lookup()
    )

    valid = []

    print("=" * 80)
    print("FINAL PAIR DISCOVERY")
    print("=" * 80)

    for path in sorted(
        PAIR_ROOT.glob(
            "*.csv"
        )
    ):
        try:
            df = pd.read_csv(
                path
            )
        except Exception:
            continue

        source_col = find_col(
            df.columns,
            SOURCE_COLUMNS,
        )

        target_col = find_col(
            df.columns,
            TARGET_COLUMNS,
        )

        if (
            source_col is None
            or target_col is None
        ):
            continue

        print(
            f"{path.name}: "
            f"rows={len(df)} "
            f"S={source_col} "
            f"T={target_col}"
        )

        split = detect_split(
            path.name
        )

        for idx, row in df.iterrows():
            source_key = norm(
                row[
                    source_col
                ]
            )

            target_key = norm(
                row[
                    target_col
                ]
            )

            source = lookup(
                rgb_lookup,
                source_key,
            )

            target = lookup(
                target_lookup,
                target_key,
            )

            # Source only needs RGB.
            if source is None:
                # If the pair itself stores a real path,
                # use it directly.
                if (
                    source_key
                    and Path(
                        source_key
                    ).is_file()
                ):
                    source = {
                        "frame_id":
                            source_key,

                        "native_rgb_path":
                            str(
                                Path(
                                    source_key
                                ).resolve()
                            ),

                        "video_id":
                            norm(
                                row.get(
                                    "video_id",
                                    "",
                                )
                            ),

                        "segment_id":
                            norm(
                                row.get(
                                    "segment_id",
                                    "",
                                )
                            ),
                    }
                else:
                    continue

            # Target must have full geometry.
            if target is None:
                continue

            video_id = norm(
                row.get(
                    "video_id",
                    "",
                )
            )

            if not video_id:
                video_id = norm(
                    target.get(
                        "video_id",
                        "",
                    )
                )

            segment_id = norm(
                row.get(
                    "segment_id",
                    "",
                )
            )

            if not segment_id:
                segment_id = norm(
                    target.get(
                        "segment_id",
                        "",
                    )
                )

            pair_id = norm(
                row.get(
                    "pair_id",
                    "",
                )
            )

            if not pair_id:
                pair_id = (
                    f"{path.name}:"
                    f"{idx}"
                )

            valid.append({
                "pair_id":
                    pair_id,

                "split":
                    norm(
                        row.get(
                            "split",
                            split,
                        )
                    ),

                "video_id":
                    video_id,

                "segment_id":
                    segment_id,

                "source":
                    source,

                "target":
                    target,
            })

    print()
    print(
        "geometry-complete target pairs:",
        len(valid),
    )

    if not valid:
        raise RuntimeError(
            "No usable source-target pairs found."
        )

    return valid


# ============================================================
# Select 40, preferably 40 different videos.
# ============================================================

def choose_pairs(
    pairs,
):
    rng = random.Random(
        SEED
    )

    pairs = pairs.copy()

    rng.shuffle(
        pairs
    )

    chosen = []
    used_videos = set()
    used_pairs = set()

    for pair in pairs:
        video = norm(
            pair[
                "video_id"
            ]
        )

        if (
            video
            and video
            in used_videos
        ):
            continue

        chosen.append(
            pair
        )

        used_pairs.add(
            pair[
                "pair_id"
            ]
        )

        if video:
            used_videos.add(
                video
            )

        if len(chosen) == N:
            break

    # Fallback only when fewer than 40 distinct videos exist.
    if len(chosen) < N:
        for pair in pairs:
            if (
                pair[
                    "pair_id"
                ]
                in used_pairs
            ):
                continue

            chosen.append(
                pair
            )

            used_pairs.add(
                pair[
                    "pair_id"
                ]
            )

            if len(chosen) == N:
                break

    if len(chosen) < N:
        raise RuntimeError(
            f"Only {len(chosen)} usable pairs."
        )

    return chosen


