#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
HumanVid high-quality showcase candidate selection.

Output
------
60 source-target pair sheets:

SOURCE RGB
TARGET RGB
TARGET DWPose
TARGET SMPL-X Normal
TARGET SMPL-X Depth

Selection
---------
- final valid HumanVid SINGLE pairs
- target geometry must already be complete
- prefer both source and target quality_status == clean
- rank quality by percentile inside current HumanVid retained pool
- pair score uses the WORSE side of source/target
- maximize unique video_id
- deterministic
- presentation selection only; does NOT modify formal dataset
"""

from pathlib import Path
import importlib.util
import random

import numpy as np
import pandas as pd


ROOT = Path(
    "/home/shangguanrz/project/pic-edit/add"
)

BASE_SCRIPT = (
    ROOT
    / "tools/"
      "55c_build_humanvid_pair_showcase40_v1.py"
)

FRAME_POOL = (
    ROOT
    / "outputs/humanvid_assets_v1/"
      "pose_coverage/"
      "humanvid_single_pose_coverage_v1.csv"
)

OUT_ROOT = (
    ROOT
    / "outputs/humanvid_native_assets_v1/"
      "showcase60_pairs_best_v1"
)

OUT_CSV = (
    OUT_ROOT
    / "humanvid_showcase60_best_v1.csv"
)

N = 60
SEED = 2026


# ============================================================
# Reuse the already working 5-panel renderer.
# ============================================================

spec = importlib.util.spec_from_file_location(
    "showcase55c",
    BASE_SCRIPT,
)

base = importlib.util.module_from_spec(
    spec
)

spec.loader.exec_module(
    base
)

# Redirect output used inside base.make_sheet().
base.OUT_ROOT = OUT_ROOT


# ============================================================
# Build frame-level quality ranking.
# ============================================================

HIGHER_BETTER = [
    "normalized_person_sharpness",
    "normalized_head_sharpness",
    "min_body_mean_conf",
    "min_body_visible_05",
    "min_border_margin_ratio",
    "min_person_area_ratio",
]

LOWER_BETTER = [
    "exposure_clip_ratio",
]


def norm(x):
    x = str(x).strip()

    if not x or x.lower() == "nan":
        return ""

    return x


def prepare_quality_table():
    df = pd.read_csv(
        FRAME_POOL
    ).copy()

    score_cols = []

    for col in HIGHER_BETTER:
        if col not in df.columns:
            continue

        x = pd.to_numeric(
            df[col],
            errors="coerce",
        )

        rank_col = (
            f"_rank_{col}"
        )

        df[rank_col] = (
            x.rank(
                pct=True,
                method="average",
            )
        )

        score_cols.append(
            rank_col
        )

    for col in LOWER_BETTER:
        if col not in df.columns:
            continue

        x = pd.to_numeric(
            df[col],
            errors="coerce",
        )

        rank_col = (
            f"_rank_{col}"
        )

        # smaller value = better
        df[rank_col] = (
            (-x).rank(
                pct=True,
                method="average",
            )
        )

        score_cols.append(
            rank_col
        )

    if not score_cols:
        raise RuntimeError(
            "No quality metrics available."
        )

    df["_technical_quality"] = (
        df[
            score_cols
        ]
        .mean(
            axis=1,
            skipna=True,
        )
    )

    df["_is_clean"] = (
        df[
            "quality_status"
        ]
        .astype(str)
        .str.lower()
        .eq("clean")
        if "quality_status" in df.columns
        else True
    )

    return df


def build_quality_lookup():
    df = prepare_quality_table()

    lookup = {}
    basename_count = {}

    rows = df.to_dict(
        "records"
    )

    for row in rows:
        keys = []

        for c in [
            "frame_id",
            "frame_path",
        ]:
            k = norm(
                row.get(
                    c,
                    "",
                )
            )

            if k:
                keys.append(
                    k
                )

        for key in keys:
            lookup[key] = row

            base_name = Path(
                key
            ).name

            basename_count[
                base_name
            ] = (
                basename_count.get(
                    base_name,
                    0,
                )
                + 1
            )

    # basename fallback only when unique
    for key, row in list(
        lookup.items()
    ):
        base_name = Path(
            key
        ).name

        if (
            basename_count.get(
                base_name,
                0,
            )
            == 1
        ):
            lookup.setdefault(
                base_name,
                row,
            )

    return lookup


def lookup_quality(
    table,
    path,
):
    path = norm(
        path
    )

    if path in table:
        return table[
            path
        ]

    if path:
        return table.get(
            Path(path).name
        )

    return None


# ============================================================
# Rank pairs.
# ============================================================

def rank_pairs():
    pairs = base.load_pairs()

    quality_lookup = (
        build_quality_lookup()
    )

    ranked = []

    missing_quality = 0

    for pair in pairs:
        src = pair[
            "source"
        ]

        tgt = pair[
            "target"
        ]

        src_q = lookup_quality(
            quality_lookup,
            src[
                "native_rgb_path"
            ],
        )

        tgt_q = lookup_quality(
            quality_lookup,
            tgt[
                "native_rgb_path"
            ],
        )

        if (
            src_q is None
            or tgt_q is None
        ):
            missing_quality += 1
            continue

        src_score = float(
            src_q.get(
                "_technical_quality",
                np.nan,
            )
        )

        tgt_score = float(
            tgt_q.get(
                "_technical_quality",
                np.nan,
            )
        )

        if (
            not np.isfinite(
                src_score
            )
            or not np.isfinite(
                tgt_score
            )
        ):
            continue

        src_clean = bool(
            src_q.get(
                "_is_clean",
                False,
            )
        )

        tgt_clean = bool(
            tgt_q.get(
                "_is_clean",
                False,
            )
        )

        pair["_source_quality"] = (
            src_score
        )

        pair["_target_quality"] = (
            tgt_score
        )

        # The weakest frame determines presentation quality.
        pair["_pair_quality"] = min(
            src_score,
            tgt_score,
        )

        pair["_mean_quality"] = (
            src_score
            + tgt_score
        ) / 2.0

        pair["_both_clean"] = (
            src_clean
            and tgt_clean
        )

        pair["_source_clean"] = (
            src_clean
        )

        pair["_target_clean"] = (
            tgt_clean
        )

        ranked.append(
            pair
        )

    print()
    print(
        "pairs with quality metadata:",
        len(ranked),
    )

    print(
        "missing quality:",
        missing_quality,
    )

    # Stable deterministic random tie breaker.
    rng = random.Random(
        SEED
    )

    for x in ranked:
        x["_tie"] = (
            rng.random()
        )

    ranked.sort(
        key=lambda x: (
            not x[
                "_both_clean"
            ],
            -x[
                "_pair_quality"
            ],
            -x[
                "_mean_quality"
            ],
            x[
                "_tie"
            ],
        )
    )

    return ranked


# ============================================================
# Maximize video diversity.
# ============================================================

def choose_candidates(
    ranked,
):
    selected = []
    used_video = set()
    used_pair = set()

    # Pass 1:
    # one best pair from each video.
    for pair in ranked:
        video = norm(
            pair[
                "video_id"
            ]
        )

        if (
            video
            and video in used_video
        ):
            continue

        selected.append(
            pair
        )

        used_pair.add(
            pair[
                "pair_id"
            ]
        )

        if video:
            used_video.add(
                video
            )

        if len(
            selected
        ) >= N:
            break

    # Only fallback if fewer than N unique videos survive.
    if len(selected) < N:
        for pair in ranked:
            if (
                pair[
                    "pair_id"
                ]
                in used_pair
            ):
                continue

            selected.append(
                pair
            )

            used_pair.add(
                pair[
                    "pair_id"
                ]
            )

            if len(
                selected
            ) >= N:
                break

    return selected


def main():
    OUT_ROOT.mkdir(
        parents=True,
        exist_ok=True,
    )

    ranked = rank_pairs()

    selected = (
        choose_candidates(
            ranked
        )
    )

    if len(selected) < N:
        print(
            f"WARNING: only {len(selected)} "
            f"candidates available"
        )

    unique_videos = len(
        {
            norm(
                x[
                    "video_id"
                ]
            )
            for x in selected
            if norm(
                x[
                    "video_id"
                ]
            )
        }
    )

    both_clean = sum(
        bool(
            x[
                "_both_clean"
            ]
        )
        for x in selected
    )

    print()
    print("=" * 80)
    print(
        "HumanVid BEST Showcase Candidates"
    )
    print("=" * 80)

    print(
        "selected      :",
        len(selected),
    )

    print(
        "unique videos :",
        unique_videos,
    )

    print(
        "both clean    :",
        both_clean,
    )

    print()

    rows = []

    for rank, pair in enumerate(
        selected,
        1,
    ):
        out = base.make_sheet(
            pair,
            rank,
        )

        src = pair[
            "source"
        ]

        tgt = pair[
            "target"
        ]

        print(
            f"[{rank:02d}/{len(selected)}] "
            f"Q={pair['_pair_quality']:.3f} "
            f"S={pair['_source_quality']:.3f} "
            f"T={pair['_target_quality']:.3f} "
            f"clean={pair['_both_clean']} "
            f"video={pair['video_id']}"
        )

        rows.append({
            "rank":
                rank,

            "pair_id":
                pair[
                    "pair_id"
                ],

            "split":
                pair[
                    "split"
                ],

            "video_id":
                pair[
                    "video_id"
                ],

            "segment_id":
                pair[
                    "segment_id"
                ],

            "both_clean":
                pair[
                    "_both_clean"
                ],

            "source_quality":
                pair[
                    "_source_quality"
                ],

            "target_quality":
                pair[
                    "_target_quality"
                ],

            "pair_quality":
                pair[
                    "_pair_quality"
                ],

            "source_rgb_path":
                src[
                    "native_rgb_path"
                ],

            "target_rgb_path":
                tgt[
                    "native_rgb_path"
                ],

            "target_dwpose_path":
                tgt[
                    "dwpose_npz_path"
                ],

            "target_normal_path":
                tgt[
                    "normal_path"
                ],

            "target_depth_path":
                tgt[
                    "depth_path"
                ],

            "showcase_path":
                str(out),
        })

    pd.DataFrame(
        rows
    ).to_csv(
        OUT_CSV,
        index=False,
    )

    print()
    print("=" * 80)
    print("DONE")
    print("=" * 80)

    print(
        "candidates   :",
        len(selected),
    )

    print(
        "unique videos:",
        unique_videos,
    )

    print(
        "output       :",
        OUT_ROOT,
    )

    print(
        "manifest     :",
        OUT_CSV,
    )


if __name__ == "__main__":
    main()

