]


QUANTILES = [
    .01,
    .05,
    .10,
    .25,
    .50,
    .75,
    .90,
    .95,
    .99,
]


# ============================================================
# Helpers
# ============================================================

def add_distribution_stats(
    row,
    prefix,
    values
):
    x = np.asarray(
        values
    )

    x = x[
        np.isfinite(x)
    ]

    row[
        f"{prefix}_count"
    ] = int(
        len(x)
    )

    if len(x) == 0:

        for name in [
            "mean",
            "min",
            "p01",
            "p05",
            "p10",
            "p25",
            "p50",
            "p75",
            "p90",
            "p95",
            "p99",
            "max",
        ]:
            row[
                f"{prefix}_{name}"
            ] = np.nan

        return


    row[
        f"{prefix}_mean"
    ] = float(
        np.mean(x)
    )

    row[
        f"{prefix}_min"
    ] = float(
        np.min(x)
    )

    q = np.quantile(
        x,
        QUANTILES
    )

    for p, v in zip(
        QUANTILES,
        q
    ):

        row[
            f"{prefix}_p{int(round(p*100)):02d}"
        ] = float(v)


    row[
        f"{prefix}_max"
    ] = float(
        np.max(x)
    )


def concat_chunks(
    chunks,
    dtype=np.float32
):

    if not chunks:

        return np.empty(
            0,
            dtype=dtype
        )

    return np.concatenate(
        chunks
    ).astype(
        dtype,
        copy=False
    )


def pose_pairwise_block(
    pose_block,
    visible_block,
    pose_all,
    visible_all,
):

    diff = (
        pose_block[:, None, :, :]
        -
        pose_all[None, :, :, :]
    )

    joint_distance = np.sqrt(
        np.sum(
            diff * diff,
            axis=-1
        )
    )


    common = (
        visible_block[:, None, :]
        &
        visible_all[None, :, :]
    )


    common_count = np.sum(
        common,
        axis=-1
    )


    numerator = np.sum(
        joint_distance
        *
        common,
        axis=-1
    )


    distance = (
        numerator
        /
        np.maximum(
            common_count,
            1
        )
    ).astype(
        np.float32
    )


    distance[
        common_count
        <
        MIN_COMMON_JOINTS
    ] = np.nan


    return (
        distance,
        common_count
    )


def scale_ratio_block(
    scale_block,
    scale_all
):

    a = scale_block[
        :, None
    ]

    b = scale_all[
        None, :
    ]


    return np.maximum(
        a / b,
        b / a
    ).astype(
        np.float32
    )


def camera_translation_block(
    t_block,
    t_all
):

    d = (
        t_block[:, None, :]
        -
        t_all[None, :, :]
    )


    return np.sqrt(
        np.sum(
            d * d,
            axis=-1
        )
    ).astype(
        np.float32
    )


def camera_rotation_block(
    R_block,
    R_all
):

    trace_rel = np.einsum(
        "bij,nij->bn",
        R_block,
        R_all,
        optimize=True
    )


    c = (
        trace_rel
        -
        1.0
    ) / 2.0


    c = np.clip(
        c,
        -1.0,
        1.0
    )


    return np.degrees(
        np.arccos(
            c
        )
    ).astype(
        np.float32
    )


def source_count_stats(
    row,
    counts
):

    counts = np.asarray(
        counts,
        dtype=np.int64
    )


    row[
        "source_count"
    ] = int(
        len(counts)
    )

    row[
        "covered_source_count"
    ] = int(
        (
            counts > 0
        ).sum()
    )

    row[
        "zero_candidate_sources"
    ] = int(
        (
            counts == 0
        ).sum()
    )

    row[
        "source_coverage_ratio"
    ] = float(
        (
            counts > 0
        ).mean()
    )


    q = np.quantile(
        counts,
        QUANTILES
    )


    row[
        "candidates_per_source_mean"
    ] = float(
        np.mean(
            counts
        )
    )


    for p, v in zip(
        QUANTILES,
        q
    ):

        row[
            f"candidates_per_source_p{int(round(p*100)):02d}"
        ] = float(v)


    row[
        "candidates_per_source_max"
    ] = int(
        counts.max()
    )


