            cfg["name"]
        ] = {

            "valid_pairs":
                0,

            "source_counts":
                [],

            "pose_values":
                [],
        }


    sequence_rows = []

    total_pairs = 0
    total_pose_valid = 0


    groups = list(
        meta.groupby(
            [
                "split",
                "sequence"
            ],
            sort=False
        )
    )


    for (
        split,
        sequence
    ), group in tqdm(
        groups,
        desc="Single sequences"
    ):

        group = (
            group
            .sort_values(
                "frame_index"
            )
            .reset_index(
                drop=True
            )
        )


        idx = group[
            "descriptor_index"
        ].to_numpy(
            dtype=np.int64
        )


        pose = np.nan_to_num(
            all_pose[idx],
            nan=0.0,
            posinf=0.0,
            neginf=0.0
        ).astype(
            np.float32,
            copy=False
        )


        visible = all_visible[
            idx
        ].astype(
            bool,
            copy=False
        )


        scale = all_scale[
            idx
        ].astype(
            np.float32,
            copy=False
        )


        R = all_R[
            idx
        ].astype(
            np.float32,
            copy=False
        )


        t = all_t[
            idx
        ].astype(
            np.float32,
            copy=False
        )


        n = len(
            group
        )


        expected_pairs = (
            n * (n - 1) // 2
        )

        total_pairs += expected_pairs


        seq_counts = {
            cfg["name"]:
                np.zeros(
                    n,
                    dtype=np.int32
                )

            for cfg in CONFIGS
        }


        seq_valid_pairs = {
            cfg["name"]:
                0

            for cfg in CONFIGS
        }


        seq_pose_valid = 0


        cols = np.arange(
            n,
            dtype=np.int64
        )[None, :]


        for a in range(
            0,
            n,
            BLOCK
        ):

            b = min(
                a + BLOCK,
                n
            )


            rows = np.arange(
                a,
                b,
                dtype=np.int64
            )[:, None]


            upper = (
                cols > rows
            )


            pose_distance, _ = (
                pose_pairwise_block(

                    pose[
                        a:b
