                camera_translation_block(

                    t[
                        a:b
                    ],

                    t
                )
            )


            camera_r = (
                camera_rotation_block(

                    R[
                        a:b
                    ],

                    R
                )
            )


            pose_valid = (
                upper
                &
                np.isfinite(
                    pose_distance
                )
            )


            seq_pose_valid += int(
                pose_valid.sum()
            )


            for cfg in CONFIGS:

                name = cfg[
                    "name"
                ]


                valid = (

                    pose_valid

                    &

                    (
                        scale_ratio
                        <=
                        cfg[
                            "scale_max"
                        ]
                    )

                    &

                    (
                        camera_r
                        <=
                        cfg[
                            "camera_rotation_max"
                        ]
                    )

                    &

