                    valid.sum(
                        axis=1
                    )
                    .astype(
                        np.int32
                    )
                )


                col_counts = (
                    valid.sum(
                        axis=0
                    )
                    .astype(
                        np.int32
                    )
                )


                seq_counts[
                    name
                ][
                    a:b
                ] += row_counts


                seq_counts[
                    name
                ] += col_counts


        total_pose_valid += (
            seq_pose_valid
        )


        for cfg in CONFIGS:

            name = cfg[
                "name"
            ]

            counts = seq_counts[
                name
            ]


