                    ),
            }


            source_count_stats(
                row,
                counts
            )


            sequence_rows.append(
                row
            )


    summary_rows = []


    for cfg in CONFIGS:

        name = cfg[
            "name"
        ]


        counts = concat_chunks(
            accum[
                name
            ][
                "source_counts"
            ],
            dtype=np.int32
        )


        poses = concat_chunks(
            accum[
                name
            ][
                "pose_values"
            ],
            dtype=np.float32
        )


        valid_pairs = int(
            accum[
                name
            ][
                "valid_pairs"
            ]
        )


        # correctness check:
        # every valid unordered pair contributes
        # to 2 directed candidate counts.
        expected_sum = (
            2 * valid_pairs
        )


        if int(
            counts.sum()
        ) != expected_sum:

            raise RuntimeError(
                f"{name}: candidate count check failed: "
                f"{int(counts.sum())} != {expected_sum}"
            )


        row = {

            "dataset":
                "single",

            "config":
                name,

            "scale_max":
                cfg[
                    "scale_max"
                ],

            "camera_rotation_max":
                cfg[
                    "camera_rotation_max"
                ],

            "camera_translation_max":
                cfg[
                    "camera_translation_max"
                ],

            "unordered_pair_count":
                int(
                    total_pairs
                ),

            "pose_valid_pairs":
                int(
                    total_pose_valid
                ),

            "valid_pairs":
                valid_pairs,

            "directed_candidate_edges":
                int(
                    expected_sum
                ),

            "pair_retention_all":
                float(
                    valid_pairs
                    /
                    total_pairs
                ),

            "pair_retention_pose_valid":
                float(
                    valid_pairs
                    /
                    total_pose_valid
                ),
        }


        source_count_stats(
            row,
            counts
        )


        add_distribution_stats(
            row,
            "pose_distance",
            poses
        )


        summary_rows.append(
            row
