# ============================================================
# Statistics
# ============================================================

def stats(arr):

    x = np.asarray(arr)

    x = x[
        np.isfinite(x)
    ]

    if len(x) == 0:
        return {
            "count": 0
        }

    q = np.quantile(
        x,
        QUANTILES
    )

    out = {
        "count":
            int(len(x)),

        "mean":
            float(np.mean(x)),

        "std":
            float(np.std(x)),

        "min":
            float(np.min(x)),

        "max":
            float(np.max(x)),
    }

    for p, value in zip(
        QUANTILES,
        q
    ):

        name = f"p{int(round(p * 100)):02d}"

        out[name] = float(
            value
        )

    return out


def add_stats(
    row,
    prefix,
    arr
):

    s = stats(
        arr
    )

    for k, v in s.items():

        row[
            f"{prefix}_{k}"
        ] = v


def concat(chunks, dtype=None):

    if not chunks:

        return np.empty(
            0,
            dtype=dtype or np.float32
        )

    x = np.concatenate(
        chunks
    )

    if dtype is not None:

        x = x.astype(
            dtype,
            copy=False
        )

    return x


# ============================================================
# Pairwise kernels
# ============================================================

def pose_pairwise_block(
    pose_block,
    vis_block,
    pose_all,
    vis_all
):
    """
    pose_block : [B, J, 2]
    pose_all   : [N, J, 2]
    """

    diff = (
        pose_block[:, None, :, :]
        -
        pose_all[None, :, :, :]
    )

    joint_dist = np.sqrt(
        np.sum(
            diff * diff,
            axis=-1
        )
    )

    common = (
        vis_block[:, None, :]
        &
        vis_all[None, :, :]
    )

    common_count = np.sum(
        common,
        axis=-1
    )

    numerator = np.sum(
        joint_dist
        *
        common,
        axis=-1
    )

    denominator = np.maximum(
        common_count,
        1
    )

    distance = (
        numerator
        /
        denominator
    )

    distance = distance.astype(
        np.float32
    )

    distance[
        common_count
        <
        MIN_COMMON_JOINTS
    ] = np.nan

    return (
        distance,
        common_count.astype(
            np.uint8
        )
    )


def scale_ratio_block(
    scale_block,
    scale_all
):

    a = scale_block[
        :, None
    ]

    b = scale_all[
        None, :
    ]

    ratio1 = a / b
    ratio2 = b / a

    return np.maximum(
        ratio1,
        ratio2
    ).astype(
        np.float32
    )


def camera_translation_block(
    t_block,
    t_all
):

    d = (
        t_block[:, None, :]
        -
        t_all[None, :, :]
    )

    return np.sqrt(
        np.sum(
            d*d,
            axis=-1
        )
    ).astype(
        np.float32
    )


def camera_rotation_block(
    R_block,
    R_all
):
    """
    trace(Ra^T Rb) == Frobenius inner product.
    """

    trace_rel = np.einsum(
        "bij,nij->bn",
        R_block,
        R_all,
        optimize=True
    )

    c = (
        trace_rel - 1.0
    ) / 2.0

    c = np.clip(
        c,
        -1.0,
        1.0
    )

    return np.degrees(
        np.arccos(c)
    ).astype(
        np.float32
    )


# ============================================================
# Gap summaries
# ============================================================

def build_gap_summary(
    gap,
    metrics
):

    rows = []

    for name, lo, hi in GAP_BANDS:

        if hi is None:

            mask = (
                gap >= lo
            )

        else:

            mask = (
                (gap >= lo)
                &
                (gap <= hi)
            )

        row = {
            "gap_band":
                name,

            "pair_count":
                int(
                    mask.sum()
                ),
        }

        for metric_name, values in metrics.items():

            add_stats(
                row,
                metric_name,
                values[mask]
            )

        rows.append(
            row
        )

    return pd.DataFrame(
        rows
    )


