# ============================================================
# Target sampler
# ============================================================

def choose_target(
    source,
    bin_name,
):
    indptr = pool[
        f"{bin_name}_indptr"
    ]

    indices = pool[
        f"{bin_name}_indices"
    ]


    start = int(
        indptr[
            source
        ]
    )

    end = int(
        indptr[
            source + 1
        ]
    )


    candidates = indices[
        start:end
    ]


    if len(candidates) == 0:

        raise RuntimeError(
            f"source={source} has no "
            f"{bin_name} candidates"
        )


    # Mild target-degree correction.
    target_degree = sampling[
        f"{bin_name}_count"
    ][
        candidates
    ].astype(
        np.float64
    )


    weights = (
        1.0
        /
        np.sqrt(
            np.maximum(
                target_degree,
                1.0
            )
        )
    )


    weights /= (
        weights.sum()
    )


    return int(
        rng.choice(
            candidates,
            p=weights
        )
    )


# ============================================================
# Simulate dynamic sampling
# ============================================================

rows = []


