    # --------------------------------------------------------

    available_bin_ids = []


    for bin_id, bin_name in enumerate(
        BIN_NAMES
    ):

        if len(
            sequence_bin_sources[
                seq
            ][
                bin_name
            ]
        ) > 0:

            available_bin_ids.append(
                bin_id
            )


    if not available_bin_ids:

        raise RuntimeError(
            f"sequence {seq} has no available bins"
        )


    available_bin_ids = np.asarray(
        available_bin_ids,
        dtype=np.int64
    )


    probs = DESIRED_BIN_WEIGHTS[
        available_bin_ids
    ].copy()


    probs /= (
        probs.sum()
    )


    bin_id = int(
        rng.choice(
            available_bin_ids,
            p=probs
        )
    )


    bin_name = BIN_NAMES[
        bin_id
    ]


    # --------------------------------------------------------
    # 3. Uniform source among sources supporting this bin
    # --------------------------------------------------------

    source_pool = sequence_bin_sources[
        seq
    ][
        bin_name
    ]


    source = int(
        rng.choice(
            source_pool
        )
    )


    # --------------------------------------------------------
    # 4. Degree-aware target
    # --------------------------------------------------------

    target = choose_target(
        source,
        bin_name
    )


    # --------------------------------------------------------
