# ============================================================
# Frozen pair-level rules
# ============================================================

BLOCK = 128

MIN_COMMON_JOINTS = 5

SCALE_MAX = 1.20
CAM_ROT_MAX = 5.0
CAM_TRANS_MAX = 0.50

SINGLE_POSE_MIN = 0.05

TWO_MEAN_MIN = 0.05
TWO_MIN_PERSON_MIN = 0.02

# train-only terciles
Q_SMALL_END = 1.0 / 3.0
Q_MEDIUM_END = 2.0 / 3.0


# ============================================================
# Pairwise helpers
# ============================================================

def pose_distance_block(
    pose_block,
    visible_block,
    pose_all,
    visible_all,
):
    diff = (
        pose_block[:, None, :, :]
        -
        pose_all[None, :, :, :]
    )

    joint_dist = np.sqrt(
        np.sum(
            diff * diff,
            axis=-1
        )
    )

    common = (
        visible_block[:, None, :]
        &
        visible_all[None, :, :]
    )

    common_count = np.sum(
        common,
        axis=-1
    )

    numerator = np.sum(
        joint_dist * common,
        axis=-1
    )

    distance = (
        numerator
        /
        np.maximum(
            common_count,
            1
        )
    ).astype(
        np.float32
    )

    distance[
        common_count < MIN_COMMON_JOINTS
    ] = np.nan

    return distance


def scale_ratio_block(
    a,
    b,
):
    x = a[:, None]
    y = b[None, :]

    return np.maximum(
        x / y,
        y / x
    ).astype(
        np.float32
    )


def camera_translation_block(
    a,
    b,
):
    d = (
        a[:, None, :]
        -
        b[None, :, :]
    )

    return np.sqrt(
        np.sum(
            d * d,
            axis=-1
        )
    ).astype(
        np.float32
    )


def camera_rotation_block(
    a,
    b,
):
    trace_rel = np.einsum(
        "bij,nij->bn",
        a,
        b,
        optimize=True
    )

    cos_theta = (
        trace_rel - 1.0
    ) / 2.0

    cos_theta = np.clip(
        cos_theta,
        -1.0,
        1.0
    )

    return np.degrees(
        np.arccos(
            cos_theta
        )
    ).astype(
        np.float32
    )


def check_descriptor_index(meta):

    idx = meta[
        "descriptor_index"
    ].to_numpy(
        dtype=np.int64
    )

    expected = np.arange(
        len(meta),
        dtype=np.int64
    )

    if not np.array_equal(
        idx,
        expected
    ):
        raise RuntimeError(
            "descriptor_index is not contiguous 0..N-1"
        )


# ============================================================
# CSR helpers
# ============================================================

def chunks_to_csr(
    source_chunks,
    target_chunks,
    n_sources,
):

    if not source_chunks:

        return (
            np.zeros(
                n_sources + 1,
                dtype=np.int64
            ),
            np.empty(
                0,
                dtype=np.int32
            )
        )


    sources = np.concatenate(
        source_chunks
    ).astype(
        np.int32,
        copy=False
    )

    targets = np.concatenate(
        target_chunks
    ).astype(
        np.int32,
        copy=False
    )


    order = np.argsort(
        sources,
        kind="stable"
    )

    sources = sources[
        order
    ]

    targets = targets[
        order
    ]


    counts = np.bincount(
        sources,
        minlength=n_sources
    ).astype(
        np.int64
    )


    indptr = np.empty(
        n_sources + 1,
        dtype=np.int64
    )

    indptr[0] = 0

    np.cumsum(
        counts,
        out=indptr[1:]
    )


    return (
        indptr,
        targets
    )


def csr_counts(
    indptr
):
    return np.diff(
        indptr
    )


def count_summary(
    indptr
):

    counts = csr_counts(
        indptr
    )

    q = np.quantile(
        counts,
        [
            .01,
            .05,
            .10,
            .25,
            .50,
            .75,
            .90,
            .95,
            .99,
        ]
    )

    return {
        "edges":
            int(
                indptr[-1]
            ),

        "covered_sources":
            int(
                (counts > 0).sum()
            ),

        "zero_sources":
            int(
                (counts == 0).sum()
            ),

        "coverage":
            float(
                (counts > 0).mean()
            ),

        "mean":
            float(
                counts.mean()
            ),

        "p01": float(q[0]),
        "p05": float(q[1]),
        "p10": float(q[2]),
        "p25": float(q[3]),
        "p50": float(q[4]),
        "p75": float(q[5]),
        "p90": float(q[6]),
        "p95": float(q[7]),
        "p99": float(q[8]),

        "max":
            int(
                counts.max()
            ),
    }


def all_bin_coverage(
    small_indptr,
    medium_indptr,
    large_indptr,
):

    total = (
        csr_counts(
            small_indptr
        )
        +
        csr_counts(
            medium_indptr
        )
        +
        csr_counts(
            large_indptr
        )
    )

    return {
        "covered_sources":
            int(
                (total > 0).sum()
            ),

        "zero_sources":
            int(
                (total == 0).sum()
            ),

        "coverage":
            float(
                (total > 0).mean()
            ),

        "candidate_mean":
            float(
                total.mean()
            ),

        "candidate_median":
            float(
                np.median(
                    total
                )
            ),
    }


# ============================================================
# PASS 1 — train-only thresholds
# ============================================================

def get_single_train_scores(
    meta,
    data,
):

    chunks = []

    train = meta[
        meta["split"] == "train"
    ]


    groups = list(
        train.groupby(
            [
                "split",
                "sequence"
            ],
            sort=False
        )
    )


    for _, group in tqdm(
        groups,
        desc="Single train thresholds"
    ):

        group = (
            group
            .sort_values(
                "frame_index"
            )
            .reset_index(
                drop=True
            )
        )


        idx = group[
            "descriptor_index"
        ].to_numpy(
            dtype=np.int64
        )


        pose = np.nan_to_num(
            data[
                "pose_normalized"
            ][idx],
            nan=0.0,
            posinf=0.0,
            neginf=0.0
        ).astype(
            np.float32,
            copy=False
        )

        vis = data[
            "pose_visible"
        ][idx].astype(
            bool,
            copy=False
        )

        scale = data[
            "torso_scale"
        ][idx].astype(
            np.float32,
            copy=False
        )

        R = data[
            "camera_R"
        ][idx].astype(
            np.float32,
            copy=False
        )

        trans = data[
            "camera_t"
        ][idx].astype(
            np.float32,
            copy=False
        )


        n = len(group)

        cols = np.arange(
            n,
            dtype=np.int64
        )[None, :]


        for a in range(
            0,
            n,
            BLOCK
        ):

            b = min(
                a + BLOCK,
                n
            )

            rows = np.arange(
                a,
                b,
                dtype=np.int64
            )[:, None]

            upper = (
                cols > rows
            )


            pose_d = pose_distance_block(
                pose[a:b],
                vis[a:b],
                pose,
                vis
            )


            scale_d = scale_ratio_block(
                scale[a:b],
                scale
            )


            cam_t = camera_translation_block(
                trans[a:b],
                trans
            )


            cam_r = camera_rotation_block(
                R[a:b],
                R
            )


            valid = (
                upper
                &
                np.isfinite(pose_d)
                &
                (scale_d <= SCALE_MAX)
                &
                (cam_t <= CAM_TRANS_MAX)
                &
                (cam_r <= CAM_ROT_MAX)
                &
                (
                    pose_d
                    >=
                    SINGLE_POSE_MIN
                )
            )


            if valid.any():

                chunks.append(
                    pose_d[
                        valid
                    ].astype(
                        np.float32,
                        copy=False
                    )
                )


    scores = np.concatenate(
        chunks
    )


    q1, q2 = np.quantile(
        scores,
        [
            Q_SMALL_END,
            Q_MEDIUM_END,
        ]
    )


    return (
        float(q1),
        float(q2),
        int(len(scores))
    )


