                a + BLOCK,
                n
            )

            rows = np.arange(
                a,
                b,
                dtype=np.int64
            )[:, None]

            upper = (
                cols > rows
            )


            p0 = pose_distance_block(
                pose[a:b, 0],
                vis[a:b, 0],
                pose[:, 0],
                vis[:, 0]
            )


            p1 = pose_distance_block(
                pose[a:b, 1],
                vis[a:b, 1],
                pose[:, 1],
                vis[:, 1]
            )


            mean_pose = (
                p0 + p1
            ) / 2.0


            min_pose = np.minimum(
                p0,
                p1
            )


            s0 = scale_ratio_block(
                scale[a:b, 0],
                scale[:, 0]
            )

            s1 = scale_ratio_block(
                scale[a:b, 1],
                scale[:, 1]
            )

            max_scale = np.maximum(
                s0,
                s1
            )


            cam_t = camera_translation_block(
                trans[a:b],
                trans
            )


            cam_r = camera_rotation_block(
                R[a:b],
                R
            )


            valid = (
                upper
                &
                np.isfinite(p0)
                &
                np.isfinite(p1)
                &
                (max_scale <= SCALE_MAX)
                &
                (cam_t <= CAM_TRANS_MAX)
                &
                (cam_r <= CAM_ROT_MAX)
                &
                (
                    mean_pose
                    >=
                    TWO_MEAN_MIN
                )
                &
                (
                    min_pose
                    >=
                    TWO_MIN_PERSON_MIN
                )
            )


            if valid.any():

                # IMPORTANT:
                # two-person strata are based on
                # the weaker-moving actor.
                chunks.append(
                    min_pose[
                        valid
                    ].astype(
                        np.float32,
                        copy=False
                    )
                )


    scores = np.concatenate(
        chunks
    )


    q1, q2 = np.quantile(
        scores,
        [
            Q_SMALL_END,
            Q_MEDIUM_END,
        ]
    )


    return (
        float(q1),
        float(q2),
        int(len(scores))
    )


