def build_single_edges(
    meta,
    data,
    q1,
    q2,
):

    bins = {
        "small": {
            "src": [],
            "tgt": [],
        },

        "medium": {
            "src": [],
            "tgt": [],
        },

        "large": {
            "src": [],
            "tgt": [],
        },
    }


    groups = list(
        meta.groupby(
            [
                "split",
                "sequence"
            ],
            sort=False
        )
    )


    for _, group in tqdm(
        groups,
        desc="Single candidate pool"
    ):

        group = (
            group
            .sort_values(
                "frame_index"
            )
            .reset_index(
                drop=True
            )
        )


        idx = group[
            "descriptor_index"
        ].to_numpy(
            dtype=np.int32
        )


        pose = np.nan_to_num(
            data[
                "pose_normalized"
            ][idx],
            nan=0.0,
            posinf=0.0,
            neginf=0.0
        ).astype(
            np.float32,
            copy=False
        )

        vis = data[
            "pose_visible"
        ][idx].astype(
            bool,
            copy=False
        )

        scale = data[
            "torso_scale"
        ][idx].astype(
            np.float32,
            copy=False
        )

        R = data[
            "camera_R"
        ][idx].astype(
            np.float32,
            copy=False
        )

        trans = data[
            "camera_t"
        ][idx].astype(
            np.float32,
            copy=False
        )


        n = len(group)

        cols = np.arange(
            n,
            dtype=np.int64
        )[None, :]


        for a in range(
            0,
            n,
            BLOCK
        ):

            b = min(
                a + BLOCK,
                n
            )

            local_rows = np.arange(
                a,
                b,
                dtype=np.int64
            )[:, None]


            upper = (
                cols > local_rows
            )


            pose_d = pose_distance_block(
                pose[a:b],
                vis[a:b],
                pose,
                vis
            )


            scale_d = scale_ratio_block(
                scale[a:b],
                scale
            )


            cam_t = camera_translation_block(
                trans[a:b],
                trans
            )


            cam_r = camera_rotation_block(
                R[a:b],
                R
            )


            valid = (
                upper
                &
                np.isfinite(pose_d)
                &
                (scale_d <= SCALE_MAX)
                &
                (cam_t <= CAM_TRANS_MAX)
                &
                (cam_r <= CAM_ROT_MAX)
                &
                (
                    pose_d
                    >=
                    SINGLE_POSE_MIN
                )
            )


            bin_masks = {
                "small":
                    (
                        valid
                        &
                        (
                            pose_d < q1
                        )
                    ),

                "medium":
                    (
                        valid
                        &
                        (
                            pose_d >= q1
                        )
                        &
                        (
                            pose_d < q2
                        )
                    ),

                "large":
                    (
                        valid
                        &
                        (
                            pose_d >= q2
                        )
                    ),
            }


            for name, mask in bin_masks.items():

                rr, cc = np.where(
                    mask
                )

                if len(rr) == 0:
                    continue


                gi = idx[
                    a + rr
                ].astype(
                    np.int32,
                    copy=False
                )

                gj = idx[
                    cc
                ].astype(
                    np.int32,
                    copy=False
                )


                # both directions:
                # i -> j and j -> i
                bins[
                    name
                ][
                    "src"
                ].append(
                    np.concatenate(
                        [
                            gi,
                            gj
                        ]
                    )
                )

                bins[
                    name
                ][
                    "tgt"
                ].append(
                    np.concatenate(
                        [
                            gj,
                            gi
                        ]
                    )
                )


    return bins


