def split_bin_stats(
    meta,
    indptr,
):

    counts = csr_counts(
        indptr
    )

    result = {}

    for split in [
        "train",
        "validation",
        "test",
    ]:

        mask = (
            meta[
                "split"
            ].to_numpy()
            ==
            split
        )

        x = counts[
            mask
        ]

        if len(x) == 0:

            continue

        result[
            split
        ] = {

            "sources":
                int(
                    len(x)
                ),

            "edges":
                int(
                    x.sum()
                ),

            "covered_sources":
                int(
                    (x > 0).sum()
                ),

            "coverage":
                float(
                    (x > 0).mean()
                ),

            "median_candidates":
                float(
                    np.median(x)
                ),
        }


    return result


