# ============================================================
# Frozen pair rules
# ============================================================

BLOCK = 128

MIN_COMMON_JOINTS = 5

POSE_MIN = 0.05

SCALE_MAX = 1.20

CAM_ROT_MAX = 5.0

CAM_TRANS_MAX = 0.50


Q1 = 1.0 / 3.0
Q2 = 2.0 / 3.0


# ============================================================
# Pairwise helpers
# ============================================================

def pose_distance_block(
    pose_block,
    visible_block,
    pose_all,
    visible_all,
):
    diff = (
        pose_block[:, None, :, :]
        -
        pose_all[None, :, :, :]
    )

    joint_dist = np.sqrt(
        np.sum(
            diff * diff,
            axis=-1
        )
    )

    common = (
        visible_block[:, None, :]
        &
        visible_all[None, :, :]
    )

    common_count = np.sum(
        common,
        axis=-1
    )

    numerator = np.sum(
        joint_dist * common,
        axis=-1
    )

    distance = (
        numerator
        /
        np.maximum(
            common_count,
            1
        )
    ).astype(
        np.float32
    )

    distance[
        common_count
        <
        MIN_COMMON_JOINTS
    ] = np.nan

    return distance


def scale_ratio_block(
    scale_block,
    scale_all,
):
    a = scale_block[
        :, None
    ]

    b = scale_all[
        None, :
    ]

    return np.maximum(
        a / b,
        b / a
    ).astype(
        np.float32
    )


def camera_translation_block(
    t_block,
    t_all,
):
    d = (
        t_block[:, None, :]
        -
        t_all[None, :, :]
    )

    return np.sqrt(
        np.sum(
            d * d,
            axis=-1
        )
    ).astype(
        np.float32
    )


def camera_rotation_block(
    R_block,
    R_all,
):
    trace_rel = np.einsum(
        "bij,nij->bn",
        R_block,
        R_all,
        optimize=True
    )

    cos_theta = (
        trace_rel - 1.0
    ) / 2.0

    cos_theta = np.clip(
        cos_theta,
        -1.0,
        1.0
    )

    return np.degrees(
        np.arccos(
            cos_theta
        )
    ).astype(
        np.float32
    )


# ============================================================
# CSR helpers
# ============================================================

def build_csr(
    source_chunks,
    target_chunks,
    n_sources,
):
    if not source_chunks:
        return (
            np.zeros(
                n_sources + 1,
                dtype=np.int64
            ),
            np.empty(
                0,
                dtype=np.int32
            ),
        )

    source = np.concatenate(
        source_chunks
    ).astype(
        np.int32,
        copy=False
    )

    target = np.concatenate(
        target_chunks
    ).astype(
        np.int32,
        copy=False
    )

    order = np.argsort(
        source,
        kind="stable"
    )

    source = source[
        order
    ]

    target = target[
        order
    ]

    counts = np.bincount(
        source,
        minlength=n_sources
    ).astype(
        np.int64
    )

    indptr = np.zeros(
        n_sources + 1,
        dtype=np.int64
    )

    np.cumsum(
        counts,
        out=indptr[1:]
    )

    return (
        indptr,
        target
    )


def count_stats(
    indptr,
):
    counts = np.diff(
        indptr
    )

    q = np.quantile(
        counts,
        [
            .01,
            .05,
            .10,
            .25,
            .50,
            .75,
            .90,
            .95,
            .99,
        ]
    )

    return {
        "edges":
            int(
                indptr[-1]
            ),

        "covered_sources":
            int(
                (
                    counts > 0
                ).sum()
            ),

        "zero_sources":
            int(
                (
                    counts == 0
                ).sum()
            ),

        "coverage":
            float(
                (
                    counts > 0
                ).mean()
            ),

        "mean":
            float(
                counts.mean()
            ),

        "p01":
            float(q[0]),

        "p05":
            float(q[1]),

        "p10":
            float(q[2]),

        "p25":
            float(q[3]),

        "p50":
            float(q[4]),

        "p75":
            float(q[5]),

        "p90":
            float(q[6]),

        "p95":
            float(q[7]),

        "p99":
            float(q[8]),

        "max":
            int(
                counts.max()
            ),
    }


