# ============================================================
# Candidate helpers
# ============================================================

def get_targets(
    source,
    bin_name,
):
    indptr = pool[
        f"{bin_name}_indptr"
    ]

    indices = pool[
        f"{bin_name}_indices"
    ]

    start = int(
        indptr[source]
    )

    end = int(
        indptr[source + 1]
    )

    return indices[
        start:end
    ]


def available_bins(
    source,
):
    result = []

    for bin_name in BINS:

        if len(
            get_targets(
                source,
                bin_name
            )
        ) > 0:

            result.append(
                bin_name
            )

    return result


# ============================================================
# Build one split
# ============================================================

def build_split(
    split,
    seed,
):
    rng = np.random.default_rng(
        seed
    )


    split_df = meta[
        meta["split"] == split
    ].copy()


    sequences = sorted(
        split_df[
            "sequence"
        ].unique()
    )


    # --------------------------------------------------------
    # Sequence -> usable sources
    # --------------------------------------------------------

    sequence_sources = {}


    for sequence in sequences:

        candidate_sources = split_df[
            split_df[
                "sequence"
            ]
            ==
            sequence
        ][
            "descriptor_index"
        ].to_numpy(
            dtype=np.int32
        )


        usable = []

        for source in candidate_sources:

            source = int(
                source
            )

            if available_bins(
                source
            ):

                usable.append(
                    source
                )


        sequence_sources[
            sequence
        ] = np.asarray(
            usable,
            dtype=np.int32
        )


    # --------------------------------------------------------
    # Shuffle source order once per sequence.
    #
    # We prefer source uniqueness:
    # each source is used once before any source is reused.
    # --------------------------------------------------------

    source_orders = {}


    for sequence, sources in sequence_sources.items():

        order = sources.copy()

        rng.shuffle(
            order
        )

        source_orders[
            sequence
        ] = order


    source_pointer = {
        sequence: 0
        for sequence
        in sequences
    }


    source_usage = Counter()
    target_usage = Counter()
    pair_usage = set()


    rows = []


    # Randomized sequence round-robin.
    sequence_cycle = list(
        sequences
    )


    round_id = 0


    while len(rows) < PAIRS_PER_SPLIT:

        current_sequences = list(
            sequence_cycle
        )

        rng.shuffle(
            current_sequences
        )

        progress = False


        for sequence in current_sequences:

            if len(rows) >= PAIRS_PER_SPLIT:
                break


            sources = source_orders[
                sequence
            ]


            if len(sources) == 0:
                continue


            # ------------------------------------------------
            # Prefer a never-used source.
            # ------------------------------------------------

            pointer = source_pointer[
                sequence
            ]


            if pointer < len(sources):

                source = int(
                    sources[
                        pointer
                    ]
                )

                source_pointer[
                    sequence
                ] += 1

            else:

                # Only if a sequence runs out of unique
                # sources do we allow source reuse.
                usage = np.asarray(
                    [
                        source_usage[
                            int(s)
                        ]
                        for s
                        in sources
                    ],
                    dtype=np.int32
                )

                min_usage = int(
                    usage.min()
                )

                candidates = sources[
                    usage == min_usage
                ]

                source = int(
                    rng.choice(
                        candidates
                    )
                )


            bins = available_bins(
                source
            )


            if not bins:
                continue


            # ------------------------------------------------
            # Natural pose-bin sampling:
            #
            # no global 1:1:1 target;
            # choose uniformly only among bins this source
            # actually supports.
            # ------------------------------------------------

            bin_name = str(
                rng.choice(
                    bins
                )
            )


            targets = get_targets(
                source,
                bin_name
            )


            if len(targets) == 0:
                continue


            # ------------------------------------------------
            # Prefer least-used target.
            #
            # This controls evaluation duplication without
            # changing pair validity or forcing pose-bin ratios.
            # ------------------------------------------------

            target_use = np.asarray(
                [
                    target_usage[
                        int(t)
                    ]
                    for t
                    in targets
                ],
                dtype=np.int32
            )


            min_use = int(
                target_use.min()
            )


            preferred_targets = targets[
                target_use == min_use
            ].copy()


            rng.shuffle(
                preferred_targets
            )


            target = None


            # Prefer unseen directed pair.
            for candidate in preferred_targets:

                candidate = int(
                    candidate
                )

                if (
                    source,
                    candidate
                ) not in pair_usage:

                    target = candidate
                    break


            if target is None:

                all_targets = targets.copy()

                rng.shuffle(
                    all_targets
                )

                for candidate in all_targets:

                    candidate = int(
                        candidate
                    )

                    if (
                        source,
                        candidate
                    ) not in pair_usage:

                        target = candidate
                        break


            if target is None:
                continue


            source_row = meta.iloc[
                source
            ]

            target_row = meta.iloc[
                target
            ]


            # ------------------------------------------------
            # Strong validation
            # ------------------------------------------------

            if source == target:
                raise RuntimeError(
                    "source == target"
                )


            if (
                source_row["split"]
                !=
                split
                or
                target_row["split"]
                !=
                split
            ):
                raise RuntimeError(
                    "cross-split pair"
                )


            if (
                source_row["sequence"]
                !=
                target_row["sequence"]
            ):
                raise RuntimeError(
                    "cross-sequence pair"
                )


            source_usage[
                source
            ] += 1

            target_usage[
                target
            ] += 1

            pair_usage.add(
                (
                    source,
                    target
                )
            )


            rows.append(
                {
                    "pair_id":
                        len(rows),

                    "split":
                        split,

                    "sequence":
                        sequence,

                    "pose_bin":
                        bin_name,

                    "source_descriptor_index":
                        source,

                    "target_descriptor_index":
                        target,

                    "source_old_descriptor_index":
                        int(
                            source_row[
                                "old_descriptor_index"
                            ]
                        ),

                    "target_old_descriptor_index":
                        int(
                            target_row[
                                "old_descriptor_index"
                            ]
                        ),

                    "source_frame_index":
                        int(
                            source_row[
                                "frame_index"
                            ]
                        ),

                    "target_frame_index":
                        int(
                            target_row[
                                "frame_index"
                            ]
                        ),
                }
            )


            progress = True


        if not progress:

            raise RuntimeError(
                f"{split}: sampling made no progress."
            )


        round_id += 1


        if round_id > 10000:

            raise RuntimeError(
                f"{split}: sampling loop overflow."
            )


    result = pd.DataFrame(
        rows
    )


    # ========================================================
    # Final checks
    # ========================================================

    if len(result) != PAIRS_PER_SPLIT:

        raise RuntimeError(
            f"{split}: expected "
            f"{PAIRS_PER_SPLIT}, got {len(result)}"
        )


    duplicate_pairs = int(
        result.duplicated(
            [
                "source_descriptor_index",
                "target_descriptor_index",
            ]
        ).sum()
    )


    if duplicate_pairs != 0:

        raise RuntimeError(
            f"{split}: duplicate directed pairs found."
        )


    return (
        result,
        source_usage,
        target_usage,
    )


# ============================================================
# Build val / test
# ============================================================

val_df, val_source_usage, val_target_usage = build_split(
