def build_dir_index(directory):
    index = {}

    directory = Path(
        directory
    )

    if not directory.is_dir():
        return index

    for p in directory.iterdir():

        if not p.is_file():
            continue

        try:
            number = int(
                p.stem
            )
        except ValueError:
            continue

        index[
            number
        ] = p

    return index


# ============================================================
# Percentile helpers
# ============================================================

def percentile_rank(
    value,
    sorted_values,
):
    if (
        not np.isfinite(value)
        or len(sorted_values) == 0
    ):
        return float("nan")

    if len(sorted_values) == 1:
        return 0.5

    left = int(
        np.searchsorted(
            sorted_values,
            value,
            side="left",
        )
    )

    right = int(
        np.searchsorted(
            sorted_values,
            value,
            side="right",
        )
    )

    rank = (
        left + right - 1
    ) / 2.0

    return float(
        rank
        /
        (
            len(sorted_values)
            - 1
        )
    )


def finite_sorted(values):
    return np.asarray(
        sorted(
            float(v)
            for v in values
            if np.isfinite(v)
        ),
        dtype=np.float64,
    )


def quantiles(arr):
    arr = np.asarray(
        [
            x
            for x in arr
            if np.isfinite(x)
        ],
        dtype=np.float64,
    )

    if len(arr) == 0:
        return {}

    result = {}

    for q in [
        0.00,
        0.01,
        0.05,
        0.10,
        0.25,
        0.50,
        0.75,
        0.90,
        0.95,
        0.99,
        1.00,
    ]:
        result[
            str(q)
        ] = float(
            np.quantile(
                arr,
                q,
            )
        )

    return result


