def resize_keep_height(
    img,
    h,
):
    if img is None:
        return np.zeros(
            (
                h,
                h,
                3,
            ),
            dtype=np.uint8,
        )

    H, W = img.shape[:2]

    scale = (
        h / H
    )

    target_w = max(
        1,
        int(W * scale),
    )

    return cv2.resize(
        img,
        (
            target_w,
            h,
        ),
        interpolation=cv2.INTER_AREA,
    )


def fit_width(
    img,
    width,
):
    H, W = img.shape[:2]

    if W == width:
        return img

    if W > width:
        return cv2.resize(
            img,
            (
                width,
                H,
            ),
            interpolation=cv2.INTER_AREA,
        )

    canvas = np.zeros(
        (
            H,
            width,
            3,
        ),
        dtype=np.uint8,
    )

    x = (
        width - W
    ) // 2

    canvas[
        :,
        x:x + W,
    ] = img

    return canvas


def put_header(
    panel,
    lines,
):
    header_h = (
        24 * len(lines)
        + 8
    )

    canvas = np.zeros(
        (
            panel.shape[0]
            + header_h,
            panel.shape[1],
            3,
        ),
        dtype=np.uint8,
    )

    canvas[
        header_h:,
        :
    ] = panel

    for i, line in enumerate(
        lines
    ):
        cv2.putText(
            canvas,
            str(line),
            (
                5,
                20 + i * 24,
            ),
            cv2.FONT_HERSHEY_SIMPLEX,
            0.42,
            (
                255,
                255,
                255,
            ),
            1,
            cv2.LINE_AA,
        )

    return canvas


def make_global_panel(
    record,
    image_indices,
):
    seq = record[
        "sequence_id"
    ]

    n = int(
        record[
            "_frame_num_int"
        ]
    )

    idx = image_indices[
        seq
    ]

    prev_img = read_bgr(
        idx.get(
            n - 1
        )
    )

    current = read_bgr(
        record["rgb"]
    )

    next_img = read_bgr(
        idx.get(
            n + 1
        )
    )

    H = 220

    panels = [
        resize_keep_height(
            prev_img,
            H,
        ),
        resize_keep_height(
            current,
            H,
        ),
        resize_keep_height(
            next_img,
            H,
        ),
    ]

    cell_w = max(
        p.shape[1]
        for p in panels
    )

    panels = [
        fit_width(
            p,
            cell_w,
        )
        for p in panels
    ]

    strip = np.concatenate(
        panels,
        axis=1,
    )

    # mark CURRENT
    cv2.rectangle(
        strip,
        (
            cell_w,
            0,
        ),
        (
            cell_w * 2 - 1,
            H - 1,
        ),
        (
            255,
            255,
            255,
        ),
        3,
    )

    lines = [
        (
            f"{record['split']} "
            f"{seq}/{record['stem']} "
            f"edgeP={record['seq_edge_percentile']:.2f}"
        ),
        (
            f"recover={record['temporal_recovery_ratio']:.2f} "
            f"q95={record['recovery_q95_threshold']:.2f} "
            f"q99={record['recovery_q99_threshold']:.2f}"
        ),
    ]

    return put_header(
        strip,
        lines,
    )


def make_face_panel(
    record,
):
    full = read_bgr(
        record["rgb"]
    )

    kp, scores = load_dwpose(
        record
    )

    face_score, face_crop, meta = (
        score_local_part(
            bgr=full,
            kp=kp,
            scores=scores,
            start=24,
            end=92,
            min_valid=MIN_FACE_VALID_POINTS,
            min_side=MIN_FACE_NATIVE_SIDE,
            target_size=FACE_TARGET_SIZE,
        )
    )

    H = 260

    full_v = resize_keep_height(
        full,
        H,
    )

    if face_crop is None:
        face_v = np.zeros(
            (
                H,
                H,
                3,
            ),
            dtype=np.uint8,
        )
    else:
        face_v = cv2.resize(
            face_crop,
            (
                H,
                H,
            ),
            interpolation=cv2.INTER_LINEAR,
        )

    strip = np.concatenate(
        [
            full_v,
            face_v,
        ],
        axis=1,
    )

    lines = [
        (
            f"{record['split']} "
            f"{record['sequence_id']}/{record['stem']} "
            f"face={record['face_sharpness']:.1f}"
        ),
        (
            f"faceGlobalP={record['face_global_percentile']:.2f} "
            f"faceSeqP={record['face_seq_percentile']:.2f} "
            f"size={record['face_native_short_side']:.1f}px"
        ),
    ]

    return put_header(
        strip,
        lines,
    )


def make_hand_panel(
    record,
):
    full = read_bgr(
        record["rgb"]
    )

    kp, scores = load_dwpose(
        record
    )

    l_score, l_crop, l_meta = (
        score_local_part(
            bgr=full,
            kp=kp,
            scores=scores,
            start=92,
            end=113,
            min_valid=MIN_HAND_VALID_POINTS,
            min_side=MIN_HAND_NATIVE_SIDE,
            target_size=HAND_TARGET_SIZE,
        )
    )

    r_score, r_crop, r_meta = (
        score_local_part(
            bgr=full,
            kp=kp,
            scores=scores,
            start=113,
            end=134,
            min_valid=MIN_HAND_VALID_POINTS,
            min_side=MIN_HAND_NATIVE_SIDE,
            target_size=HAND_TARGET_SIZE,
        )
    )

    H = 230

    full_v = resize_keep_height(
        full,
        H,
    )

    def local_vis(crop):
        if crop is None:
            return np.zeros(
                (
                    H,
                    H,
                    3,
                ),
                dtype=np.uint8,
            )

        return cv2.resize(
            crop,
            (
                H,
                H,
            ),
            interpolation=cv2.INTER_LINEAR,
        )

    left_v = local_vis(
        l_crop
    )

    right_v = local_vis(
        r_crop
    )

    strip = np.concatenate(
        [
            full_v,
            left_v,
            right_v,
        ],
        axis=1,
    )

    lines = [
        (
            f"{record['split']} "
            f"{record['sequence_id']}/{record['stem']} "
            f"riskHand={record['hand_risk_side']}"
        ),
        (
            f"L={record['left_hand_sharpness']:.1f} "
            f"Lp={record['left_hand_global_percentile']:.2f} "
            f"Ls={record['left_hand_native_short_side']:.1f}px"
        ),
        (
            f"R={record['right_hand_sharpness']:.1f} "
            f"Rp={record['right_hand_global_percentile']:.2f} "
            f"Rs={record['right_hand_native_short_side']:.1f}px"
        ),
    ]

    return put_header(
        strip,
        lines,
    )


def save_contact_sheets(
    records,
    prefix,
    panel_func,
):
    if not records:
        return []

    PER_SHEET = 16
    COLS = 2

    outputs = []

    for start in range(
        0,
        len(records),
        PER_SHEET,
    ):
        chunk = records[
            start:
            start + PER_SHEET
        ]

        panels = [
            panel_func(r)
            for r in chunk
        ]

        max_h = max(
            p.shape[0]
            for p in panels
        )

        max_w = max(
            p.shape[1]
            for p in panels
        )

        fixed = []

        for p in panels:
            canvas = np.zeros(
                (
                    max_h,
                    max_w,
                    3,
                ),
                dtype=np.uint8,
            )

            canvas[
                :p.shape[0],
                :p.shape[1],
            ] = p

            fixed.append(
                canvas
            )

        rows_out = []

        for i in range(
            0,
            len(fixed),
            COLS,
        ):
            row = fixed[
                i:i + COLS
            ]

            while len(row) < COLS:
                row.append(
                    np.zeros_like(
                        fixed[0]
                    )
                )

            rows_out.append(
                np.concatenate(
                    row,
                    axis=1,
                )
            )

        sheet = np.concatenate(
            rows_out,
            axis=0,
        )

        page = (
            start // PER_SHEET
            + 1
        )

        out = (
            OUT_ROOT
            / f"{prefix}_{page:02d}.jpg"
        )

        cv2.imwrite(
            str(out),
            sheet,
            [
                cv2.IMWRITE_JPEG_QUALITY,
                92,
            ],
        )

        outputs.append(
            str(out)
        )

    return outputs


# ============================================================
# Main
# ============================================================

def main():
    OUT_ROOT.mkdir(
        parents=True,
        exist_ok=True,
    )

    rows = read_jsonl(
        MANIFEST
    )

    print("=" * 78)
    print(
        "TikTok V3 Visual Quality Audit V3"
    )
    print("=" * 78)
    print(
        "frames:",
        len(rows),
    )

    # --------------------------------------------------------
    # Sequence indices
    # --------------------------------------------------------

    by_seq = defaultdict(
        list
    )

    for row in rows:
        by_seq[
            row["sequence_id"]
        ].append(row)

    image_indices = {}
    mask_indices = {}

    for seq, seq_rows in by_seq.items():

        image_dir = Path(
            seq_rows[0]["rgb"]
        ).parent

        mask_dir = Path(
            seq_rows[0]["person_mask"]
        ).parent

        image_indices[
            seq
        ] = build_dir_index(
            image_dir
        )

        mask_indices[
            seq
        ] = build_dir_index(
            mask_dir
        )

    # --------------------------------------------------------
    # Raw-frame global edge cache
    # --------------------------------------------------------

    global_edge_cache = {}

    def raw_person_edge(
        seq,
        frame_num,
    ):
        key = (
            seq,
            int(frame_num),
        )

        if key in global_edge_cache:
            return global_edge_cache[
                key
            ]

        image_path = image_indices[
            seq
        ].get(
            int(frame_num)
        )

        mask_path = mask_indices[
            seq
        ].get(
            int(frame_num)
        )

        if image_path is None:
            global_edge_cache[
                key
            ] = float("nan")

            return float("nan")

        bgr = read_bgr(
            image_path
        )

        if bgr is None:
            global_edge_cache[
                key
            ] = float("nan")

            return float("nan")

        H, W = bgr.shape[:2]

        mask = read_binary_mask(
            mask_path,
            (
                H,
                W,
            ),
        )

        score = edge_sharpness(
            bgr,
            mask,
        )

        global_edge_cache[
            key
        ] = score

        return score

    # --------------------------------------------------------
    # First pass
    # --------------------------------------------------------

    scored = []

    for i, row in enumerate(
        rows,
        1,
    ):
        x = dict(
            row
        )

        try:
            frame_num = int(
                row["stem"]
            )
        except Exception:
            frame_num = int(
                row.get(
                    "frame_num",
                    -1,
                )
            )

        x[
            "_frame_num_int"
        ] = frame_num

        seq = row[
            "sequence_id"
        ]

        # ----------------------
        # Global / person
        # ----------------------

        current_edge = raw_person_edge(
            seq,
            frame_num,
        )

        neighbor_scores = []

        for offset in [
            -2,
            -1,
            1,
            2,
        ]:
            s = raw_person_edge(
                seq,
                frame_num + offset,
            )

            if np.isfinite(s):
                neighbor_scores.append(
                    float(s)
                )

        if (
            np.isfinite(
                current_edge
            )
            and current_edge > 1e-6
            and neighbor_scores
        ):
            # use best two temporal neighbors,
            # not one potentially noisy spike
            top = sorted(
                neighbor_scores,
                reverse=True,
            )[:2]

            neighbor_ref = float(
                np.median(
                    top
                )
            )

            recovery = (
                neighbor_ref
                /
                current_edge
            )

        else:
            neighbor_ref = float(
                "nan"
            )

            recovery = float(
                "nan"
            )

        x[
            "person_edge_sharpness"
        ] = float(
            current_edge
        )

        x[
            "temporal_neighbor_reference"
        ] = float(
            neighbor_ref
        )

        x[
            "temporal_recovery_ratio"
        ] = float(
            recovery
        )

        x[
            "temporal_neighbor_count"
        ] = len(
            neighbor_scores
        )

        # ----------------------
        # Local face / hands
        # ----------------------

        bgr = read_bgr(
            row["rgb"]
        )

        kp, scores = load_dwpose(
            row
        )

        face_score, _, face_meta = (
            score_local_part(
                bgr=bgr,
                kp=kp,
                scores=scores,
                start=24,
                end=92,
                min_valid=MIN_FACE_VALID_POINTS,
                min_side=MIN_FACE_NATIVE_SIDE,
                target_size=FACE_TARGET_SIZE,
            )
        )

        lh_score, _, lh_meta = (
            score_local_part(
                bgr=bgr,
                kp=kp,
                scores=scores,
                start=92,
                end=113,
                min_valid=MIN_HAND_VALID_POINTS,
                min_side=MIN_HAND_NATIVE_SIDE,
                target_size=HAND_TARGET_SIZE,
            )
        )

        rh_score, _, rh_meta = (
            score_local_part(
                bgr=bgr,
                kp=kp,
                scores=scores,
                start=113,
                end=134,
                min_valid=MIN_HAND_VALID_POINTS,
                min_side=MIN_HAND_NATIVE_SIDE,
                target_size=HAND_TARGET_SIZE,
            )
        )

        x[
            "face_evaluable"
        ] = bool(
            face_meta.get(
                "evaluable",
                False,
            )
        )

        x[
            "face_sharpness"
        ] = float(
            face_score
        )

        x[
            "face_native_short_side"
        ] = float(
            face_meta.get(
                "native_short_side",
                float("nan"),
            )
        )

        x[
            "face_valid_points"
        ] = int(
            face_meta.get(
                "valid_points",
                0,
            )
        )

        x[
            "left_hand_evaluable"
        ] = bool(
            lh_meta.get(
                "evaluable",
                False,
            )
        )

        x[
            "left_hand_sharpness"
        ] = float(
            lh_score
        )

        x[
            "left_hand_native_short_side"
        ] = float(
            lh_meta.get(
                "native_short_side",
                float("nan"),
            )
        )

        x[
            "left_hand_valid_points"
        ] = int(
            lh_meta.get(
                "valid_points",
                0,
            )
        )

        x[
            "right_hand_evaluable"
        ] = bool(
            rh_meta.get(
                "evaluable",
                False,
            )
        )

        x[
            "right_hand_sharpness"
        ] = float(
            rh_score
        )

        x[
            "right_hand_native_short_side"
        ] = float(
            rh_meta.get(
                "native_short_side",
                float("nan"),
            )
        )

        x[
            "right_hand_valid_points"
        ] = int(
            rh_meta.get(
                "valid_points",
                0,
            )
        )

        scored.append(
            x
        )

        if (
            i % 500 == 0
            or i == len(rows)
        ):
            print(
                f"{i}/{len(rows)}",
                flush=True,
            )

    # --------------------------------------------------------
    # Global distributions
    # --------------------------------------------------------

    global_edge_values = finite_sorted(
        [
            r[
                "person_edge_sharpness"
            ]
            for r in scored
        ]
    )

    recovery_values = finite_sorted(
        [
            r[
                "temporal_recovery_ratio"
            ]
            for r in scored
        ]
    )

    face_values = finite_sorted(
        [
            r[
                "face_sharpness"
            ]
            for r in scored
            if r[
                "face_evaluable"
            ]
        ]
    )

    left_values = finite_sorted(
        [
            r[
                "left_hand_sharpness"
            ]
            for r in scored
            if r[
                "left_hand_evaluable"
            ]
        ]
    )

    right_values = finite_sorted(
        [
            r[
                "right_hand_sharpness"
            ]
            for r in scored
            if r[
                "right_hand_evaluable"
            ]
        ]
    )

    if len(recovery_values):
        recovery_q95 = float(
            np.quantile(
                recovery_values,
                0.95,
            )
        )

        recovery_q99 = float(
            np.quantile(
                recovery_values,
                0.99,
            )
        )

    else:
        recovery_q95 = float(
            "nan"
        )

        recovery_q99 = float(
            "nan"
        )

    # --------------------------------------------------------
    # Per-sequence distributions
    # --------------------------------------------------------

    scored_by_seq = defaultdict(
        list
    )

    for r in scored:
        scored_by_seq[
            r["sequence_id"]
        ].append(r)

    for seq, seq_rows in scored_by_seq.items():

        seq_edge = finite_sorted(
            [
                r[
                    "person_edge_sharpness"
                ]
                for r in seq_rows
            ]
        )

        seq_face = finite_sorted(
            [
                r[
                    "face_sharpness"
                ]
                for r in seq_rows
                if r[
                    "face_evaluable"
                ]
            ]
        )

        seq_lh = finite_sorted(
            [
                r[
                    "left_hand_sharpness"
                ]
                for r in seq_rows
                if r[
                    "left_hand_evaluable"
                ]
            ]
        )

        seq_rh = finite_sorted(
            [
                r[
                    "right_hand_sharpness"
                ]
                for r in seq_rows
                if r[
                    "right_hand_evaluable"
                ]
            ]
        )

        for r in seq_rows:

            r[
                "sequence_usable_count"
            ] = len(
                seq_rows
            )

            r[
                "seq_edge_percentile"
            ] = percentile_rank(
                r[
                    "person_edge_sharpness"
                ],
                seq_edge,
            )

            r[
                "face_seq_percentile"
            ] = percentile_rank(
                r[
                    "face_sharpness"
                ],
                seq_face,
            )

            r[
                "left_hand_seq_percentile"
            ] = percentile_rank(
                r[
                    "left_hand_sharpness"
                ],
                seq_lh,
            )

            r[
                "right_hand_seq_percentile"
            ] = percentile_rank(
                r[
                    "right_hand_sharpness"
                ],
                seq_rh,
            )

            r[
                "face_seq_evaluable_count"
            ] = len(
                seq_face
            )

            r[
                "left_hand_seq_evaluable_count"
            ] = len(
                seq_lh
            )

            r[
                "right_hand_seq_evaluable_count"
            ] = len(
                seq_rh
            )

    # --------------------------------------------------------
    # Global percentiles for local parts
    # --------------------------------------------------------

    for r in scored:

        r[
            "person_global_percentile"
        ] = percentile_rank(
            r[
                "person_edge_sharpness"
            ],
            global_edge_values,
        )

        r[
            "face_global_percentile"
        ] = percentile_rank(
            r[
                "face_sharpness"
            ],
            face_values,
        )

        r[
            "left_hand_global_percentile"
        ] = percentile_rank(
            r[
                "left_hand_sharpness"
            ],
            left_values,
        )

        r[
            "right_hand_global_percentile"
        ] = percentile_rank(
            r[
                "right_hand_sharpness"
            ],
            right_values,
        )

        r[
            "recovery_q95_threshold"
        ] = recovery_q95

        r[
            "recovery_q99_threshold"
        ] = recovery_q99

    # --------------------------------------------------------
    # Candidate discovery
    #
    # IMPORTANT:
    # These are audit candidates, not deletion rules.
    # --------------------------------------------------------

    global_candidates = []
    face_candidates = []
    hand_candidates = []

    for r in scored:

        # ----------------------
        # GLOBAL BODY BLUR
        #
        # data-driven temporal thresholds:
        # q99 alone, or q95 + sequence low-tail
        # ----------------------

        rec = r[
            "temporal_recovery_ratio"
        ]

        ep = r[
            "seq_edge_percentile"
        ]

        global_candidate = False

        if (
            r[
                "temporal_neighbor_count"
            ]
            >= 2
            and
            np.isfinite(rec)
        ):
            if (
                np.isfinite(
                    recovery_q99
                )
                and
                rec >= recovery_q99
            ):
                global_candidate = True

            elif (
                np.isfinite(
                    recovery_q95
                )
                and
                rec >= recovery_q95
                and
                np.isfinite(ep)
                and
                ep <= 0.10
            ):
                global_candidate = True

        r[
            "global_blur_candidate"
        ] = bool(
            global_candidate
        )

        global_risk = 0.0

        if np.isfinite(rec):
            global_risk += (
                3.0
                *
                max(
                    0.0,
                    rec - 1.0,
                )
            )

        if np.isfinite(ep):
            global_risk += (
                1.0
                -
                ep
            )

        r[
            "global_blur_risk_score"
        ] = float(
            global_risk
        )

        if global_candidate:
            global_candidates.append(
                r
            )

        # ----------------------
        # FACE
        # ----------------------

        face_candidate = False

        if r[
            "face_evaluable"
        ]:

            gp = r[
                "face_global_percentile"
            ]

            sp = r[
                "face_seq_percentile"
            ]

            # Either globally poor, or clearly poor relative
            # to the same sequence.
            if (
                np.isfinite(gp)
                and
                gp <= 0.05
            ):
                face_candidate = True

            elif (
                r[
                    "face_seq_evaluable_count"
                ]
                >= 5
                and
                np.isfinite(sp)
                and
                sp <= 0.05
            ):
                face_candidate = True

        r[
            "face_blur_candidate"
        ] = bool(
            face_candidate
        )

        face_risk = 0.0

        if np.isfinite(
            r[
                "face_global_percentile"
            ]
        ):
            face_risk += (
                1.0
                -
                r[
                    "face_global_percentile"
                ]
            )

        if np.isfinite(
            r[
                "face_seq_percentile"
            ]
        ):
            face_risk += (
                0.75
                *
                (
                    1.0
                    -
                    r[
                        "face_seq_percentile"
                    ]
                )
            )

        if np.isfinite(rec):
            face_risk += (
                0.25
                *
                max(
                    0.0,
                    rec - 1.0,
                )
            )

        r[
            "face_blur_risk_score"
        ] = float(
            face_risk
        )

        if face_candidate:
            face_candidates.append(
                r
            )

        # ----------------------
        # HANDS
        # ----------------------

        side_candidates = []

        # left
        if r[
            "left_hand_evaluable"
        ]:
            gp = r[
                "left_hand_global_percentile"
            ]

            sp = r[
                "left_hand_seq_percentile"
            ]

            if (
                np.isfinite(gp)
                and
                gp <= 0.05
            ):
                side_candidates.append(
                    "LEFT"
                )

            elif (
                r[
                    "left_hand_seq_evaluable_count"
                ]
                >= 5
                and
                np.isfinite(sp)
                and
                sp <= 0.05
            ):
                side_candidates.append(
                    "LEFT"
                )

        # right
        if r[
            "right_hand_evaluable"
        ]:
            gp = r[
                "right_hand_global_percentile"
            ]

            sp = r[
                "right_hand_seq_percentile"
            ]

            if (
                np.isfinite(gp)
                and
                gp <= 0.05
            ):
                side_candidates.append(
                    "RIGHT"
                )

            elif (
                r[
                    "right_hand_seq_evaluable_count"
                ]
                >= 5
                and
                np.isfinite(sp)
                and
                sp <= 0.05
            ):
                side_candidates.append(
                    "RIGHT"
                )

        hand_candidate = bool(
            side_candidates
        )

        if len(
            side_candidates
        ) == 2:
            hand_side = "BOTH"
        elif side_candidates:
            hand_side = (
                side_candidates[0]
            )
        else:
            hand_side = "NONE"

        r[
            "hand_blur_candidate"
        ] = bool(
            hand_candidate
        )

        r[
            "hand_risk_side"
        ] = hand_side

        side_risks = []

        for prefix in [
            "left_hand",
            "right_hand",
        ]:

            gp = r[
                f"{prefix}_global_percentile"
            ]

            sp = r[
                f"{prefix}_seq_percentile"
            ]

            risk = 0.0

            if np.isfinite(gp):
                risk += (
                    1.0 - gp
                )

            if np.isfinite(sp):
                risk += (
                    0.75
                    *
                    (
                        1.0 - sp
                    )
                )

            side_risks.append(
                risk
            )

        r[
            "hand_blur_risk_score"
        ] = float(
            max(
                side_risks
            )
        )

        if hand_candidate:
            hand_candidates.append(
                r
            )

    # --------------------------------------------------------
    # Rank top candidates
    # --------------------------------------------------------

    global_ranked = sorted(
        global_candidates,
        key=lambda r:
            r[
                "global_blur_risk_score"
            ],
        reverse=True,
    )[
        :N_AUDIT
    ]

    face_ranked = sorted(
        face_candidates,
        key=lambda r:
            r[
                "face_blur_risk_score"
            ],
        reverse=True,
    )[
        :N_AUDIT
    ]

    hand_ranked = sorted(
        hand_candidates,
        key=lambda r:
            r[
                "hand_blur_risk_score"
            ],
        reverse=True,
    )[
        :N_AUDIT
    ]

    # --------------------------------------------------------
    # Write candidate JSONLs
    # --------------------------------------------------------

    def write_jsonl(
        path,
        data,
    ):
        with path.open(
            "w",
            encoding="utf-8",
        ) as f:
            for r in data:
                x = dict(
                    r
                )

                x.pop(
                    "_frame_num_int",
                    None,
                )

                f.write(
                    json.dumps(
                        x,
                        ensure_ascii=False,
                    )
                    + "\n"
                )

    write_jsonl(
        GLOBAL_JSONL,
        global_ranked,
    )

    write_jsonl(
        FACE_JSONL,
        face_ranked,
    )

    write_jsonl(
        HAND_JSONL,
        hand_ranked,
    )

    # --------------------------------------------------------
    # Full CSV
    # --------------------------------------------------------

    fields = [
        "split",
        "sequence_id",
        "stem",

        "person_edge_sharpness",
