        "right_hand_seq_percentile",
        "right_hand_native_short_side",
        "right_hand_valid_points",

        "global_blur_candidate",
        "face_blur_candidate",
        "hand_blur_candidate",
        "hand_risk_side",

        "global_blur_risk_score",
        "face_blur_risk_score",
        "hand_blur_risk_score",

        "rgb",
    ]

    with CSV_OUT.open(
        "w",
        encoding="utf-8",
        newline="",
    ) as f:

        writer = csv.DictWriter(
            f,
            fieldnames=fields,
        )

        writer.writeheader()

        for r in scored:
            writer.writerow({
                k: r.get(k)
                for k in fields
            })

    # --------------------------------------------------------
    # Contact sheets
    # --------------------------------------------------------

    global_sheets = save_contact_sheets(
        global_ranked,
        "global_blur",
        lambda r:
            make_global_panel(
                r,
                image_indices,
            ),
    )

    face_sheets = save_contact_sheets(
        face_ranked,
        "face_blur",
        make_face_panel,
    )

    hand_sheets = save_contact_sheets(
        hand_ranked,
        "hand_blur",
        make_hand_panel,
    )

    # --------------------------------------------------------
    # Summary
    # --------------------------------------------------------

    summary = {
        "version":
            "tiktok_v3_visual_quality_v3_audit",

        "input_frames":
            len(scored),

        "important":
            (
                "AUDIT ONLY. No frame, split, source pool "
                "or pair manifest has been modified."
            ),

        "method": {
            "global":
                (
                    "person-region edge-conditioned sharpness "
