#!/usr/bin/env python3
# -*- coding: utf-8 -*-

import csv
import json
from collections import Counter
from pathlib import Path


ROOT = Path("/home/shangguanrz/project/pic-edit")

USABLE_SPLIT = (
    ROOT
    / "datasets/TikTokDataset/TikTok_v3/manifests/"
      "usable_frame_pool_split.jsonl"
)

V3_CSV = (
    ROOT
    / "datasets/TikTokDataset/TikTok_v3/qc/"
      "visual_quality_v3/visual_quality_scores_v3.csv"
)

FINAL_DECISIONS = (
    ROOT
    / "datasets/TikTokDataset/TikTok_v3/qc/"
      "visual_quality_final_v1/visual_quality_decisions.jsonl"
)

OUT_ROOT = (
    ROOT
    / "datasets/TikTokDataset/TikTok_v3/manifests/"
      "strict_visual_v1"
)

OUT_ALL = (
    OUT_ROOT
    / "usable_frame_pool_strict.jsonl"
)

OUT_REJECT = (
    OUT_ROOT
    / "visual_reject_strict.jsonl"
)

SUMMARY = (
    OUT_ROOT
    / "strict_visual_summary.json"
)


def read_jsonl(path):
    return [
        json.loads(x)
        for x in path.read_text(
            encoding="utf-8"
        ).splitlines()
        if x.strip()
    ]


def as_bool(x):
    return str(x).strip().lower() in {
        "true", "1", "yes"
    }


def main():

    OUT_ROOT.mkdir(
        parents=True,
        exist_ok=True,
    )

    usable = read_jsonl(
        USABLE_SPLIT
    )

    decisions = read_jsonl(
        FINAL_DECISIONS
    )

    decision_map = {
        (
            r["sequence_id"],
            r["stem"],
        ): r
        for r in decisions
    }

    hand_map = {}

    with V3_CSV.open(
        "r",
        encoding="utf-8",
        newline="",
    ) as f:

        for r in csv.DictReader(f):
            hand_map[
                (
                    r["sequence_id"],
                    r["stem"],
                )
            ] = as_bool(
                r["hand_blur_candidate"]
            )

    keep = []
    reject = []

    reason_counts = Counter()
    split_keep = Counter()
    split_reject = Counter()

    overlap_counts = Counter()

    for r in usable:

        key = (
            r["sequence_id"],
            r["stem"],
        )

        d = decision_map[key]

        global_blur = bool(
            d["global_hard_blur"]
        )

        face_blur = bool(
            d["face_source_exclude"]
        )

        hand_blur = bool(
            hand_map.get(
                key,
                False,
            )
        )

        reasons = []

        if global_blur:
            reasons.append(
                "GLOBAL_HARD_BLUR"
            )

        if face_blur:
            reasons.append(
                "FACE_BLUR"
            )

        if hand_blur:
            reasons.append(
                "HAND_BLUR"
            )

        if reasons:

            x = dict(r)

            x[
                "visual_filter_status"
            ] = "REJECT"

            x[
                "visual_reject_reasons"
            ] = reasons

            reject.append(x)

            split_reject[
                r["split"]
            ] += 1

            for reason in reasons:
                reason_counts[
                    reason
                ] += 1

            overlap_counts[
                "+".join(
                    sorted(reasons)
                )
            ] += 1

        else:

            x = dict(r)

            x[
                "visual_filter_status"
            ] = "KEEP"

            x[
                "visual_reject_reasons"
            ] = []

            keep.append(x)

            split_keep[
                r["split"]
            ] += 1

    with OUT_ALL.open(
        "w",
        encoding="utf-8",
    ) as f:

        for r in keep:
            f.write(
                json.dumps(
                    r,
                    ensure_ascii=False,
                )
                + "\n"
            )

    with OUT_REJECT.open(
        "w",
        encoding="utf-8",
    ) as f:

        for r in reject:
            f.write(
                json.dumps(
                    r,
                    ensure_ascii=False,
                )
                + "\n"
            )

    for split in [
        "train",
        "val",
        "test",
    ]:

        p = (
            OUT_ROOT
            / f"{split}.jsonl"
        )

        with p.open(
            "w",
            encoding="utf-8",
        ) as f:

            for r in keep:

                if r["split"] != split:
                    continue

                f.write(
                    json.dumps(
                        r,
                        ensure_ascii=False,
                    )
                    + "\n"
                )

    summary = {
        "version":
            "tiktok_v3_strict_visual_v1",

        "input_frames":
            len(usable),

        "keep":
            len(keep),

        "reject_union":
            len(reject),

        "keep_ratio":
            len(keep) / len(usable),

        "raw_reason_counts":
            dict(reason_counts),

        "overlap_patterns":
            dict(overlap_counts),

        "splits": {
            split: {
                "keep":
                    split_keep[split],

                "reject":
                    split_reject[split],
            }
            for split in [
                "train",
                "val",
                "test",
            ]
        },

        "policy": {
            "reject_global_hard_blur":
                True,

            "reject_face_blur":
                True,

            "reject_hand_blur":
                True,

            "delete_original_files":
                False,
        },

        "important":
            (
                "Original RGB, DWPose and geometry files "
                "remain untouched. This is a manifest-only "
                "strict filtering branch."
            ),
    }

    SUMMARY.write_text(
        json.dumps(
            summary,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    print("=" * 78)
    print("TikTok V3 STRICT VISUAL POOL")
    print("=" * 78)

    print(
        json.dumps(
            summary,
            ensure_ascii=False,
            indent=2,
        )
    )


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Paired Face variant comparisons on common visible faces and pose groups."""

from __future__ import annotations

import argparse
import csv
import json
from pathlib import Path

import numpy as np


FACE_ROOT = Path('/home/shangguanrz/nihaochen/qwen21_face')


def arguments():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--per-sample', required=True, type=Path)
    parser.add_argument('--baseline', default='body')
    parser.add_argument('--manual-views', type=Path)
    parser.add_argument('--legacy-audit-csv', type=Path)
    parser.add_argument('--output', type=Path, default=FACE_ROOT / 'face_group_summary.json')
    return parser.parse_args()


def mean(values):
    return float(np.mean(values)) if len(values) else None


def paired(rows, baseline, candidate, metric, eligible):
    matches = []
    for row in rows:
        if not eligible(row):
            continue
        a, b = row['variants'][baseline], row['variants'][candidate]
        if metric.startswith('identity_') and not (a['generated_face_reliable'] and b['generated_face_reliable']):
            continue
        x, y = a.get(metric), b.get(metric)
        if x is not None and y is not None and np.isfinite(x) and np.isfinite(y):
            matches.append((float(x), float(y)))
    if not matches:
        return {'n': 0, 'baseline': None, 'candidate': None, 'delta': None, 'bootstrap_95_ci': None}
    array = np.asarray(matches)
    differences = array[:, 1] - array[:, 0]
    rng = np.random.default_rng(42)
    draws = rng.choice(differences, size=(2000, len(differences)), replace=True).mean(axis=1)
    return {'n': len(matches), 'baseline': mean(array[:, 0]), 'candidate': mean(array[:, 1]),
            'delta': mean(differences), 'bootstrap_95_ci': np.quantile(draws, [.025, .975]).tolist()}


def main():
    args = arguments()
    rows = json.loads(args.per_sample.read_text())
    if args.manual_views:
        audit = json.loads(args.manual_views.read_text())
        if len(audit['views']) != len(rows):
            raise ValueError('manual view count differs from the evaluation count')
        for row, code in zip(rows, audit['views']):
            row['source_view'], row['target_view'] = code[:2]
    legacy_visible, legacy_all_front = set(), set()
    if args.legacy_audit_csv:
        audit_rows = {}
        with args.legacy_audit_csv.open(newline='', encoding='utf-8') as stream:
            for entry in csv.DictReader(stream):
                audit_rows.setdefault(int(entry['pair_idx']), []).append(entry)
        for index, entries in audit_rows.items():
            if len(entries) != 6:
                continue
            if all(entry['face_visible'] == 'True' and entry['view'] in ('F', 'P') and
                   float(entry['min_side_px'] or 0) >= 32 for entry in entries):
                legacy_visible.add(index)
                if all(entry['view'] == 'F' for entry in entries):
                    legacy_all_front.add(index)
    modes = list(rows[0]['variants'])
    if args.baseline not in modes:
        raise ValueError('baseline absent from evaluation')
    groups = {'all': lambda row: True,
              'reliable_visible_face': lambda row: row['strict_reference_usable'],
              'source_face_usable': lambda row: row['source_face_usable']}
    if 'source_face_side_original' in rows[0]:
        groups.update({
            'source_face_below_32px_at_512': lambda row: row['source_face_side_original'] is not None and
                row['source_face_side_original'] < 64,
            'source_face_at_least_32px_at_512': lambda row: row['source_face_side_original'] is not None and
                row['source_face_side_original'] >= 64,
        })
    if 'person_seen_in_face_training' in rows[0]:
        groups.update({
            'person_seen_in_face_training': lambda row: row['person_seen_in_face_training'],
            'person_unseen_in_face_training': lambda row: not row['person_seen_in_face_training'],
            'reliable_face_person_seen': lambda row: row['strict_reference_usable'] and
                row['person_seen_in_face_training'],
            'reliable_face_person_unseen': lambda row: row['strict_reference_usable'] and
                not row['person_seen_in_face_training'],
        })
    if args.manual_views:
        groups.update({
            'same_visible_orientation': lambda row: row['source_view'] == row['target_view'] and row['target_view'] != 'B',
            'changed_visible_orientation': lambda row: row['source_view'] != row['target_view'] and
                row['source_view'] != 'B' and row['target_view'] != 'B',
            'source_or_target_back': lambda row: 'B' in (row['source_view'], row['target_view']),
            'reliable_face_same_orientation': lambda row: row['strict_reference_usable'] and
                row['source_view'] == row['target_view'] and row['target_view'] != 'B',
            'reliable_face_changed_orientation': lambda row: row['strict_reference_usable'] and
                row['source_view'] != row['target_view'] and
                row['source_view'] != 'B' and row['target_view'] != 'B',
        })
    if args.legacy_audit_csv:
        current_faces_at_least_32 = lambda row: all(
            variant['generated_face_reliable'] and variant['generated_face_side'] >= 32
            for variant in row['variants'].values())
        groups.update({
            'prior_audit_visible_32': lambda row: row['pair_idx'] in legacy_visible and
                current_faces_at_least_32(row),
            'prior_audit_all_front_32': lambda row: row['pair_idx'] in legacy_all_front and
                current_faces_at_least_32(row),
        })
    output = {'rows': len(rows), 'baseline': args.baseline, 'groups': {}}
    for group, eligible in groups.items():
        subset = [row for row in rows if eligible(row)]
        output['groups'][group] = {'pairs': len(subset), 'comparisons': {}}
        for candidate in modes:
            if candidate == args.baseline:
                continue
            output['groups'][group]['comparisons'][candidate] = {
                metric: paired(rows, args.baseline, candidate, metric, eligible)
                for metric in ('identity_cosine', 'identity_target_cosine', 'pose_pck_002',
                               'background_mae_source', 'psnr', 'ssim')}
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(output, ensure_ascii=False, indent=2))
    print(json.dumps(output, ensure_ascii=False), flush=True)


if __name__ == '__main__':
    main()

"""CHAMP sample validation and DeepGen pose-residual alignment."""

from dataclasses import dataclass
from pathlib import Path
from typing import Sequence

import numpy as np
from PIL import Image
import torch
import torch.nn.functional as F


CONTROL_CHANNELS = (
    "normal_r",
    "normal_g",
    "normal_b",
    "depth",
    "pose_r",
    "pose_g",
    "pose_b",
    "semantic",
)

CONTROL_PIPELINE_ARGUMENTS = frozenset({
    "block_controlnet_hidden_states",
    "control_scale",
})


@dataclass(frozen=True)
class ChampSample:
  """One aligned CHAMP source/target pair and its structural controls."""

  source: Image.Image
  target: Image.Image
  control: torch.Tensor
  paths: dict[str, Path]
  metadata: dict[str, object]


def _resolve_paths(root: Path) -> dict[str, Path]:
  paths = {
      "source": root / "real_src_frame_0.png",
      "target": root / "real_tgt_frame_60.png",
      "normal": root / "ctrl_normal.png",
      "depth": root / "ctrl_depth.png",
      "pose": root / "ctrl_openpose.png",
      "semantic": root / "ctrl_semantic.png",
  }
  for path in paths.values():
    if not path.is_file():
      raise FileNotFoundError(f"required CHAMP input is missing: {path}")
  return paths


def _resize_rgb(image: Image.Image, resolution: int) -> Image.Image:
  return image.convert("RGB").resize(
      (resolution, resolution), Image.Resampling.LANCZOS
  )


def _load_rgb(path: Path, resolution: int) -> np.ndarray:
  image = Image.open(path).convert("RGB").resize(
      (resolution, resolution), Image.Resampling.BILINEAR
  )
  return np.asarray(image, dtype=np.float32) / 255.0


def _load_gray(path: Path, resolution: int) -> np.ndarray:
  image = Image.open(path).convert("L").resize(
      (resolution, resolution), Image.Resampling.BILINEAR
  )
  return (np.asarray(image, dtype=np.float32) / 255.0)[:, :, None]


def _validate_target_rgb(target: Image.Image, path: Path) -> None:
  array = np.asarray(target.convert("RGB"), dtype=np.uint8)
  channel_equal = np.array_equal(array[:, :, 0], array[:, :, 1]) and np.array_equal(
      array[:, :, 1], array[:, :, 2]
  )
  luminance = np.rint(array.astype(np.float32).mean(axis=2)).astype(np.uint8)
  unique_luminance = np.unique(luminance)
  near_binary = np.mean((luminance <= 2) | (luminance >= 253)) > 0.95
  if channel_equal and (len(unique_luminance) < 32 or near_binary):
    raise ValueError(f"target RGB looks like a mask, not a video frame: {path}")


def load_champ_sample(root: Path | str, resolution: int = 512) -> ChampSample:
  """Load one aligned CHAMP pair using the fixed eight-channel contract."""
  if resolution <= 0 or resolution % 16 != 0:
    raise ValueError(f"resolution must be a positive multiple of 16, got {resolution}")

  root_path = Path(root)
  paths = _resolve_paths(root_path)
  source_raw = Image.open(paths["source"]).convert("RGB")
  target_raw = Image.open(paths["target"]).convert("RGB")
  _validate_target_rgb(target_raw, paths["target"])

  normal = _load_rgb(paths["normal"], resolution)
  depth = _load_gray(paths["depth"], resolution)
  pose = _load_rgb(paths["pose"], resolution)
  semantic = _load_gray(paths["semantic"], resolution)
  stacked = np.concatenate([normal, depth, pose, semantic], axis=-1)
  if stacked.shape != (resolution, resolution, 8):
    raise ValueError(
        "CHAMP controls must form [H,W,8], "
        f"got {stacked.shape} from {root_path}"
    )
  if not np.isfinite(stacked).all():
    raise ValueError(f"CHAMP controls contain NaN or Inf: {root_path}")

  control = torch.from_numpy(stacked.copy()).permute(2, 0, 1).unsqueeze(0)
  return ChampSample(
      source=_resize_rgb(source_raw, resolution),
      target=_resize_rgb(target_raw, resolution),
      control=control,
      paths=paths,
      metadata={
          "root": str(root_path),
          "resolution": resolution,
          "control_channels": CONTROL_CHANNELS,
          "source_size": source_raw.size,
          "target_size": target_raw.size,
      },
  )


def align_control_residuals(
    residuals: Sequence[torch.Tensor],
    target_tokens: int,
    reference_tokens: int,
    batch_size: int,
) -> list[torch.Tensor]:
  """Pad reference-token positions with zero without changing batch or scale."""
  if target_tokens <= 0 or reference_tokens < 0 or batch_size <= 0:
    raise ValueError("target_tokens and batch_size must be positive")
  if not residuals:
    raise ValueError("at least one control residual layer is required")

  aligned = []
  for index, residual in enumerate(residuals):
    if residual.ndim != 3 or residual.shape[1] != target_tokens:
      raise ValueError(
          f"control layer {index}: expected [B,{target_tokens},D], "
          f"got {tuple(residual.shape)}"
      )
    if residual.shape[0] != batch_size:
      raise ValueError(
          f"control layer {index}: expected batch {batch_size}, "
          f"got {residual.shape[0]}"
      )
    if not torch.isfinite(residual).all():
      raise ValueError(f"control layer {index} contains NaN or Inf")
    aligned.append(F.pad(residual, (0, 0, 0, reference_tokens)))
  return aligned


def image_diagnostics(image: Image.Image) -> dict[str, float | bool]:
  """Return cheap numerical guards against collapsed generated images."""
  array = np.asarray(image.convert("RGB"), dtype=np.float32)
  mean = float(array.mean())
  std = float(array.std())
  near_white_ratio = float(np.mean(np.all(array >= 250.0, axis=2)))
  near_black_ratio = float(np.mean(np.all(array <= 5.0, axis=2)))
  finite = bool(np.isfinite(array).all())
  valid = finite and std >= 5.0 and near_white_ratio <= 0.95 and near_black_ratio <= 0.95
  return {
      "mean": mean,
      "std": std,
      "near_white_ratio": near_white_ratio,
      "near_black_ratio": near_black_ratio,
      "finite": finite,
      "valid": valid,
  }


def call_deepgen_without_control(pipeline, **kwargs):
  """Call DeepGen while making control injection structurally impossible."""
  forbidden = sorted(CONTROL_PIPELINE_ARGUMENTS.intersection(kwargs))
  if forbidden:
    raise ValueError(
        "pure DeepGen ablation forbids control arguments: " + ", ".join(forbidden)
    )
  return pipeline(**kwargs)


def image_error_metrics(
    image: Image.Image,
    target: Image.Image,
) -> dict[str, float]:
  """Return full-image MAE, MSE, and PSNR against an aligned RGB target."""
  actual = np.asarray(image.convert("RGB"), dtype=np.float32)
  expected = np.asarray(target.convert("RGB"), dtype=np.float32)
  if actual.shape != expected.shape:
    raise ValueError(
        f"image and target shapes must match, got {actual.shape} and {expected.shape}"
    )
  difference = actual - expected
  mae = float(np.mean(np.abs(difference)))
  mse = float(np.mean(np.square(difference)))
  psnr = (
      float("inf")
      if mse == 0.0
      else float(-10.0 * np.log10(mse / (255.0**2)))
  )
  return {"mae": mae, "mse": mse, "psnr": psnr}

"""Target-RGB-free generation boundary for Hi4D Qwen21 dual editing."""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Mapping

import torch
from PIL import Image

from src.data.hi4d_qwen21_dataset import collate_hi4d
from .body_adapter import Qwen21ControlContext
from .runtime import Qwen21IPERCache, dataset_image_to_pil


# These fields are derived from the source or supplied target geometry. In
# particular, tgt_image, target_rgb and gt_mask_A/B never cross this boundary.
CONTROL_SAMPLE_KEYS = (
    "normal_a", "normal_b", "pose_heatmap_a", "pose_heatmap_b",
    "part_onehot_a", "part_onehot_b", "smplx_global_a", "smplx_global_b",
    "human_mask_a", "human_mask_b", "depth_a", "depth_b",
    "relative_geometry", "contact_raster", "task_id", "person_b_valid",
    "contact_src_person", "contact_src_part", "contact_dst_person",
    "contact_dst_part", "contact_contact_type", "contact_distance",
    "contact_valid_mask", "source_mask_a", "source_mask_b",
)
CONTROL_BATCH_KEYS = (set(CONTROL_SAMPLE_KEYS) - {
    "contact_src_person", "contact_src_part", "contact_dst_person",
    "contact_dst_part", "contact_contact_type", "contact_distance",
    "contact_valid_mask",
}) | {"contact_relations"}


@dataclass(frozen=True)
class NativeGenerationInput:
    source_image: Image.Image
    prompt: str


@dataclass(frozen=True)
class DualGenerationInput(NativeGenerationInput):
    controls: Mapping[str, Any]

    def __post_init__(self) -> None:
        if set(self.controls) != CONTROL_BATCH_KEYS:
            missing = CONTROL_BATCH_KEYS - set(self.controls)
            extra = set(self.controls) - CONTROL_BATCH_KEYS
            raise ValueError(f"dual generation control keys invalid: missing={missing}, extra={extra}")


def generation_inputs_from_sample(
    sample: Mapping[str, Any], native_prompt: str, adapter_prompt: str,
) -> tuple[NativeGenerationInput, DualGenerationInput]:
    """Whitelist source and control tensors from a dataset row that may contain GT."""
    if not native_prompt.strip() or not adapter_prompt.strip():
        raise ValueError("both generation prompts must be nonempty")
    source = dataset_image_to_pil(sample["src_image"])
    selected = {name: sample[name] for name in CONTROL_SAMPLE_KEYS}
    controls = collate_hi4d([selected])
    return (NativeGenerationInput(source, native_prompt),
            DualGenerationInput(source, adapter_prompt, controls))


def _pipeline_kwargs(source_image: Image.Image, prompt: str, steps: int, seed: int) -> dict:
    if steps <= 0:
        raise ValueError("sampling steps must be positive")
    return dict(prompt=prompt, image=source_image, width=512, height=512,
                output_resolution=512, num_inference_steps=steps,
                true_cfg_scale=1.0, use_kv_cache=True,
                generator=torch.Generator(device="cuda").manual_seed(seed))


@torch.inference_mode()
def generate_native(pipe, inputs: NativeGenerationInput, *, steps: int, seed: int) -> Image.Image:
    """The original model receives only the source photo and detailed text."""
    if type(inputs) is not NativeGenerationInput:
        raise TypeError("native generation requires NativeGenerationInput without controls")
    with torch.autocast("cuda", dtype=torch.bfloat16):
        return pipe(**_pipeline_kwargs(inputs.source_image, inputs.prompt, steps, seed)).images[0].convert("RGB")


@torch.inference_mode()
def generate_controlled(pipe, adapter, cache: Qwen21IPERCache,
                        inputs: DualGenerationInput, *, mode: str, steps: int, seed: int) -> Image.Image:
    """The adapter receives source photo, text and supplied target geometry only."""
    if mode not in ("geometry", "full"):
        raise ValueError("controlled generation mode must be geometry or full")
    reference = cache.source(pipe, inputs.source_image, prompt=inputs.prompt)["reference_latent"].to("cuda")
    state = adapter.encode_dual(inputs.controls, reference,
                                include_contact=(mode == "full"))
    if mode == "geometry":
        state = state.geometry_only()
    with Qwen21ControlContext(pipe.transformer, adapter, state) as control:
        with torch.autocast("cuda", dtype=torch.bfloat16):
            image = pipe(**_pipeline_kwargs(inputs.source_image, inputs.prompt, steps, seed)).images[0].convert("RGB")
    if any(count == 0 for count in control.call_counts.values()):
        raise RuntimeError("a Qwen control layer was not used during inference")
    return image

"""Pinned Qwen-Image-2.1 image/latent contract used by iPER training and evaluation."""

from __future__ import annotations

import hashlib
import os
from collections.abc import Sequence
from pathlib import Path

import torch
import torch.nn.functional as F
from PIL import Image
from torchvision.transforms.functional import to_pil_image


MODEL_REVISION = "790c92633540aa0cb11d9abf19eb46d861714758"
PROMPT = "Change the person pose to match the target pose. Preserve identity, clothing, and background."
RESOLUTION = 512


def dataset_image_to_pil(image: torch.Tensor) -> Image.Image:
    """Convert the dataset's normalized RGB tensor into an opaque RGB image."""
    return to_pil_image(((image.detach().float().cpu() + 1) * 0.5).clamp(0, 1))


class Qwen21IPERCache:
    def __init__(self, root: str | Path, *, prompt: str = PROMPT, resolution: int = RESOLUTION) -> None:
        if resolution not in (512, 1024):
            raise ValueError('resolution must be 512 or 1024')
        self.root = Path(root)
        self.root.mkdir(parents=True, exist_ok=True)
        self.prompt = prompt
        self.resolution = resolution

    def _path(self, image: Image.Image, kind: str, *, prompt: str | None = None) -> Path:
        resolved_prompt = self.prompt if prompt is None or kind == "target" else prompt
        digest = hashlib.sha256()
        digest.update((MODEL_REVISION + resolved_prompt + kind + str(self.resolution)).encode())
        digest.update(image.convert("RGB").tobytes())
        return self.root / f"{kind}_{digest.hexdigest()[:24]}.pt"

    @staticmethod
    def _store(path: Path, value: object) -> None:
        temporary = path.with_name(f"{path.name}.{os.getpid()}.tmp")
        torch.save(value, temporary)
        temporary.replace(path)

    def _vae_input(self, pipe, image: Image.Image, device: torch.device) -> torch.Tensor:
        rgba = image.convert("RGBA")
        return pipe.image_processor.preprocess(
            rgba, width=self.resolution, height=self.resolution
        ).unsqueeze(2).to(device=device, dtype=pipe.vae.dtype)

    def source(self, pipe, image: Image.Image, *, prompt: str | None = None) -> dict[str, torch.Tensor]:
        resolved_prompt = self.prompt if prompt is None else prompt
        path = self._path(image, "source", prompt=resolved_prompt)
        if path.exists():
            return torch.load(path, map_location="cpu", weights_only=True)
        device = next(pipe.text_encoder.parameters()).device
        if device.type == "cpu":
            raise RuntimeError(f"missing source cache {path.name}; text encoder must be on GPU for precompute")
        with torch.inference_mode():
            rgba = image.convert("RGBA")
            vlm_image = pipe.image_processor.resize(rgba, width=self.resolution, height=self.resolution)
            prompt_embeds, prompt_mask, image_mask = pipe.encode_prompt(
                resolved_prompt, image=[vlm_image], device=device
            )
            vae_image = self._vae_input(pipe, rgba, device)
            latent = pipe._encode_vae_image(vae_image, torch.Generator(device=device).manual_seed(0))
            latent = latent.flatten(3).squeeze(2).transpose(1, 2)
            if prompt_mask is None:
                prompt_mask = torch.ones(prompt_embeds.shape[:2], device=device, dtype=torch.bool)
            entry = {
                "prompt_embeds": prompt_embeds.cpu().contiguous(),
                "prompt_mask": prompt_mask.cpu().bool().contiguous(),
                "image_mask": image_mask.cpu().bool().contiguous(),
                "reference_latent": latent.cpu().contiguous(),
            }
        self._store(path, entry)
        return entry

    def target(self, pipe, image: Image.Image) -> torch.Tensor:
        path = self._path(image, "target")
        if path.exists():
            return torch.load(path, map_location="cpu", weights_only=True)
        device = next(pipe.vae.parameters()).device
        if device.type == "cpu":
            raise RuntimeError(f"missing target cache {path.name}; VAE must be on GPU for precompute")
        with torch.inference_mode():
            latent = pipe._encode_vae_image(
                self._vae_input(pipe, image, device), torch.Generator(device=device).manual_seed(0)
            )
            latent = latent.flatten(3).squeeze(2).transpose(1, 2).cpu().contiguous()
        self._store(path, latent)
        return latent

    def pair(
        self, pipe, batch: dict, device: torch.device, *, prompts: Sequence[str] | None = None
    ) -> dict[str, torch.Tensor]:
        batch_size = batch["src_image"].shape[0]
        if prompts is None:
            conditions = [self.source(pipe, dataset_image_to_pil(batch["src_image"][index])) for index in range(batch_size)]
        else:
            if len(prompts) != batch_size:
                raise ValueError(f"prompts length {len(prompts)} does not match batch size {batch_size}")
            conditions = [
                self.source(pipe, dataset_image_to_pil(batch["src_image"][index]), prompt=prompts[index])
                for index in range(batch_size)
            ]
        targets = [self.target(pipe, dataset_image_to_pil(batch["tgt_image"][index])) for index in range(batch_size)]
        target_latent = torch.cat(targets, dim=0)
        tokens = target_latent.shape[1]
        if tokens != (self.resolution // 16) ** 2 or tokens % 4:
            raise ValueError(f"unexpected Qwen21 target token count: {tokens}")
        max_prompt = max(condition["prompt_embeds"].shape[1] for condition in conditions)
        prompt_embeds = torch.cat([
            F.pad(condition["prompt_embeds"], (0, 0, 0, max_prompt - condition["prompt_embeds"].shape[1]))
            for condition in conditions
        ], dim=0)
        prompt_mask = torch.cat([
            F.pad(condition["prompt_mask"], (0, max_prompt - condition["prompt_mask"].shape[1]), value=False)
            for condition in conditions
        ], dim=0)
        image_mask = torch.cat([
            torch.cat((
                F.pad(condition["image_mask"], (0, max_prompt - condition["image_mask"].shape[1]), value=False),
                torch.ones(1, tokens // 4, dtype=torch.bool),
            ), dim=1) for condition in conditions
        ], dim=0)
        return {
            "source_latent": torch.cat([condition["reference_latent"] for condition in conditions], dim=0).to(device),
            "target_latent": target_latent.to(device),
            "prompt_embeds": prompt_embeds.to(device),
            "prompt_mask": prompt_mask.to(device),
            "img_mask": image_mask.to(device),
            "resolution": self.resolution,
        }


def transformer_inputs(pair: dict[str, torch.Tensor], noisy_target: torch.Tensor, sigma: torch.Tensor):
    grid = pair['resolution'] // 16
    if noisy_target.shape[1] != grid * grid:
        raise ValueError('target latent token count does not match resolution')
    return {
        "hidden_states": torch.cat((pair["source_latent"], noisy_target), dim=1),
        "timestep": sigma,
        "encoder_hidden_states": pair["prompt_embeds"],
        "encoder_hidden_states_mask": pair["prompt_mask"],
        "img_shapes": [[(1, grid, grid)] * 2 for _ in range(noisy_target.shape[0])],
        "img_mask": pair["img_mask"],
        "return_dict": False,
    }

from __future__ import annotations

from collections.abc import Mapping
from typing import Any

import torch
import torch.nn as nn


ARCHITECTURE_VERSION = "v6.6"
DETAIL_SCHEMA_VERSION = "1"
PREPROCESSING_SCHEMA_VERSION = "1"
FACE_SCHEMA_VERSION = "1"
BRANCH_NAMES = ["geometry", "interaction", "hand", "face"]
V66_BRANCH_NAMES = ["geometry", "interaction", "legacy_hand", "face", "hand"]
HAND_SCHEMA_VERSION = "1"
V64_BRANCH_NAMES = ["geometry", "interaction", "detail"]

DETAIL_ONLY_PREFIXES = (
    "detail_preparer.",
    "control_interface.control_core.detail_branch.",
    "control_interface.strength_controller.detail_log_group_scale",
)

FACE_ONLY_PREFIXES = (
    "face_preparer.",
    "control_interface.face_adapter.",
    "control_interface.strength_controller.face_",
)
HAND_ONLY_PREFIXES = (
    "hand_preparer.",
    "control_interface.hand_adapter.",
    "control_interface.strength_controller.hand_log_group_scale",
    "control_interface.strength_controller.hand_group_prior",
)


def _has_prefix(key: str, prefixes: tuple[str, ...]) -> bool:
    return any(key.startswith(prefix) for prefix in prefixes)


def _adapter_state(checkpoint: Mapping[str, Any]) -> Mapping[str, torch.Tensor]:
    state = checkpoint.get("adapter_state_dict", checkpoint)
    if not isinstance(state, Mapping):
        raise TypeError("checkpoint adapter_state_dict must be a mapping")
    return state


def _preflight_state(
    model: nn.Module,
    state: Mapping[str, Any],
    expected_keys: set[str],
) -> None:
    provided_keys = set(state)
    unexpected = sorted(provided_keys - expected_keys)
    missing = sorted(expected_keys - provided_keys)
    if unexpected:
        raise RuntimeError(f"unexpected checkpoint keys: {unexpected}")
    if missing:
        raise RuntimeError(f"checkpoint is missing keys: {missing}")
    expected_state = model.state_dict()
    for key in sorted(expected_keys):
        value = state[key]
        expected = expected_state[key]
        if not torch.is_tensor(value):
            raise RuntimeError(f"checkpoint value for {key!r} must be a tensor")
        if value.shape != expected.shape:
            raise RuntimeError(
                f"checkpoint tensor {key!r} has shape {tuple(value.shape)}; "
                f"expected {tuple(expected.shape)}"
            )
        if value.dtype != expected.dtype:
            raise RuntimeError(
                f"checkpoint tensor {key!r} has dtype {value.dtype}; "
                f"expected {expected.dtype}"
            )
        if value.layout != torch.strided or value.layout != expected.layout:
            raise RuntimeError(
                f"checkpoint tensor {key!r} has layout {value.layout}; "
                f"expected strided layout {expected.layout}"
            )


def _transactional_load(
    model: nn.Module,
    state: Mapping[str, torch.Tensor],
    *,
    strict: bool,
    after_load=None,
):
    snapshot = {
        key: value.detach().clone() for key, value in model.state_dict().items()
    }
    try:
        result = model.load_state_dict(state, strict=strict)
        if after_load is not None:
            after_load()
        return result
    except Exception:
        current = model.state_dict()
        with torch.no_grad():
            for key, value in snapshot.items():
                current[key].copy_(value)
        raise


def load_v63_checkpoint(
    model: nn.Module, checkpoint: Mapping[str, Any]
) -> torch.nn.modules.module._IncompatibleKeys:
    """Load V6.3 adapter weights while allowing only newly introduced detail keys."""

    if "optimizer_state_dict" in checkpoint:
        raise RuntimeError(
            "V6.3 optimizer state is incompatible with V6.4 and must not be restored"
        )
    metadata = checkpoint.get("metadata")
    if isinstance(metadata, Mapping) and metadata.get("architecture_version") in {
        "v6.4",
        "v6.5",
        "v6.6",
    }:
        version = metadata.get("architecture_version")
        raise RuntimeError(f"V6.3 loader rejects {version.upper()} metadata")
    state = _adapter_state(checkpoint)
    detail_keys = sorted(
        key
        for key in state
        if _has_prefix(key, DETAIL_ONLY_PREFIXES)
    )
    if detail_keys:
        raise RuntimeError(f"V6.3 checkpoint contains detail-only keys: {detail_keys}")
    face_keys = sorted(
        key for key in state if _has_prefix(key, FACE_ONLY_PREFIXES)
    )
    if face_keys:
        raise RuntimeError(f"V6.3 checkpoint contains face-only keys: {face_keys}")
    hand_keys = sorted(key for key in state if _has_prefix(key, HAND_ONLY_PREFIXES))
    if hand_keys:
        raise RuntimeError(f"V6.3 checkpoint contains hand-only keys: {hand_keys}")
    model_keys = set(model.state_dict())
    expected_keys = {
        key
        for key in model_keys
        if not _has_prefix(key, DETAIL_ONLY_PREFIXES + FACE_ONLY_PREFIXES + HAND_ONLY_PREFIXES)
    }
    _preflight_state(model, state, expected_keys)
    detail_branch = model.get_submodule("control_interface.control_core.detail_branch")

    def rezero_new_heads() -> None:
        with torch.no_grad():
            for head in detail_branch.zero_heads:
                nn.init.zeros_(head.weight)
                if head.bias is not None:
                    nn.init.zeros_(head.bias)
        _rezero_face_heads(model)
        _rezero_hand_heads(model)

    result = _transactional_load(
        model,
        state,
        strict=False,
        after_load=rezero_new_heads,
    )
    return result


def v64_checkpoint_metadata() -> dict[str, object]:
    return {
        "architecture_version": "v6.4",
        "branch_names": list(V64_BRANCH_NAMES),
        "detail_schema_version": DETAIL_SCHEMA_VERSION,
        "preprocessing_schema_version": PREPROCESSING_SCHEMA_VERSION,
    }


def build_v64_checkpoint(
    model: nn.Module, **extra: Any
) -> dict[str, Any]:
    reserved = {"metadata", "adapter_state_dict"} & set(extra)
    if reserved:
        raise ValueError(f"checkpoint extra keys are reserved: {sorted(reserved)}")
    checkpoint = {
        "adapter_state_dict": {
            key: value.detach().clone()
            for key, value in model.state_dict().items()
            if not _has_prefix(key, FACE_ONLY_PREFIXES + HAND_ONLY_PREFIXES)
        },
        "metadata": v64_checkpoint_metadata(),
    }
    checkpoint.update(extra)
    return checkpoint


def _rezero_face_heads(model: nn.Module) -> None:
    interface = getattr(model, "control_interface", None)
    face_adapter = getattr(interface, "face_adapter", None)
    if face_adapter is None:
        return
    with torch.no_grad():
        for head in face_adapter.zero_heads:
            nn.init.zeros_(head.weight)
            if head.bias is not None:
                nn.init.zeros_(head.bias)


def _rezero_hand_heads(model: nn.Module) -> None:
    interface = getattr(model, "control_interface", None)
    adapter = getattr(interface, "hand_adapter", None)
    if adapter is not None:
        with torch.no_grad():
            for head in adapter.zero_heads:
                nn.init.zeros_(head.weight)
                if head.bias is not None:
                    nn.init.zeros_(head.bias)


def load_v64_checkpoint(
    model: nn.Module, checkpoint: Mapping[str, Any]
) -> torch.nn.modules.module._IncompatibleKeys:
    if "optimizer_state_dict" in checkpoint:
        raise RuntimeError(
            "V6.4 optimizer state is incompatible with V6.5 and must not be restored"
        )
    metadata = checkpoint.get("metadata")
    if not isinstance(metadata, Mapping):
        raise RuntimeError("V6.4 checkpoint metadata is missing")
    expected = v64_checkpoint_metadata()
    for key, value in expected.items():
        if metadata.get(key) != value:
            raise RuntimeError(f"invalid V6.4 checkpoint metadata field {key!r}")
    state = _adapter_state(checkpoint)
    expected_keys = {
        key for key in model.state_dict() if not _has_prefix(key, FACE_ONLY_PREFIXES + HAND_ONLY_PREFIXES)
    }
    _preflight_state(model, state, expected_keys)
    return _transactional_load(
        model,
        state,
        strict=expected_keys == set(model.state_dict()),
        after_load=lambda: (_rezero_face_heads(model), _rezero_hand_heads(model)),
    )


def v65_checkpoint_metadata(
    *, feature_cache_fingerprint: str | None = None
) -> dict[str, object]:
    return {
        "architecture_version": "v6.5",
        "branch_names": list(BRANCH_NAMES),
        "detail_schema_version": DETAIL_SCHEMA_VERSION,
        "face_schema_version": FACE_SCHEMA_VERSION,
        "preprocessing_schema_version": PREPROCESSING_SCHEMA_VERSION,
        "feature_cache_fingerprint": feature_cache_fingerprint,
    }


def build_v65_checkpoint(
    model: nn.Module,
    *,
    feature_cache_fingerprint: str | None = None,
    **extra: Any,
) -> dict[str, Any]:
    reserved = {"metadata", "adapter_state_dict"} & set(extra)
    if reserved:
        raise ValueError(f"checkpoint extra keys are reserved: {sorted(reserved)}")
    checkpoint = {
        "adapter_state_dict": {
            key: value.detach().clone() for key, value in model.state_dict().items()
            if not _has_prefix(key, HAND_ONLY_PREFIXES)
        },
        "metadata": v65_checkpoint_metadata(
            feature_cache_fingerprint=feature_cache_fingerprint
        ),
    }
    checkpoint.update(extra)
    return checkpoint


def load_v65_checkpoint(model: nn.Module, checkpoint: Mapping[str, Any]) -> None:
    metadata = checkpoint.get("metadata")
    if not isinstance(metadata, Mapping):
        raise RuntimeError("V6.5 checkpoint metadata is missing")
    expected = v65_checkpoint_metadata(
        feature_cache_fingerprint=metadata.get("feature_cache_fingerprint")
    )
    for key, value in expected.items():
        if metadata.get(key) != value:
            raise RuntimeError(f"invalid V6.5 checkpoint metadata field {key!r}")
    state = _adapter_state(checkpoint)
    expected_keys = {key for key in model.state_dict() if not _has_prefix(key, HAND_ONLY_PREFIXES)}
    _preflight_state(model, state, expected_keys)
    _transactional_load(model, state, strict=expected_keys == set(model.state_dict()), after_load=lambda: _rezero_hand_heads(model))


def v66_checkpoint_metadata(*, feature_cache_fingerprint: str | None = None, hand_cache_fingerprint: str | None = None) -> dict[str, object]:
    return {
        "architecture_version": ARCHITECTURE_VERSION,
        "branch_names": list(V66_BRANCH_NAMES),
        "detail_schema_version": DETAIL_SCHEMA_VERSION,
        "face_schema_version": FACE_SCHEMA_VERSION,
        "hand_schema_version": HAND_SCHEMA_VERSION,
        "preprocessing_schema_version": PREPROCESSING_SCHEMA_VERSION,
        "feature_cache_fingerprint": feature_cache_fingerprint,
        "hand_cache_fingerprint": hand_cache_fingerprint,
    }


def build_v66_checkpoint(model: nn.Module, *, feature_cache_fingerprint: str | None = None, hand_cache_fingerprint: str | None = None, **extra: Any) -> dict[str, Any]:
    reserved = {"metadata", "adapter_state_dict"} & set(extra)
    if reserved:
        raise ValueError(f"checkpoint extra keys are reserved: {sorted(reserved)}")
    result = {"adapter_state_dict": {key: value.detach().clone() for key, value in model.state_dict().items()},
              "metadata": v66_checkpoint_metadata(feature_cache_fingerprint=feature_cache_fingerprint, hand_cache_fingerprint=hand_cache_fingerprint)}
    result.update(extra)
    return result


def load_v66_checkpoint(model: nn.Module, checkpoint: Mapping[str, Any]) -> None:
    metadata = checkpoint.get("metadata")
    if not isinstance(metadata, Mapping):
        raise RuntimeError("V6.6 checkpoint metadata is missing")
    expected = v66_checkpoint_metadata(feature_cache_fingerprint=metadata.get("feature_cache_fingerprint"), hand_cache_fingerprint=metadata.get("hand_cache_fingerprint"))
    for key, value in expected.items():
        if metadata.get(key) != value:
            raise RuntimeError(f"invalid V6.6 checkpoint metadata field {key!r}")
    state = _adapter_state(checkpoint)
    _preflight_state(model, state, set(model.state_dict()))
    _transactional_load(model, state, strict=True)


def freeze_for_hand_training(model: nn.Module, *, warmup: bool = False) -> tuple[nn.Parameter, ...]:
    """V6.6-only optimizer selection; warmup trains heads and group gate."""
    for parameter in model.parameters():
        parameter.requires_grad_(False)
    prefixes = ("control_interface.hand_adapter.zero_heads.", "control_interface.strength_controller.hand_log_group_scale") if warmup else HAND_ONLY_PREFIXES
    selected = []
    for name, parameter in model.named_parameters():
        if _has_prefix(name, prefixes):
            parameter.requires_grad_(True)
            selected.append(parameter)
    return tuple(selected)


def freeze_for_detail_training(model: nn.Module) -> tuple[nn.Parameter, ...]:
    """Freeze V6.3 and expose only V6.4 detail modules and detail group gates."""

    for parameter in model.parameters():
        parameter.requires_grad_(False)
    trainable_prefixes = (
        "detail_preparer.",
        "control_interface.control_core.detail_branch.",
        "control_interface.strength_controller.detail_log_group_scale",
    )
    selected = []
    for name, parameter in model.named_parameters():
        if any(name.startswith(prefix) for prefix in trainable_prefixes):
            parameter.requires_grad_(True)
            selected.append(parameter)
    return tuple(selected)


def freeze_for_face_training(model: nn.Module) -> tuple[nn.Parameter, ...]:
    """Freeze every old branch and expose only the independent V6.5 face path."""

    for parameter in model.parameters():
        parameter.requires_grad_(False)
    selected = []
    for name, parameter in model.named_parameters():
        if _has_prefix(name, FACE_ONLY_PREFIXES):
            parameter.requires_grad_(True)
            selected.append(parameter)
    return tuple(selected)


