@dataclass
class FaceHandDetailCondition:
    """Normalized two-person face/hand geometry and region bindings."""

    face_keypoints: torch.Tensor
    hand_keypoints: torch.Tensor
    smplx_detail: torch.Tensor
    source_boxes: torch.Tensor
    target_boxes: torch.Tensor
    region_valid: torch.Tensor
    source_indices: torch.Tensor

    @property
    def batch_size(self) -> int:
        return int(self.face_keypoints.shape[0])

    @property
    def person_valid(self) -> torch.Tensor:
        return self.region_valid.any(dim=-1)

    @property
    def device(self) -> torch.device:
        return self.face_keypoints.device

    def validate(self) -> "FaceHandDetailCondition":
        batch_size = self.batch_size
        expected_shapes = {
            "face_keypoints": (batch_size, 2, 68, 3),
            "hand_keypoints": (batch_size, 2, 2, 21, 3),
            "smplx_detail": (batch_size, 2, 103),
            "source_boxes": (batch_size, 2, 3, 4),
            "target_boxes": (batch_size, 2, 3, 4),
        }
        floating = []
        for name, expected in expected_shapes.items():
            value = getattr(self, name)
            if tuple(value.shape) != expected:
                raise ValueError(f"{name} must have shape {expected}")
            if not value.is_floating_point():
                raise ValueError(f"{name} must use a floating dtype")
            floating.append(value)
        if any(value.dtype != floating[0].dtype for value in floating[1:]):
            raise ValueError("all floating tensors must use the same dtype")
        if any(value.device != floating[0].device for value in floating[1:]):
            raise ValueError("all condition tensors must be on the same device")
        if tuple(self.region_valid.shape) != (batch_size, 2, 3) or self.region_valid.dtype != torch.bool:
            raise ValueError("region_valid must have shape [B,2,3] and dtype bool")
        if tuple(self.source_indices.shape) != (batch_size, 2) or self.source_indices.dtype != torch.long:
            raise ValueError("source_indices must have shape [B,2] and dtype int64")
        if self.region_valid.device != self.device or self.source_indices.device != self.device:
            raise ValueError("all condition tensors must be on the same device")
        if any(not torch.isfinite(value).all() for value in floating):
            raise ValueError("detail condition tensors must contain only finite values")

        for name in ("face_keypoints", "hand_keypoints"):
            keypoints = getattr(self, name)
            if torch.any((keypoints < 0) | (keypoints > 1)):
                raise ValueError(f"{name} must contain normalized xy/confidence values in [0,1]")

        for name in ("source_boxes", "target_boxes"):
            boxes = getattr(self, name)
            if torch.any((boxes < 0) | (boxes > 1)):
                raise ValueError(f"{name} must contain normalized boxes in [0,1]")
            ordered = (boxes[..., 0] <= boxes[..., 2]) & (
                boxes[..., 1] <= boxes[..., 3]
            )
            positive = (boxes[..., 0] < boxes[..., 2]) & (
                boxes[..., 1] < boxes[..., 3]
            )
            if not ordered.all() or not positive[self.region_valid].all():
                raise ValueError(f"{name} must use valid normalized xyxy boxes")

        valid_indices = self.source_indices[self.person_valid]
        if valid_indices.numel() and torch.any(
            (valid_indices < 0) | (valid_indices > 15)
        ):
            raise ValueError("valid source_indices must be in [0, 15]")
        both_valid = self.person_valid.all(dim=1)
        if torch.any(
            both_valid & (self.source_indices[:, 0] == self.source_indices[:, 1])
        ):
            raise ValueError("valid persons must use unique source_indices within each sample")
        return self

    def index_select(self, indices: torch.Tensor) -> "FaceHandDetailCondition":
        return _selected(self, indices)

    def to(self, *args, **kwargs) -> "FaceHandDetailCondition":
        return _moved(self, *args, **kwargs)


@dataclass
class DetailReferenceBatch:
    """One to three local appearance references per person and detail region."""

    images: torch.Tensor
    reference_valid: torch.Tensor

    @property
    def batch_size(self) -> int:
        return int(self.images.shape[0])

    @property
    def reference_count(self) -> int:
        return int(self.images.shape[3])

    @property
    def device(self) -> torch.device:
        return self.images.device

    def validate(self) -> "DetailReferenceBatch":
        if self.images.ndim != 7:
            raise ValueError("images must have shape [B,2,3,R,3,224,224]")
        batch_size, people, regions, reference_count, channels, height, width = self.images.shape
        if (people, regions, channels, height, width) != (2, 3, 3, 224, 224):
            raise ValueError("images must have shape [B,2,3,R,3,224,224]")
        if not 1 <= reference_count <= 3:
            raise ValueError("detail reference count must be between 1 and 3")
        expected = (batch_size, 2, 3, reference_count)
        if tuple(self.reference_valid.shape) != expected or self.reference_valid.dtype != torch.bool:
            raise ValueError(f"reference_valid must have shape {expected} and dtype bool")
        if not self.images.is_floating_point():
            raise ValueError("reference images must use a floating dtype")
        if self.reference_valid.device != self.images.device:
            raise ValueError("reference images and reference_valid must be on the same device")
        if not torch.isfinite(self.images).all():
            raise ValueError("reference images must contain only finite values")
        return self

    def index_select(self, indices: torch.Tensor) -> "DetailReferenceBatch":
        return _selected(self, indices)

    def to(self, *args, **kwargs) -> "DetailReferenceBatch":
        return _moved(self, *args, **kwargs)


@dataclass
class PreparedFaceHandDetailConditioning:
    """Static face/hand detail tensors ready for the recurrent control branch."""

    detail_condition: torch.Tensor
    detail_tokens: torch.Tensor
    detail_token_mask: torch.Tensor
    region_masks: torch.Tensor
    region_valid: torch.Tensor
    detail_valid: torch.Tensor

    @property
    def batch_size(self) -> int:
        return int(self.detail_condition.shape[0])

    @property
    def device(self) -> torch.device:
        return self.detail_condition.device

    def validate(self) -> "PreparedFaceHandDetailConditioning":
        batch_size = self.batch_size
        if batch_size == 0:
            raise ValueError("prepared detail batch must be non-empty")
        if self.detail_condition.ndim != 4 or self.detail_condition.shape[1] != 144:
            raise ValueError("detail_condition must have shape [B,144,Hlat,Wlat]")
        if self.detail_tokens.ndim != 3 or self.detail_tokens.shape[:2] != (batch_size, 48):
            raise ValueError("detail_tokens must have shape [B,48,D]")
        if tuple(self.detail_token_mask.shape) != (batch_size, 48) or self.detail_token_mask.dtype != torch.bool:
            raise ValueError("detail_token_mask must have shape [B,48] and dtype bool")
        if self.region_masks.ndim != 5 or self.region_masks.shape[:3] != (batch_size, 2, 3):
            raise ValueError("region_masks must have shape [B,2,3,Htoken,Wtoken]")
        if tuple(self.region_valid.shape) != (batch_size, 2, 3) or self.region_valid.dtype != torch.bool:
            raise ValueError("region_valid must have shape [B,2,3] and dtype bool")
        if tuple(self.detail_valid.shape) != (batch_size,) or self.detail_valid.dtype != torch.bool:
            raise ValueError("detail_valid must have shape [B] and dtype bool")
        floating = (self.detail_condition, self.detail_tokens, self.region_masks)
        if any(not value.is_floating_point() for value in floating):
            raise ValueError("prepared detail floating tensors require a floating dtype")
        if any(value.dtype != floating[0].dtype for value in floating[1:]):
            raise ValueError("prepared detail floating tensors must share a dtype")
        tensors = (*floating, self.detail_token_mask, self.region_valid, self.detail_valid)
        if any(value.device != self.device for value in tensors[1:]):
            raise ValueError("prepared detail tensors must be on the same device")
        if any(not torch.isfinite(value).all() for value in floating):
            raise ValueError("prepared detail tensors must contain only finite values")
        if torch.any((self.region_masks < 0) | (self.region_masks > 1)):
            raise ValueError("region_masks must be bounded in [0,1]")
        expected_mask = self.region_valid[..., None].expand(
            -1, -1, -1, 8
        ).reshape(batch_size, 48)
        if not torch.equal(self.detail_token_mask, expected_mask):
            raise ValueError("detail_token_mask must repeat each region validity eight times")
        if torch.count_nonzero(self.detail_tokens[~self.detail_token_mask]):
            raise ValueError("invalid detail tokens must be exactly zero")
        if torch.count_nonzero(self.region_masks[~self.region_valid]):
            raise ValueError("invalid region masks must be exactly zero")
        expected_valid = self.region_valid.flatten(1).any(dim=1)
        if not torch.equal(self.detail_valid, expected_valid):
            raise ValueError("detail_valid must equal region_valid.any per sample")
        if torch.count_nonzero(self.detail_condition[~self.detail_valid]):
            raise ValueError("invalid sample detail_condition must be exactly zero")
        return self

    def index_select(self, indices: torch.Tensor) -> "PreparedFaceHandDetailConditioning":
        return _selected(self, indices)

    def to(self, *args, **kwargs) -> "PreparedFaceHandDetailConditioning":
        return _moved(self, *args, **kwargs)

    def expand_to_batch(self, batch_size: int) -> "PreparedFaceHandDetailConditioning":
        if self.batch_size == 0:
            raise ValueError("prepared detail batch must be non-empty")
        if batch_size <= 0 or batch_size % self.batch_size:
            raise ValueError(
                "expanded batch size must be a positive multiple of the current batch"
            )
        repeats = batch_size // self.batch_size
        values = {}
        for item in fields(self):
            value = getattr(self, item.name)
            values[item.name] = value.repeat((repeats,) + (1,) * (value.ndim - 1))
        return type(self)(**values).validate()

from __future__ import annotations

from dataclasses import dataclass, fields

import torch

from ..conditions import _to_preserving_discrete_dtype
from ..face import FaceFineCondition, dwpose68_to_face72
from .conditions import DetailReferenceBatch, FaceHandDetailCondition


def _map_fields(instance, transform):
    return type(instance)(
        **{
            field.name: transform(getattr(instance, field.name))
            for field in fields(instance)
        }
    )


@dataclass
class HandDetailCondition:
    """Hand-only geometry and source/target bindings for two people."""

    hand_keypoints: torch.Tensor
    hand_pose: torch.Tensor
    source_boxes: torch.Tensor
    target_boxes: torch.Tensor
    region_valid: torch.Tensor
    source_indices: torch.Tensor

    @property
    def batch_size(self) -> int:
        return int(self.hand_keypoints.shape[0])

    @property
    def person_valid(self) -> torch.Tensor:
        return self.region_valid.any(dim=-1)

    @property
    def device(self) -> torch.device:
        return self.hand_keypoints.device

    def validate(self) -> "HandDetailCondition":
        batch_size = self.batch_size
        if batch_size == 0:
            raise ValueError("hand condition batch must be non-empty")
        shapes = {
            "hand_keypoints": (batch_size, 2, 2, 21, 3),
            "hand_pose": (batch_size, 2, 2, 45),
            "source_boxes": (batch_size, 2, 2, 4),
            "target_boxes": (batch_size, 2, 2, 4),
        }
        floating: list[torch.Tensor] = []
        for name, shape in shapes.items():
            value = getattr(self, name)
            if tuple(value.shape) != shape:
                raise ValueError(f"{name} must have shape {shape}")
            if not value.is_floating_point():
                raise ValueError(f"{name} must use a floating dtype")
            if not torch.isfinite(value).all():
                raise ValueError(f"{name} must contain only finite values")
            floating.append(value)
        reference = floating[0]
        if any(value.dtype != reference.dtype for value in floating[1:]):
            raise ValueError("all floating hand tensors must use the same dtype")
        if any(value.device != reference.device for value in floating[1:]):
            raise ValueError("all hand tensors must use the same device")
        if (
            tuple(self.region_valid.shape) != (batch_size, 2, 2)
            or self.region_valid.dtype != torch.bool
        ):
            raise ValueError("region_valid must have shape [B,2,2] and dtype bool")
        if (
            tuple(self.source_indices.shape) != (batch_size, 2)
            or self.source_indices.dtype != torch.long
        ):
            raise ValueError("source_indices must have shape [B,2] and dtype int64")
        if (
            self.region_valid.device != reference.device
            or self.source_indices.device != reference.device
        ):
            raise ValueError("all hand tensors must use the same device")
        if torch.any((self.hand_keypoints < 0) | (self.hand_keypoints > 1)):
            raise ValueError("hand_keypoints xy/confidence values must lie in [0,1]")
        for name in ("source_boxes", "target_boxes"):
            boxes = getattr(self, name)
            if torch.any((boxes < 0) | (boxes > 1)):
                raise ValueError(f"{name} must contain normalized xyxy boxes")
            positive = (boxes[..., 0] < boxes[..., 2]) & (
                boxes[..., 1] < boxes[..., 3]
            )
            if self.region_valid.any() and not positive[self.region_valid].all():
                raise ValueError(f"valid {name} must contain positive-area boxes")
        valid_indices = self.source_indices[self.person_valid]
        if valid_indices.numel() and torch.any(
            (valid_indices < 0) | (valid_indices > 15)
        ):
            raise ValueError("valid source_indices must be in [0,15]")
        both_valid = self.person_valid.all(dim=1)
        if torch.any(
            both_valid & (self.source_indices[:, 0] == self.source_indices[:, 1])
        ):
            raise ValueError("valid people must use unique source_indices")
        return self

    def to(self, *args, **kwargs) -> "HandDetailCondition":
        return _map_fields(
            self,
            lambda value: _to_preserving_discrete_dtype(value, *args, **kwargs),
        )

    def index_select(self, indices: torch.Tensor) -> "HandDetailCondition":
        if indices.ndim != 1 or indices.dtype != torch.long:
            raise ValueError("indices must be a one-dimensional int64 tensor")
        return _map_fields(self, lambda value: value.index_select(0, indices))

    def expand_to_batch(self, batch_size: int) -> "HandDetailCondition":
        if batch_size <= 0 or batch_size % self.batch_size:
            raise ValueError("expanded batch must be a positive multiple")
        repeats = batch_size // self.batch_size
        return _map_fields(
            self,
            lambda value: value.repeat((repeats,) + (1,) * (value.ndim - 1)),
        ).validate()


def legacy_to_face_and_hand(
    condition: FaceHandDetailCondition,
) -> tuple[FaceFineCondition, HandDetailCondition]:
    """Split the V6.4 shared condition without sharing either branch input."""

    condition.validate()
    face = FaceFineCondition(
        landmarks=dwpose68_to_face72(condition.face_keypoints),
        expression=condition.smplx_detail[..., :10],
        jaw_pose=condition.smplx_detail[..., 10:13],
        source_boxes=condition.source_boxes[:, :, 0],
        target_boxes=condition.target_boxes[:, :, 0],
        face_valid=condition.region_valid[:, :, 0],
        source_indices=condition.source_indices,
    ).validate()
    hand_pose = torch.stack(
        (
            condition.smplx_detail[..., 13:58],
            condition.smplx_detail[..., 58:103],
        ),
        dim=2,
    )
    hand = HandDetailCondition(
        hand_keypoints=condition.hand_keypoints,
        hand_pose=hand_pose,
        source_boxes=condition.source_boxes[:, :, 1:],
        target_boxes=condition.target_boxes[:, :, 1:],
        region_valid=condition.region_valid[:, :, 1:],
        source_indices=condition.source_indices,
    ).validate()
    return face, hand


def hand_to_legacy_detail(condition: HandDetailCondition) -> FaceHandDetailCondition:
    """Build a V6.4-shaped hand-only payload for the retained detail branch."""

    condition.validate()
    batch_size = condition.batch_size
    hand_keypoints = condition.hand_keypoints
    false_face = torch.zeros(
        batch_size, 2, 1, device=condition.device, dtype=torch.bool
    )
    face_boxes = hand_keypoints.new_zeros(batch_size, 2, 1, 4)
    smplx_detail = hand_keypoints.new_zeros(batch_size, 2, 103)
    smplx_detail[..., 13:58] = condition.hand_pose[:, :, 0]
    smplx_detail[..., 58:103] = condition.hand_pose[:, :, 1]
    return FaceHandDetailCondition(
        face_keypoints=hand_keypoints.new_zeros(batch_size, 2, 68, 3),
        hand_keypoints=hand_keypoints,
        smplx_detail=smplx_detail,
        source_boxes=torch.cat((face_boxes, condition.source_boxes), dim=2),
        target_boxes=torch.cat((face_boxes, condition.target_boxes), dim=2),
        region_valid=torch.cat((false_face, condition.region_valid), dim=2),
        source_indices=condition.source_indices,
    )


def references_to_hand_only(
    references: DetailReferenceBatch,
) -> DetailReferenceBatch:
    """Copy legacy references while erasing face pixels and validity."""

    references.validate()
    images = references.images.clone()
    reference_valid = references.reference_valid.clone()
    images[:, :, 0].zero_()
    reference_valid[:, :, 0] = False
    return DetailReferenceBatch(images=images, reference_valid=reference_valid)


def legacy_to_hand_only(
    condition: FaceHandDetailCondition,
    references: DetailReferenceBatch | None = None,
) -> tuple[FaceHandDetailCondition, DetailReferenceBatch | None]:
    """Deprecated V6.4 compatibility path with face leakage removed."""

    _, hand = legacy_to_face_and_hand(condition)
    return hand_to_legacy_detail(hand), (
        None if references is None else references_to_hand_only(references)
    )


__all__ = [
    "HandDetailCondition",
    "hand_to_legacy_detail",
    "legacy_to_face_and_hand",
    "legacy_to_hand_only",
    "references_to_hand_only",
]

from __future__ import annotations

import torch
import torch.nn as nn
import torch.nn.functional as F

from .conditions import (
    DetailReferenceBatch,
    FaceHandDetailCondition,
    PreparedFaceHandDetailConditioning,
)
from .binder import DetailTokenBinder
from .encoders import (
    DetailAppearanceEncoder,
    DetailSpatialEncoder,
)


def soft_box_masks(
    boxes: torch.Tensor,
    valid: torch.Tensor,
    spatial_size: tuple[int, int],
    *,
    sharpness: float = 40.0,
) -> torch.Tensor:
    """Rasterize bounded soft boxes; invalid regions are exactly zero."""

    if len(spatial_size) != 2 or min(spatial_size) <= 0:
        raise ValueError("spatial_size must contain two positive dimensions")
    height, width = spatial_size
    y = (torch.arange(height, device=boxes.device, dtype=boxes.dtype) + 0.5) / height
    x = (torch.arange(width, device=boxes.device, dtype=boxes.dtype) + 0.5) / width
    y = y.reshape((1,) * (boxes.ndim - 1) + (height, 1))
    x = x.reshape((1,) * (boxes.ndim - 1) + (1, width))
    x1, y1, x2, y2 = boxes.unbind(dim=-1)
    x1, x2 = x1[..., None, None], x2[..., None, None]
    y1, y2 = y1[..., None, None], y2[..., None, None]
    mask = (
        torch.sigmoid((x - x1) * sharpness)
        * torch.sigmoid((x2 - x) * sharpness)
        * torch.sigmoid((y - y1) * sharpness)
        * torch.sigmoid((y2 - y) * sharpness)
    )
    return mask * valid[..., None, None].to(mask.dtype)


class FaceHandDetailPreparer(nn.Module):
    """Validate and statically prepare local detail control inputs."""

    def __init__(
        self,
        *,
        token_dim: int,
        hidden_dim: int = 256,
    ) -> None:
        super().__init__()
        self.spatial_encoder = DetailSpatialEncoder(hidden_dim=hidden_dim)
        self.appearance_encoder = DetailAppearanceEncoder(
            token_dim=token_dim, hidden_dim=hidden_dim
        )
        self.token_binder = DetailTokenBinder(token_dim=token_dim)

    @staticmethod
    def _validate_source_latents(
        source_latents: torch.Tensor,
        condition: FaceHandDetailCondition,
    ) -> None:
        valid_shape = (
            source_latents.ndim == 4
            and source_latents.shape[:2] == (condition.batch_size, 16)
        ) or (
            source_latents.ndim == 5
            and source_latents.shape[:3] == (condition.batch_size, 2, 16)
        )
        if not valid_shape:
            raise ValueError("source_latents must have shape [B,16,H,W] or [B,2,16,H,W]")
        if not source_latents.is_floating_point():
            raise ValueError("source_latents must use a floating dtype")
        if source_latents.device != condition.device:
            raise ValueError("source_latents and condition must be on the same device")
        if not torch.isfinite(source_latents).all():
            raise ValueError("source_latents must contain only finite values")

    @staticmethod
    def _source_canvas(
        source_latents: torch.Tensor,
        condition: FaceHandDetailCondition,
        latent_masks: torch.Tensor,
    ) -> torch.Tensor:
        batch_size, _, height, width = latent_masks.shape[0], 16, latent_masks.shape[-2], latent_masks.shape[-1]
        y = (torch.arange(height, device=source_latents.device, dtype=source_latents.dtype) + 0.5) / height
        x = (torch.arange(width, device=source_latents.device, dtype=source_latents.dtype) + 0.5) / width
        yy, xx = torch.meshgrid(y, x, indexing="ij")
        numerator = source_latents.new_zeros(batch_size, 16, height, width)
        denominator = source_latents.new_zeros(batch_size, 1, height, width)
        for person in range(2):
            for region in range(3):
                source = condition.source_boxes[:, person, region]
                target = condition.target_boxes[:, person, region]
                target_width = (target[:, 2] - target[:, 0]).clamp_min(1e-6)
                target_height = (target[:, 3] - target[:, 1]).clamp_min(1e-6)
                relative_x = (
                    xx[None] - target[:, 0, None, None]
                ) / target_width[:, None, None]
                relative_y = (
                    yy[None] - target[:, 1, None, None]
                ) / target_height[:, None, None]
                source_x = source[:, 0, None, None] + relative_x * (
                    source[:, 2] - source[:, 0]
                )[:, None, None]
                source_y = source[:, 1, None, None] + relative_y * (
                    source[:, 3] - source[:, 1]
                )[:, None, None]
                grid = torch.stack((source_x * 2 - 1, source_y * 2 - 1), dim=-1)
                person_source = (
                    source_latents
                    if source_latents.ndim == 4
                    else source_latents[:, person]
                )
                warped = F.grid_sample(
                    person_source,
                    grid,
                    mode="bilinear",
                    padding_mode="zeros",
                    align_corners=False,
                )
                weight = latent_masks[:, person, region, None]
                numerator = numerator + warped * weight
                denominator = denominator + weight
        return numerator / denominator.clamp_min(1.0)

    def forward(
        self,
        condition: FaceHandDetailCondition,
        references: DetailReferenceBatch,
        latent_spatial_size: tuple[int, int],
        token_spatial_size: tuple[int, int],
        source_latents: torch.Tensor | None = None,
        *,
        reference_features: torch.Tensor | None = None,
        person_binding: torch.Tensor,
    ) -> PreparedFaceHandDetailConditioning:
        condition.validate()
        references.validate()
        if references.batch_size != condition.batch_size:
            raise ValueError("condition and references must have the same batch size")
        if references.device != condition.device:
            raise ValueError("condition and references must be on the same device")
        if references.images.dtype != condition.face_keypoints.dtype:
            raise ValueError("condition and reference images must use the same dtype")
        if person_binding.ndim != 3 or person_binding.shape[:2] != (
            condition.batch_size,
            2,
        ):
            raise ValueError("person_binding must have shape [B,2,D]")
        if not person_binding.is_floating_point() or person_binding.device != condition.device:
            raise ValueError("person_binding must be floating and colocated with condition")

        if source_latents is not None:
            self._validate_source_latents(source_latents, condition)

        parameter = next(self.parameters())
        condition = condition.to(device=parameter.device, dtype=parameter.dtype)
        references = references.to(device=parameter.device, dtype=parameter.dtype)
        person_binding = person_binding.to(
            device=parameter.device, dtype=parameter.dtype
        )
        if reference_features is not None:
            reference_features = reference_features.to(
                device=parameter.device, dtype=parameter.dtype
            )
        if source_latents is not None:
            source_latents = source_latents.to(
                device=parameter.device, dtype=parameter.dtype
            )

        latent_masks = soft_box_masks(
            condition.target_boxes, condition.region_valid, latent_spatial_size
        )
        region_masks = soft_box_masks(
            condition.target_boxes, condition.region_valid, token_spatial_size
        )
        geometry = self.spatial_encoder(condition, latent_masks)
        if source_latents is None:
            source_canvas = geometry.new_zeros(
                condition.batch_size, 16, *latent_spatial_size
            )
        else:
            source_canvas = self._source_canvas(
                source_latents, condition, latent_masks
            )
        detail_valid = condition.region_valid.flatten(1).any(dim=1)
        detail_condition = torch.cat((source_canvas, geometry), dim=1)
        detail_condition = detail_condition * detail_valid[:, None, None, None].to(
            detail_condition.dtype
        )

        region_tokens = self.appearance_encoder(
            references, reference_features=reference_features
        )
        detail_tokens, detail_token_mask = self.token_binder(
            region_tokens, condition.region_valid, person_binding
        )
        return PreparedFaceHandDetailConditioning(
            detail_condition=detail_condition,
            detail_tokens=detail_tokens,
            detail_token_mask=detail_token_mask,
            region_masks=region_masks,
            region_valid=condition.region_valid,
            detail_valid=detail_valid,
        ).validate()

from __future__ import annotations

from dataclasses import dataclass

import torch


@dataclass
class RoutingDecision:
    num_people: torch.Tensor
    single_mask: torch.Tensor
    dual_mask: torch.Tensor


class TaskRouter:
    """Route exclusively from the validated number of SMPL-X instances."""

    def resolve(self, person_count: torch.Tensor) -> RoutingDecision:
        if person_count.ndim != 1:
            raise ValueError("person_count must have shape [B]")
        num_people = person_count.long()
        if torch.any((num_people < 1) | (num_people > 2)):
            raise ValueError("router supports one or two people only")
        return RoutingDecision(
            num_people=num_people,
            single_mask=num_people == 1,
            dual_mask=num_people == 2,
        )

from __future__ import annotations

from dataclasses import dataclass, fields

import torch

from ..conditions import _to_preserving_discrete_dtype


def _index_selected(instance, indices: torch.Tensor):
    if indices.dtype != torch.long or indices.ndim != 1:
        raise ValueError("indices must be a one-dimensional int64 tensor")
    return type(instance)(
        **{
            item.name: getattr(instance, item.name).index_select(0, indices)
            for item in fields(instance)
        }
    )


def _moved(instance, *args, **kwargs):
    return type(instance)(
        **{
            item.name: _to_preserving_discrete_dtype(
                getattr(instance, item.name), *args, **kwargs
            )
            for item in fields(instance)
        }
    )


def _expanded(instance, batch_size: int):
    current = instance.batch_size
    if current == 0:
        raise ValueError("batch must be non-empty before expansion")
    if batch_size <= 0 or batch_size % current:
        raise ValueError(
            "expanded batch size must be a positive multiple of the current batch"
        )
    repeats = batch_size // current
    return type(instance)(
        **{
            item.name: getattr(instance, item.name).repeat(
                (repeats,) + (1,) * (getattr(instance, item.name).ndim - 1)
            )
            for item in fields(instance)
        }
    ).validate()


def _validate_same_float_dtype_device(
    named_tensors: dict[str, torch.Tensor],
) -> tuple[torch.dtype, torch.device]:
    first_name, first = next(iter(named_tensors.items()))
    if not first.is_floating_point():
        raise ValueError(f"{first_name} must use a floating dtype")
    for name, value in named_tensors.items():
        if not value.is_floating_point():
            raise ValueError(f"{name} must use a floating dtype")
        if value.dtype != first.dtype:
            raise ValueError("all floating tensors must use the same dtype")
        if value.device != first.device:
            raise ValueError("all tensors must be on the same device")
        if not torch.isfinite(value).all():
            raise ValueError("floating tensors must contain only finite values")
    return first.dtype, first.device


def _validate_normalized_boxes(
    boxes: torch.Tensor,
    valid: torch.Tensor,
    *,
    name: str,
) -> None:
    if torch.any((boxes < 0) | (boxes > 1)):
        raise ValueError(f"{name} must contain normalized xyxy boxes in [0,1]")
    positive = (boxes[..., 0] < boxes[..., 2]) & (
        boxes[..., 1] < boxes[..., 3]
    )
    if valid.any() and not positive[valid].all():
        raise ValueError(f"valid {name} must contain positive-area xyxy boxes")


@dataclass
class FaceFineCondition:
    """Fine face geometry and two-person source/target bindings."""

    landmarks: torch.Tensor
    jaw_pose: torch.Tensor
    expression: torch.Tensor
    source_boxes: torch.Tensor
    target_boxes: torch.Tensor
    face_valid: torch.Tensor
    source_indices: torch.Tensor

    @property
    def batch_size(self) -> int:
        return int(self.landmarks.shape[0])

    @property
    def device(self) -> torch.device:
        return self.landmarks.device

    def validate(self) -> "FaceFineCondition":
        batch_size = self.batch_size
        if batch_size == 0:
            raise ValueError("face condition batch must be non-empty")
        expected_shapes = {
            "landmarks": (batch_size, 2, 72, 3),
            "jaw_pose": (batch_size, 2, 3),
            "expression": (batch_size, 2, 10),
            "source_boxes": (batch_size, 2, 4),
            "target_boxes": (batch_size, 2, 4),
        }
        floating = {}
        for name, expected in expected_shapes.items():
            value = getattr(self, name)
            if tuple(value.shape) != expected:
                raise ValueError(f"{name} must have shape {expected}")
            floating[name] = value
        _, device = _validate_same_float_dtype_device(floating)
        if tuple(self.face_valid.shape) != (batch_size, 2) or self.face_valid.dtype != torch.bool:
            raise ValueError("face_valid must have shape [B,2] and dtype bool")
        if (
            tuple(self.source_indices.shape) != (batch_size, 2)
            or self.source_indices.dtype != torch.long
        ):
            raise ValueError("source_indices must have shape [B,2] and dtype int64")
        if self.face_valid.device != device or self.source_indices.device != device:
            raise ValueError("all tensors must be on the same device")
        if torch.any((self.landmarks[..., 2] < 0) | (self.landmarks[..., 2] > 1)):
            raise ValueError("landmark confidence must be in [0,1]")
        _validate_normalized_boxes(
            self.source_boxes, self.face_valid, name="source_boxes"
        )
        _validate_normalized_boxes(
            self.target_boxes, self.face_valid, name="target_boxes"
        )
        valid_indices = self.source_indices[self.face_valid]
        if valid_indices.numel() and torch.any(
            (valid_indices < 0) | (valid_indices > 15)
        ):
            raise ValueError("valid source_indices must be in [0, 15]")
        both_valid = self.face_valid.all(dim=1)
        duplicates = self.source_indices[:, 0] == self.source_indices[:, 1]
        if torch.any(both_valid & duplicates):
            raise ValueError(
                "valid people must use unique source_indices within each sample"
            )
        return self

    def to(self, *args, **kwargs) -> "FaceFineCondition":
        return _moved(self, *args, **kwargs)

    def index_select(self, indices: torch.Tensor) -> "FaceFineCondition":
        return _index_selected(self, indices)

    def expand_to_batch(self, batch_size: int) -> "FaceFineCondition":
        return _expanded(self, batch_size)


@dataclass
class FaceReferenceFeatures:
    """One to three precomputed ArcFace and DINO references per person."""

    arcface: torch.Tensor
    dino_patches: torch.Tensor
    reference_valid: torch.Tensor

    @property
    def batch_size(self) -> int:
        return int(self.arcface.shape[0])

    @property
    def reference_count(self) -> int:
        return int(self.arcface.shape[2])

    @property
    def device(self) -> torch.device:
        return self.arcface.device

    def validate(self) -> "FaceReferenceFeatures":
        if self.arcface.ndim != 4:
            raise ValueError("arcface must have shape [B,2,R,512]")
        batch_size, people, reference_count, feature_dim = self.arcface.shape
        if people != 2 or feature_dim != 512:
            raise ValueError("arcface must have shape [B,2,R,512]")
        if batch_size == 0:
            raise ValueError("face reference batch must be non-empty")
        if not 1 <= reference_count <= 3:
            raise ValueError("face reference count must be between 1 and 3")
        expected_dino = (batch_size, 2, reference_count, 256, 1536)
        if tuple(self.dino_patches.shape) != expected_dino:
            raise ValueError(f"dino_patches must have shape {expected_dino}")
        expected_valid = (batch_size, 2, reference_count)
        if (
            tuple(self.reference_valid.shape) != expected_valid
            or self.reference_valid.dtype != torch.bool
        ):
            raise ValueError(
                f"reference_valid must have shape {expected_valid} and dtype bool"
            )
        _, device = _validate_same_float_dtype_device(
            {"arcface": self.arcface, "dino_patches": self.dino_patches}
        )
        if self.reference_valid.device != device:
            raise ValueError("all tensors must be on the same device")
        return self

    def to(self, *args, **kwargs) -> "FaceReferenceFeatures":
        return _moved(self, *args, **kwargs)

    def index_select(self, indices: torch.Tensor) -> "FaceReferenceFeatures":
        return _index_selected(self, indices)

    def expand_to_batch(self, batch_size: int) -> "FaceReferenceFeatures":
        return _expanded(self, batch_size)


@dataclass
class PreparedFaceConditioning:
    """Validated ROI-local face tensors ready for a Face Control Adapter."""

    spatial_features: torch.Tensor
    identity_tokens: torch.Tensor
    texture_tokens: torch.Tensor
    texture_delta: torch.Tensor
    geometry_tokens: torch.Tensor
    face_masks: torch.Tensor
    target_boxes: torch.Tensor
    face_valid: torch.Tensor

    @property
    def batch_size(self) -> int:
        return int(self.spatial_features.shape[0])

    @property
    def device(self) -> torch.device:
        return self.spatial_features.device

    def validate(self) -> "PreparedFaceConditioning":
        batch_size = self.batch_size
        if batch_size == 0:
            raise ValueError("prepared face batch must be non-empty")
        expected = {
            "spatial_features": (batch_size, 2, 512, 16, 16),
            "identity_tokens": (batch_size, 2, 4, 512),
            "texture_tokens": (batch_size, 2, 8, 512),
            "texture_delta": (batch_size, 2, 4, 512),
            "geometry_tokens": (batch_size, 2, 4, 512),
            "target_boxes": (batch_size, 2, 4),
        }
        floating = {}
        for name, shape in expected.items():
            value = getattr(self, name)
            if tuple(value.shape) != shape:
                raise ValueError(f"{name} must have shape {shape}")
            floating[name] = value
        if self.face_masks.ndim != 4 or self.face_masks.shape[:2] != (
            batch_size,
            2,
        ):
            raise ValueError("face_masks must have shape [B,2,H,W]")
        if min(self.face_masks.shape[-2:]) <= 0:
            raise ValueError("face mask spatial dimensions must be positive")
        floating["face_masks"] = self.face_masks
        _, device = _validate_same_float_dtype_device(floating)
        if tuple(self.face_valid.shape) != (batch_size, 2) or self.face_valid.dtype != torch.bool:
            raise ValueError("face_valid must have shape [B,2] and dtype bool")
        if self.face_valid.device != device:
            raise ValueError("all tensors must be on the same device")
        if torch.any((self.face_masks < 0) | (self.face_masks > 1)):
            raise ValueError("face_masks must be bounded in [0,1]")
        _validate_normalized_boxes(
            self.target_boxes, self.face_valid, name="target_boxes"
        )
        invalid = ~self.face_valid
        for name, value in floating.items():
            if torch.count_nonzero(value[invalid]):
                raise ValueError(f"invalid people must have exactly zero {name}")
        return self

    def to(self, *args, **kwargs) -> "PreparedFaceConditioning":
        return _moved(self, *args, **kwargs)

    def index_select(self, indices: torch.Tensor) -> "PreparedFaceConditioning":
        return _index_selected(self, indices)

    def expand_to_batch(self, batch_size: int) -> "PreparedFaceConditioning":
        return _expanded(self, batch_size)

from __future__ import annotations

import math

import torch
import torch.nn as nn
import torch.nn.functional as F


def _group_count(channels: int) -> int:
    return next(group for group in (32, 16, 8, 4, 2, 1) if channels % group == 0)


class ConditionResBlock(nn.Module):
    def __init__(self, channels: int) -> None:
        super().__init__()
        groups = _group_count(channels)
        self.block = nn.Sequential(
            nn.GroupNorm(groups, channels),
            nn.SiLU(),
            nn.Conv2d(channels, channels, 3, padding=1),
            nn.GroupNorm(groups, channels),
            nn.SiLU(),
            nn.Conv2d(channels, channels, 3, padding=1),
        )

    def forward(self, value: torch.Tensor) -> torch.Tensor:
        return value + self.block(value)


class NativeConditionStem(nn.Module):
    """Three-level GroupNorm/SiLU stem for one explicit condition modality."""

    def __init__(
        self,
        in_channels: int,
        channels: tuple[int, int, int],
        *,
        project_to: int | None = None,
        sparse_init: bool = False,
    ) -> None:
        super().__init__()
        first_channels = project_to or in_channels
        self.input_projection = (
            nn.Identity()
            if project_to is None
            else nn.Conv2d(in_channels, project_to, kernel_size=1)
        )
        stages = []
        current = first_channels
        for output in channels:
            stages.extend(
                (
                    nn.Conv2d(current, output, 3, stride=2, padding=1),
                    nn.GroupNorm(_group_count(output), output),
                    nn.SiLU(),
                    ConditionResBlock(output),
                )
            )
            current = output
        self.stages = nn.Sequential(*stages)
        if sparse_init:
            self._initialize_sparse_convolutions()

    def _initialize_sparse_convolutions(self) -> None:
        for module in self.modules():
            if isinstance(module, nn.Conv2d):
                fan_in = module.kernel_size[0] * module.kernel_size[1] * module.in_channels
                nn.init.normal_(module.weight, mean=0.0, std=math.sqrt(2.0 / fan_in))
                if module.bias is not None:
                    nn.init.zeros_(module.bias)

    def forward(self, value: torch.Tensor) -> torch.Tensor:
        return self.stages(self.input_projection(value))


class RoleFiLM(nn.Module):
    def __init__(self, channels: int = 256, embedding_dim: int = 128) -> None:
        super().__init__()
        self.role_embedding = nn.Embedding(2, embedding_dim)
        self.to_scale_shift = nn.Sequential(
            nn.Linear(embedding_dim, embedding_dim),
            nn.SiLU(),
            nn.Linear(embedding_dim, channels * 2),
        )

    def forward(self, value: torch.Tensor, role_id: int) -> torch.Tensor:
        roles = torch.full((value.shape[0],), role_id, dtype=torch.long, device=value.device)
        scale, shift = self.to_scale_shift(self.role_embedding(roles)).chunk(2, dim=-1)
        return value * (1 + scale[..., None, None]) + shift[..., None, None]


class ChampConditionStemAdapter(nn.Module):
    """Adapt Normal or scalar Depth to the vendored single-frame CHAMP stem."""

    def __init__(self, in_channels: int, output_channels: int = 128) -> None:
        super().__init__()
        if in_channels not in (1, 3):
            raise ValueError("CHAMP condition stem supports 1-channel depth or 3-channel normal")
        from third_party.champ_guidance import ChampGuidanceEncoder

        self.in_channels = in_channels
        self.encoder = ChampGuidanceEncoder(
            guidance_embedding_channels=output_channels,
            guidance_input_channels=3,
        )

    def forward(self, value: torch.Tensor) -> torch.Tensor:
        if self.in_channels == 1:
            value = value.expand(-1, 3, -1, -1)
        return self.encoder(value)


class SpatialConditionEncoder(nn.Module):
    """Independent stems followed by mid-level fusion and role binding."""

    def __init__(
        self,
        *,
        use_depth: bool = False,
        output_channels: int = 256,
        normal_backend: str = "native",
        depth_backend: str = "native",
    ) -> None:
        super().__init__()
        self.use_depth = use_depth
        self.normal_stem = (
            NativeConditionStem(3, (32, 64, 128))
            if normal_backend == "native"
            else ChampConditionStemAdapter(3)
        )
        self.pose_stem = NativeConditionStem(
            25, (64, 96, 128), project_to=32, sparse_init=True
        )
        self.part_stem = NativeConditionStem(14, (64, 96, 128), project_to=32)
        self.depth_stem = None
        if use_depth:
            self.depth_stem = (
                NativeConditionStem(1, (32, 64, 128))
                if depth_backend == "native"
                else ChampConditionStemAdapter(1)
            )
        fusion_input = 128 * (4 if use_depth else 3)
        self.fusion = nn.Sequential(
            nn.Conv2d(fusion_input, output_channels, 1),
            nn.GroupNorm(_group_count(output_channels), output_channels),
            nn.SiLU(),
            nn.Conv2d(output_channels, output_channels, 3, padding=1),
            nn.GroupNorm(_group_count(output_channels), output_channels),
            nn.SiLU(),
            ConditionResBlock(output_channels),
            ConditionResBlock(output_channels),
        )
        self.role_film = RoleFiLM(output_channels)

    def forward(
        self,
        *,
        normal: torch.Tensor,
        pose_heatmap: torch.Tensor,
        part_onehot: torch.Tensor,
        human_mask: torch.Tensor,
        role_id: int,
        depth: torch.Tensor | None = None,
        valid: torch.Tensor | None = None,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        mask = human_mask.to(dtype=normal.dtype)
        features = (
            self.normal_stem(normal * mask),
            self.pose_stem(pose_heatmap * mask),
            self.part_stem(part_onehot * mask),
        )
        if self.use_depth:
            if depth is None:
                depth = normal.new_zeros(normal.shape[0], 1, *normal.shape[-2:])
            features = (*features, self.depth_stem(depth * mask))
        spatial = self.role_film(self.fusion(torch.cat(features, dim=1)), role_id)
        output_mask = F.interpolate(mask, size=spatial.shape[-2:], mode="nearest")
        if valid is not None:
            valid_map = valid.to(spatial.dtype)[:, None, None, None]
            spatial = spatial * valid_map
            output_mask = output_mask * valid_map
        return spatial, output_mask


def normalize_scene_depth(
    depth_a: torch.Tensor | None,
    depth_b: torch.Tensor | None,
    mask_a: torch.Tensor,
    mask_b: torch.Tensor | None,
    person_b_valid: torch.Tensor,
    *,
    eps: float = 1e-6,
) -> tuple[torch.Tensor | None, torch.Tensor | None]:
    """Normalize A/B camera-space depth with one range per scene."""

    if depth_a is None and depth_b is None:
        return None, None
    has_depth_a = depth_a is not None
    has_depth_b = depth_b is not None
    template = depth_a if depth_a is not None else depth_b
    work_depth_a = torch.zeros_like(template) if depth_a is None else depth_a
    work_depth_b = torch.zeros_like(template) if depth_b is None else depth_b
    if mask_b is None:
        mask_b = torch.zeros_like(mask_a)
    if not has_depth_a:
        mask_a = torch.zeros_like(mask_a)
    if not has_depth_b:
        mask_b = torch.zeros_like(mask_b)
    valid_b = person_b_valid[:, None, None, None]
    mask_b = mask_b * valid_b.to(mask_b.dtype)
    result_a = torch.zeros_like(work_depth_a) if has_depth_a else None
    result_b = torch.zeros_like(work_depth_b) if has_depth_b else None
    for index in range(template.shape[0]):
        values = []
        if mask_a[index].bool().any():
            values.append(work_depth_a[index][mask_a[index].bool()])
        if mask_b[index].bool().any():
            values.append(work_depth_b[index][mask_b[index].bool()])
        if not values:
            continue
        joined = torch.cat(values)
        minimum, maximum = joined.amin(), joined.amax()
        span = maximum - minimum
        if span > eps:
            if result_a is not None:
                result_a[index] = (
                    (work_depth_a[index] - minimum) / span * 2 - 1
                ) * mask_a[index]
            if result_b is not None:
                result_b[index] = (
                    (work_depth_b[index] - minimum) / span * 2 - 1
                ) * mask_b[index]
    if result_b is not None:
        result_b = result_b * valid_b.to(result_b.dtype)
    return result_a, result_b

from __future__ import annotations

from dataclasses import dataclass, fields

import torch

from ..conditions import _to_preserving_discrete_dtype
from ..detail.hand import HandDetailCondition


def _transform(obj, function):
    return type(obj)(**{field.name: function(getattr(obj, field.name)) for field in fields(obj)})


@dataclass
class HandFineCondition(HandDetailCondition):
    """Target-only local geometry; no target RGB is required at inference."""

    mesh_bps: torch.Tensor
    mesh_valid: torch.Tensor
    depth: torch.Tensor
    visibility: torch.Tensor

    @classmethod
    def from_legacy(cls, value: HandDetailCondition) -> "HandFineCondition":
        value.validate()
        b = value.batch_size
        return cls(
            **{field.name: getattr(value, field.name) for field in fields(HandDetailCondition)},
            mesh_bps=value.hand_pose.new_zeros(b, 2, 2, 1024),
            mesh_valid=torch.zeros(b, 2, 2, dtype=torch.bool, device=value.device),
            depth=value.hand_pose.new_zeros(b, 2, 2, 1, 16, 16),
            visibility=value.region_valid.to(value.hand_pose.dtype),
        )

    def validate(self) -> "HandFineCondition":
        super().validate()
        b = self.batch_size
        expected = {"mesh_bps": (b, 2, 2, 1024), "depth": (b, 2, 2, 1, 16, 16), "visibility": (b, 2, 2)}
        for name, shape in expected.items():
            value = getattr(self, name)
            if value.shape != shape or value.dtype != self.hand_pose.dtype or value.device != self.device or not torch.isfinite(value).all():
                raise ValueError(f"{name} must be finite {shape} and match hand dtype/device")
        if self.mesh_valid.shape != (b, 2, 2) or self.mesh_valid.dtype != torch.bool or self.mesh_valid.device != self.device:
            raise ValueError("mesh_valid must be bool [B,2,2] on the hand device")
        if torch.any((self.visibility < 0) | (self.visibility > 1)):
            raise ValueError("visibility must lie in [0,1]")
        return self

    def to(self, *args, **kwargs):
        return _transform(self, lambda x: _to_preserving_discrete_dtype(x, *args, **kwargs))

    def index_select(self, indices):
        return _transform(self, lambda x: x.index_select(0, indices))

    def expand_to_batch(self, batch_size):
        if batch_size <= 0 or batch_size % self.batch_size:
            raise ValueError("invalid expanded batch size")
        factor = batch_size // self.batch_size
        return _transform(self, lambda x: x.repeat((factor,) + (1,) * (x.ndim - 1))).validate()


@dataclass
class HandReferenceFeatures:
    """Source-hand DINOv2 patch cache; [B,person,side,reference,patch,1536]."""

    dino_patches: torch.Tensor
    reference_valid: torch.Tensor
    source_indices: torch.Tensor

    @property
    def batch_size(self):
        return self.dino_patches.shape[0]

    def validate(self):
        patches = self.dino_patches
        if patches.ndim != 6 or patches.shape[1:3] != (2, 2) or patches.shape[-1] != 1536 or not 1 <= patches.shape[3] <= 3:
            raise ValueError("dino_patches must have shape [B,2,2,R,N,1536], R<=3")
        if self.reference_valid.shape != patches.shape[:4] or self.reference_valid.dtype != torch.bool:
            raise ValueError("reference_valid must be bool [B,2,2,R]")
        if self.source_indices.shape != (patches.shape[0], 2) or self.source_indices.dtype != torch.long:
            raise ValueError("source_indices must be int64 [B,2]")
        if patches.device != self.reference_valid.device or patches.device != self.source_indices.device or not torch.isfinite(patches).all():
            raise ValueError("reference tensors must be finite and colocated")
        return self

    def to(self, *args, **kwargs):
        return _transform(self, lambda x: _to_preserving_discrete_dtype(x, *args, **kwargs))

    def index_select(self, indices):
        return _transform(self, lambda x: x.index_select(0, indices))


@dataclass
class PreparedHandConditioning:
    spatial_features: torch.Tensor  # [B,2,2,256,D]
    geometry_tokens: torch.Tensor  # [B,2,2,4,D]
    appearance_tokens: torch.Tensor  # [B,2,2,8,D]
    hand_masks: torch.Tensor  # [B,2,2,16,16]
    target_boxes: torch.Tensor
    hand_valid: torch.Tensor
    visibility: torch.Tensor
    depth: torch.Tensor  # [B,2,2,1,16,16], smaller is closer

    @property
    def batch_size(self):
        return self.spatial_features.shape[0]

    @property
    def device(self):
        return self.spatial_features.device

    def validate(self):
        b, _, _, _, dim = self.spatial_features.shape
        for name, shape in {
            "spatial_features": (b, 2, 2, 256, dim),
            "geometry_tokens": (b, 2, 2, 4, dim),
            "appearance_tokens": (b, 2, 2, 8, dim),
            "hand_masks": (b, 2, 2, 16, 16),
            "target_boxes": (b, 2, 2, 4),
            "visibility": (b, 2, 2),
            "depth": (b, 2, 2, 1, 16, 16),
        }.items():
            if getattr(self, name).shape != shape:
                raise ValueError(f"{name} must have shape {shape}")
        if self.hand_valid.shape != (b, 2, 2) or self.hand_valid.dtype != torch.bool:
            raise ValueError("hand_valid must be bool [B,2,2]")
        return self

    def to(self, *args, **kwargs):
        return _transform(self, lambda x: _to_preserving_discrete_dtype(x, *args, **kwargs))

    def index_select(self, indices):
        return _transform(self, lambda x: x.index_select(0, indices))

"""Offline-only SMPL-X hand quality gate and conservative refinement merge."""
from __future__ import annotations

import torch


def hand_quality_gate(keypoints: torch.Tensor, boxes: torch.Tensor, *, min_side: float = .035, min_confidence: float = .35) -> torch.Tensor:
    """True means request 2D refinement; does not imply target RGB at inference."""
    if keypoints.shape[-2:] != (21, 3) or boxes.shape[-1] != 4:
        raise ValueError("expected hand keypoints [...,21,3] and boxes [...,4]")
    size = boxes[..., 2:] - boxes[..., :2]
    confidence = keypoints[..., 2].mean(-1)
    outside = ((keypoints[..., :2] < 0) | (keypoints[..., :2] > 1)).any(-1).float().mean(-1)
    return (size.amin(-1) < min_side) | (confidence < min_confidence) | (outside > .2)


def merge_vitpose_keypoints(smplx: torch.Tensor, vitpose: torch.Tensor, refine: torch.Tensor, *, min_confidence: float = .25) -> torch.Tensor:
    """Use a confident ViTPose result for flagged samples; preserve SMPL-X otherwise."""
    if vitpose.shape != smplx.shape or smplx.shape[-2:] != (21, 3) or refine.shape != smplx.shape[:-2]:
        raise ValueError("ViTPose refinement shapes must match 21-point SMPL-X hands")
    accept = refine & (vitpose[..., 2].mean(-1) >= min_confidence)
    return torch.where(accept[..., None, None], vitpose, smplx)

"""Shape-adapted VTON-HandFit Handprocessor and Perceiver Resampler primitives.

Upstream: VTON-HandFit/VTON-HandFit e69aaacc8285c2bd248ff9b1b6d8e9b92b1f8b5a
HandFit/pose_guider.py and HandFit/ip_adapter/resampler.py. The projection
topology and latent-query attention are retained; dimensions are exposed for
DeepGen's 512-wide hand stream. No UNet or CUDA-specific operation is imported.
"""
from __future__ import annotations

import torch
import torch.nn as nn
import torch.nn.functional as F


class FeatureEmbedderLN(nn.Module):
    def __init__(self, input_dim: int, hidden_dim: int, output_dim: int):
        super().__init__()
        self.linear = nn.Sequential(
            nn.Linear(input_dim, hidden_dim), nn.LayerNorm(hidden_dim), nn.ReLU(),
            nn.Linear(hidden_dim, hidden_dim), nn.LayerNorm(hidden_dim), nn.ReLU(),
            nn.Linear(hidden_dim, output_dim), nn.LayerNorm(output_dim),
        )

    def forward(self, x):
        return self.linear(x)


class OneLinearLN(nn.Module):
    def __init__(self, input_dim: int, output_dim: int):
        super().__init__()
        self.linear = nn.Sequential(nn.Linear(input_dim, output_dim), nn.LayerNorm(output_dim))

    def forward(self, x):
        return self.linear(x)


class HandStructureProjector(nn.Module):
    """VTON's separate BPS/6D/side/2D projectors with an explicit null BPS."""

    def __init__(self, dim: int = 512):
        super().__init__()
        self.mano_bps = FeatureEmbedderLN(1024, max(dim, 64), dim)
        self.mano_6d = OneLinearLN(96, dim)
        self.handtype = OneLinearLN(1, dim)
        self.mano_2d = FeatureEmbedderLN(42, max(dim, 64), dim)
        self.combined = OneLinearLN(dim * 3, dim)
        self.null_bps = nn.Parameter(torch.zeros(dim))

    def forward(self, bps, pose6d, points42, side, mesh_valid):
        bps_features = self.mano_bps(bps)
        bps_features = torch.where(mesh_valid[..., None], bps_features, self.null_bps)
        volume = self.combined(torch.cat((bps_features, self.mano_6d(pose6d), self.handtype(side)), -1))
        return volume, self.mano_2d(points42)


class PerceiverAttention(nn.Module):
    def __init__(self, dim: int, heads: int = 8):
        super().__init__()
        if dim % heads:
            raise ValueError("dim must divide heads")
        self.heads = heads
        self.dim_head = dim // heads
        self.norm1 = nn.LayerNorm(dim)
        self.norm2 = nn.LayerNorm(dim)
        self.to_q = nn.Linear(dim, dim, bias=False)
        self.to_kv = nn.Linear(dim, dim * 2, bias=False)
        self.to_out = nn.Linear(dim, dim, bias=False)

    def forward(self, x, latents):
        b, n, d = latents.shape
        q = self.to_q(self.norm2(latents)).reshape(b, n, self.heads, self.dim_head).transpose(1, 2)
        kv = self.to_kv(torch.cat((self.norm1(x), self.norm2(latents)), dim=1))
        k, v = (tensor.reshape(b, -1, self.heads, self.dim_head).transpose(1, 2) for tensor in kv.chunk(2, -1))
        scale = self.dim_head ** -.25
        weights = torch.softmax(((q * scale) @ (k * scale).transpose(-1, -2)).float(), dim=-1).to(q.dtype)
        return self.to_out((weights @ v).transpose(1, 2).reshape(b, n, d))


class HandResampler(nn.Module):
    def __init__(self, *, dim: int = 512, depth: int = 2, heads: int = 8, num_queries: int = 8):
        super().__init__()
        self.latents = nn.Parameter(torch.randn(1, num_queries, dim) / dim ** .5)
        self.proj_in = nn.Linear(dim, dim)
        self.proj_out = nn.Linear(dim, dim)
        self.norm_out = nn.LayerNorm(dim)
        self.layers = nn.ModuleList([
            nn.ModuleList([
                PerceiverAttention(dim, heads),
                nn.Sequential(nn.LayerNorm(dim), nn.Linear(dim, dim * 4), nn.GELU(), nn.Linear(dim * 4, dim)),
            ]) for _ in range(depth)
        ])

    def forward(self, x):
        latents = self.latents.expand(x.shape[0], -1, -1)
        x = self.proj_in(x)
        for attention, feed_forward in self.layers:
            latents = latents + attention(x, latents)
            latents = latents + feed_forward(latents)
        return self.norm_out(self.proj_out(latents))

