from dataclasses import dataclass
from typing import Any

import torch

from third_party.v65_face.xdyna import repeat_condition_batch

from ..conditions import _to_preserving_discrete_dtype
from ..control_core import BranchControlResiduals  # noqa: F401 - public re-export
from ..detail import PreparedFaceHandDetailConditioning
from ..face.conditions import PreparedFaceConditioning
from ..hand.conditions import PreparedHandConditioning
from ..reasoning import InternalControlState


@dataclass
class PreparedControlConditioning:
    """Static per-image conditions consumed by every denoising step."""

    geometry_condition: torch.Tensor
    interaction_condition: torch.Tensor
    adapter_tokens: torch.Tensor
    adapter_token_mask: torch.Tensor
    person_count: torch.Tensor
    interaction_valid: torch.Tensor
    control_state: InternalControlState
    detail: PreparedFaceHandDetailConditioning | None = None
    face: PreparedFaceConditioning | None = None
    hand: PreparedHandConditioning | None = None

    @property
    def batch_size(self) -> int:
        return int(self.geometry_condition.shape[0])

    def validate(self) -> "PreparedControlConditioning":
        if self.geometry_condition.ndim != 4:
            raise ValueError("geometry_condition must have shape [B,C,H,W]")
        if self.interaction_condition.shape != self.geometry_condition.shape:
            raise ValueError("interaction_condition must match geometry_condition")
        batch_size = self.batch_size
        if self.adapter_tokens.ndim != 3 or self.adapter_tokens.shape[0] != batch_size:
            raise ValueError("adapter_tokens must have shape [B,M,D]")
        if (
            self.adapter_token_mask.shape != self.adapter_tokens.shape[:2]
            or self.adapter_token_mask.dtype != torch.bool
        ):
            raise ValueError("adapter_token_mask must have shape [B,M] and dtype bool")
        if self.person_count.shape != (batch_size,) or self.person_count.dtype != torch.long:
            raise ValueError("person_count must have shape [B] and dtype int64")
        if (
            self.interaction_valid.shape != (batch_size,)
            or self.interaction_valid.dtype != torch.bool
        ):
            raise ValueError("interaction_valid must have shape [B] and dtype bool")
        if not torch.equal(self.interaction_valid, self.person_count == 2):
            raise ValueError("interaction_valid must identify exactly the dual-person rows")
        if self.control_state.batch_size != batch_size:
            raise ValueError("control_state batch does not match prepared conditions")
        if self.detail is not None:
            self.detail.validate()
            if self.detail.batch_size != batch_size:
                raise ValueError("detail batch does not match prepared conditions")
        if self.face is not None:
            self.face.validate()
            if self.face.batch_size != batch_size:
                raise ValueError("face batch does not match prepared conditions")
        if self.hand is not None:
            self.hand.validate()
            if self.hand.batch_size != batch_size:
                raise ValueError("hand batch does not match prepared conditions")
        invalid = ~self.interaction_valid
        if invalid.any() and torch.count_nonzero(self.interaction_condition[invalid]) != 0:
            raise ValueError("single-person interaction_condition must be exactly zero")
        if torch.count_nonzero(
            self.adapter_tokens * (~self.adapter_token_mask)[..., None]
        ) != 0:
            raise ValueError("masked adapter tokens must be exactly zero")
        return self

    def index_select(self, indices: torch.Tensor) -> "PreparedControlConditioning":
        return type(self)(
            geometry_condition=self.geometry_condition.index_select(0, indices),
            interaction_condition=self.interaction_condition.index_select(0, indices),
            adapter_tokens=self.adapter_tokens.index_select(0, indices),
            adapter_token_mask=self.adapter_token_mask.index_select(0, indices),
            person_count=self.person_count.index_select(0, indices),
            interaction_valid=self.interaction_valid.index_select(0, indices),
            control_state=self.control_state.index_select(indices),
            detail=None if self.detail is None else self.detail.index_select(indices),
            face=None if self.face is None else self.face.index_select(indices),
            hand=None if self.hand is None else self.hand.index_select(indices),
        )

    def expand_to_batch(self, batch_size: int) -> "PreparedControlConditioning":
        if batch_size % self.batch_size:
            raise ValueError("prepared batch cannot be expanded to transformer batch")
        factor = batch_size // self.batch_size
        indices = repeat_condition_batch(
            torch.arange(self.batch_size, device=self.geometry_condition.device),
            factor,
        )
        return self.index_select(indices).validate()

    def to(self, *args, **kwargs) -> "PreparedControlConditioning":
        return type(self)(
            geometry_condition=self.geometry_condition.to(*args, **kwargs),
            interaction_condition=self.interaction_condition.to(*args, **kwargs),
            adapter_tokens=self.adapter_tokens.to(*args, **kwargs),
            adapter_token_mask=_to_preserving_discrete_dtype(
                self.adapter_token_mask, *args, **kwargs
            ),
            person_count=_to_preserving_discrete_dtype(
                self.person_count, *args, **kwargs
            ),
            interaction_valid=_to_preserving_discrete_dtype(
                self.interaction_valid, *args, **kwargs
            ),
            control_state=self.control_state.to(*args, **kwargs),
            detail=None if self.detail is None else self.detail.to(*args, **kwargs),
            face=None if self.face is None else self.face.to(*args, **kwargs),
            hand=None if self.hand is None else self.hand.to(*args, **kwargs),
        )


@dataclass
class DeepGenControlOutput:
    """Six aligned residual groups and lightweight runtime diagnostics."""

    block_controlnet_hidden_states: tuple[torch.Tensor, ...]
    diagnostics: dict[str, Any]

    def validate(self) -> "DeepGenControlOutput":
        if len(self.block_controlnet_hidden_states) != 6:
            raise ValueError("DeepGen control output must contain six residuals")
        expected = None
        for index, residual in enumerate(self.block_controlnet_hidden_states):
            if residual.ndim != 3:
                raise ValueError(f"control residual {index} must have shape [B,N,D]")
            if expected is None:
                expected = residual.shape
            elif residual.shape != expected:
                raise ValueError("all DeepGen residuals must have the same shape")
        return self

from __future__ import annotations

import math
from dataclasses import dataclass
from typing import Literal

import torch
import torch.nn as nn

from third_party.v65_face.xdyna import add_optional_face_residual

from .outputs import BranchControlResiduals


@dataclass(frozen=True)
class StrengthScheduleConfig:
    curve: Literal["constant", "linear", "cosine"] = "constant"
    start_progress: float = 0.0
    end_progress: float = 1.0
    start_multiplier: float = 1.0
    end_multiplier: float = 1.0

    def __post_init__(self) -> None:
        if self.curve not in {"constant", "linear", "cosine"}:
            raise ValueError("curve must be constant, linear, or cosine")
        if not 0.0 <= self.start_progress <= self.end_progress <= 1.0:
            raise ValueError("schedule progress window must lie within [0,1]")
        if self.start_progress == self.end_progress:
            raise ValueError("schedule progress window must have positive width")

    def multiplier(self, progress: float | torch.Tensor) -> float | torch.Tensor:
        if torch.is_tensor(progress):
            if progress.ndim > 1 or not progress.is_floating_point():
                raise ValueError("denoise progress tensor must be scalar or have shape [B]")
            if not torch.isfinite(progress).all():
                raise ValueError("denoise progress tensor must contain only finite values")
            if torch.any((progress < 0) | (progress > 1)):
                raise ValueError("denoise progress must lie within [0,1]")
            active = (progress >= self.start_progress) & (progress <= self.end_progress)
            if self.curve == "constant":
                value = torch.full_like(progress, self.start_multiplier)
            else:
                position = (progress - self.start_progress) / (
                    self.end_progress - self.start_progress
                )
                if self.curve == "cosine":
                    position = 0.5 * (1.0 - torch.cos(torch.pi * position))
                value = self.start_multiplier + position * (
                    self.end_multiplier - self.start_multiplier
                )
            return torch.where(active, value, torch.zeros_like(value))
        progress = float(progress)
        if not 0.0 <= progress <= 1.0:
            raise ValueError("denoise progress must lie within [0,1]")
        if progress < self.start_progress or progress > self.end_progress:
            return 0.0
        if self.curve == "constant":
            return float(self.start_multiplier)
        position = (progress - self.start_progress) / (
            self.end_progress - self.start_progress
        )
        if self.curve == "cosine":
            position = 0.5 * (1.0 - math.cos(math.pi * position))
        return float(self.start_multiplier + position * (self.end_multiplier - self.start_multiplier))


class ControlStrengthController(nn.Module):
    """Apply positive per-group gates and denoising schedules per branch."""

    def __init__(
        self,
        *,
        num_control_groups: int = 6,
        geometry_schedule: StrengthScheduleConfig | None = None,
        interaction_schedule: StrengthScheduleConfig | None = None,
        detail_schedule: StrengthScheduleConfig | None = None,
        face_schedule: StrengthScheduleConfig | None = None,
        face_texture_schedule: StrengthScheduleConfig | None = None,
        enable_face: bool = False,
        enable_hand: bool = False,
    ) -> None:
        super().__init__()
        if num_control_groups != 6:
            raise ValueError("DeepGen V6.3 defines exactly six control groups")
        self.num_control_groups = num_control_groups
        self.geometry_schedule = geometry_schedule or StrengthScheduleConfig()
        self.interaction_schedule = interaction_schedule or StrengthScheduleConfig()
        self.detail_schedule = detail_schedule or StrengthScheduleConfig(
            curve="cosine",
            start_progress=0.35,
            end_progress=1.0,
            start_multiplier=0.0,
            end_multiplier=1.0,
        )
        self.face_schedule = face_schedule or StrengthScheduleConfig(
            curve="cosine",
            start_progress=0.35,
            end_progress=1.0,
            start_multiplier=0.0,
            end_multiplier=1.0,
        )
        self.face_texture_schedule = face_texture_schedule or StrengthScheduleConfig(
            curve="cosine",
            start_progress=0.65,
            end_progress=1.0,
            start_multiplier=0.0,
            end_multiplier=1.0,
        )
        self.hand_schedule = StrengthScheduleConfig(curve="cosine", start_progress=0.0, end_progress=1.0, start_multiplier=0.15, end_multiplier=1.0)
        self.hand_texture_schedule = StrengthScheduleConfig(curve="cosine", start_progress=0.65, end_progress=1.0, start_multiplier=0.0, end_multiplier=1.0)
        self.geometry_log_group_scale = nn.Parameter(torch.zeros(num_control_groups))
        self.interaction_log_group_scale = nn.Parameter(torch.zeros(num_control_groups))
        self.detail_log_group_scale = nn.Parameter(torch.zeros(num_control_groups))
        if enable_face:
            self.face_log_group_scale = nn.Parameter(torch.zeros(num_control_groups))
            self.register_buffer(
                "face_group_prior",
                torch.tensor([0.1, 0.2, 0.5, 0.8, 1.0, 1.0]),
            )
        else:
            self.register_parameter("face_log_group_scale", None)
            self.register_buffer("face_group_prior", None)
        if enable_hand:
            self.hand_log_group_scale = nn.Parameter(torch.zeros(num_control_groups))
            self.register_buffer("hand_group_prior", torch.tensor([0.1, 0.2, 0.4, 0.7, 1.0, 1.0]))
        else:
            self.register_parameter("hand_log_group_scale", None)
            self.register_buffer("hand_group_prior", None)

    @staticmethod
    def _sample_gate(value, reference: torch.Tensor) -> torch.Tensor | float:
        if not torch.is_tensor(value):
            return float(value)
        value = value.to(device=reference.device, dtype=reference.dtype)
        if value.ndim == 0:
            return value
        if value.shape != (reference.shape[0],):
            raise ValueError("per-sample strength or progress must have shape [B]")
        return value[:, None, None]

    def enable_v66_hand(self) -> None:
        if self.hand_log_group_scale is None:
            self.hand_log_group_scale = nn.Parameter(torch.zeros(self.num_control_groups))
            self.hand_group_prior = torch.tensor([0.1, 0.2, 0.4, 0.7, 1.0, 1.0])

    def forward(
        self,
        residuals: BranchControlResiduals,
        *,
        denoise_progress: float | torch.Tensor,
        geometry_strength: float | torch.Tensor = 1.0,
        interaction_strength: float | torch.Tensor = 0.8,
        detail_strength: float | torch.Tensor = 1.0,
        face_strength: float | torch.Tensor = 1.0,
        hand_strength: float | torch.Tensor = 1.0,
        detail_region_masks: torch.Tensor | None = None,
        hand_mode: Literal["legacy", "v66", "off"] = "legacy",
    ) -> tuple[tuple[torch.Tensor, ...], dict[str, object]]:
        residuals.validate()
        if hand_mode not in {"legacy", "v66", "off"}:
            raise ValueError("hand_mode must be legacy, v66 or off")
        geo_schedule = self.geometry_schedule.multiplier(denoise_progress)
        int_schedule = self.interaction_schedule.multiplier(denoise_progress)
        detail_schedule = self.detail_schedule.multiplier(denoise_progress)
        face_schedule = self.face_schedule.multiplier(denoise_progress)
        face_texture_schedule = self.face_texture_schedule.multiplier(
            denoise_progress
        )
        geo_gates = self.geometry_log_group_scale.exp()
        int_gates = self.interaction_log_group_scale.exp()
        detail_gates = self.detail_log_group_scale.exp()
        reference = residuals.geometry[0]
        if self.face_log_group_scale is None or self.face_group_prior is None:
            face_gates = reference.new_zeros(self.num_control_groups)
        else:
            face_gates = self.face_log_group_scale.exp() * self.face_group_prior
        if detail_region_masks is not None:
            expected = (reference.shape[0], 2, 3, *residuals.target_token_hw)
            if tuple(detail_region_masks.shape) != expected:
                raise ValueError(f"detail_region_masks must have shape {expected}")
            if not detail_region_masks.is_floating_point():
                raise ValueError("detail_region_masks must use a floating dtype")
            if detail_region_masks.device != reference.device:
                raise ValueError("detail_region_masks must be on the residual device")
            if not torch.isfinite(detail_region_masks).all():
                raise ValueError("detail_region_masks must contain only finite values")
            if torch.any((detail_region_masks < 0) | (detail_region_masks > 1)):
                raise ValueError("detail_region_masks must be bounded in [0,1]")
        geo_schedule = self._sample_gate(geo_schedule, reference)
        int_schedule = self._sample_gate(int_schedule, reference)
        detail_schedule = self._sample_gate(detail_schedule, reference)
        face_schedule = self._sample_gate(face_schedule, reference)
        geometry_strength = self._sample_gate(geometry_strength, reference)
        interaction_strength = self._sample_gate(interaction_strength, reference)
        output = tuple(
            geometry
            * (geometry_strength * geo_schedule * geo_gates[index])
            + interaction
            * (interaction_strength * int_schedule * int_gates[index])
            for index, (geometry, interaction) in enumerate(
                zip(residuals.geometry, residuals.interaction)
            )
        )
        detail_strength = self._sample_gate(detail_strength, reference)
        face_strength = self._sample_gate(face_strength, reference)
        hand_strength = self._sample_gate(hand_strength, reference)
        if torch.is_tensor(detail_strength):
            zero_detail_strength = bool(torch.count_nonzero(detail_strength) == 0)
        else:
            zero_detail_strength = float(detail_strength) == 0.0
        detail_is_disabled = residuals.detail is None or zero_detail_strength or hand_mode != "legacy"
        if not detail_is_disabled:
            if detail_region_masks is None:
                raise ValueError("detail_region_masks are required when detail residuals are active")
            face = detail_region_masks[:, :, 0].amax(dim=1).flatten(1)
            hands = detail_region_masks[:, :, 1:].amax(dim=(1, 2)).flatten(1)
            face_gate = face[:, :, None] * face_strength
            hand_gate = hands[:, :, None] * hand_strength
            region_gate = torch.maximum(face_gate, hand_gate)
            output = tuple(
                current + detail * region_gate * detail_strength * detail_schedule * detail_gates[index]
                for index, (current, detail) in enumerate(zip(output, residuals.detail))
            )
        if residuals.face is not None and not zero_detail_strength:
            if self.face_log_group_scale is None:
                raise ValueError("face residuals require a face-enabled strength controller")
            output = tuple(
                add_optional_face_residual(
                    current,
                    face
                    * detail_strength
                    * face_strength
                    * face_schedule
                    * face_gates[index],
                )
                for index, (current, face) in enumerate(zip(output, residuals.face))
            )
        if hand_mode == "v66" and residuals.hand is not None and not zero_detail_strength:
            if self.hand_log_group_scale is None or self.hand_group_prior is None:
                raise ValueError("v66 hand residuals require a hand-enabled controller")
            hand_gates = self.hand_log_group_scale.exp() * self.hand_group_prior
            hand_schedule = self._sample_gate(self.hand_schedule.multiplier(denoise_progress), reference)
            output = tuple(current + hand * detail_strength * hand_strength * hand_schedule * hand_gates[index]
                           for index, (current, hand) in enumerate(zip(output, residuals.hand)))

        def diagnostic(value):
            if torch.is_tensor(value):
                if value.ndim == 0:
                    return float(value.detach().cpu())
                flat = value.detach().reshape(value.shape[0], -1)[:, 0].cpu().tolist()
                return flat[0] if len(flat) == 1 else flat
            return float(value)
        diagnostics: dict[str, object] = {
            "denoise_progress": diagnostic(denoise_progress),
            "geometry_schedule_multiplier": diagnostic(geo_schedule),
            "interaction_schedule_multiplier": diagnostic(int_schedule),
            "detail_schedule_multiplier": diagnostic(detail_schedule),
            "face_schedule_multiplier": diagnostic(face_schedule),
            "face_texture_schedule_multiplier": diagnostic(face_texture_schedule),
            "geometry_group_scales": geo_gates.detach().cpu().tolist(),
            "interaction_group_scales": int_gates.detach().cpu().tolist(),
            "detail_group_scales": detail_gates.detach().cpu().tolist(),
            "face_group_scales": face_gates.detach().cpu().tolist(),
            "hand_mode": hand_mode,
            "hand_group_scales": None if self.hand_log_group_scale is None else (self.hand_log_group_scale.exp() * self.hand_group_prior).detach().cpu().tolist(),
        }
        return output, diagnostics

"""Native Qwen-Image-2.1 image/latent I/O for the full V6 migration.

Copied from the existing Qwen runtime only; no simplified control modules are used."""

from __future__ import annotations

import hashlib
import os
from collections.abc import Sequence
from pathlib import Path

import torch
import torch.nn.functional as F
from PIL import Image
from torchvision.transforms.functional import to_pil_image


MODEL_REVISION = "790c92633540aa0cb11d9abf19eb46d861714758"
PROMPT = "Change the person pose to match the target pose. Preserve identity, clothing, and background."
RESOLUTION = 512


def dataset_image_to_pil(image: torch.Tensor) -> Image.Image:
    """Convert the dataset's normalized RGB tensor into an opaque RGB image."""
    return to_pil_image(((image.detach().float().cpu() + 1) * 0.5).clamp(0, 1))


class Qwen21IPERCache:
    def __init__(self, root: str | Path, *, prompt: str = PROMPT, resolution: int = RESOLUTION) -> None:
        if resolution not in (512, 1024):
            raise ValueError('resolution must be 512 or 1024')
        self.root = Path(root)
        self.root.mkdir(parents=True, exist_ok=True)
        self.prompt = prompt
        self.resolution = resolution

    def _path(self, image: Image.Image, kind: str, *, prompt: str | None = None) -> Path:
        resolved_prompt = self.prompt if prompt is None or kind == "target" else prompt
        digest = hashlib.sha256()
        digest.update((MODEL_REVISION + resolved_prompt + kind + str(self.resolution)).encode())
        digest.update(image.convert("RGB").tobytes())
        return self.root / f"{kind}_{digest.hexdigest()[:24]}.pt"

    @staticmethod
    def _store(path: Path, value: object) -> None:
        temporary = path.with_name(f"{path.name}.{os.getpid()}.tmp")
        torch.save(value, temporary)
        temporary.replace(path)

    def _vae_input(self, pipe, image: Image.Image, device: torch.device) -> torch.Tensor:
        rgba = image.convert("RGBA")
        return pipe.image_processor.preprocess(
            rgba, width=self.resolution, height=self.resolution
        ).unsqueeze(2).to(device=device, dtype=pipe.vae.dtype)

    def source(self, pipe, image: Image.Image, *, prompt: str | None = None) -> dict[str, torch.Tensor]:
        resolved_prompt = self.prompt if prompt is None else prompt
        path = self._path(image, "source", prompt=resolved_prompt)
        if path.exists():
            return torch.load(path, map_location="cpu", weights_only=True)
        device = next(pipe.text_encoder.parameters()).device
        if device.type == "cpu":
            raise RuntimeError(f"missing source cache {path.name}; text encoder must be on GPU for precompute")
        with torch.inference_mode():
            rgba = image.convert("RGBA")
            vlm_image = pipe.image_processor.resize(rgba, width=self.resolution, height=self.resolution)
            prompt_embeds, prompt_mask, image_mask = pipe.encode_prompt(
                resolved_prompt, image=[vlm_image], device=device
            )
            vae_image = self._vae_input(pipe, rgba, device)
            latent = pipe._encode_vae_image(vae_image, torch.Generator(device=device).manual_seed(0))
            latent = latent.flatten(3).squeeze(2).transpose(1, 2)
            if prompt_mask is None:
                prompt_mask = torch.ones(prompt_embeds.shape[:2], device=device, dtype=torch.bool)
            entry = {
                "prompt_embeds": prompt_embeds.cpu().contiguous(),
                "prompt_mask": prompt_mask.cpu().bool().contiguous(),
                "image_mask": image_mask.cpu().bool().contiguous(),
                "reference_latent": latent.cpu().contiguous(),
            }
        self._store(path, entry)
        return entry

    def target(self, pipe, image: Image.Image) -> torch.Tensor:
        path = self._path(image, "target")
        if path.exists():
            return torch.load(path, map_location="cpu", weights_only=True)
        device = next(pipe.vae.parameters()).device
        if device.type == "cpu":
            raise RuntimeError(f"missing target cache {path.name}; VAE must be on GPU for precompute")
        with torch.inference_mode():
            latent = pipe._encode_vae_image(
                self._vae_input(pipe, image, device), torch.Generator(device=device).manual_seed(0)
            )
            latent = latent.flatten(3).squeeze(2).transpose(1, 2).cpu().contiguous()
        self._store(path, latent)
        return latent

    def pair(
        self, pipe, batch: dict, device: torch.device, *, prompts: Sequence[str] | None = None
    ) -> dict[str, torch.Tensor]:
        batch_size = batch["src_image"].shape[0]
        if prompts is None:
            conditions = [self.source(pipe, dataset_image_to_pil(batch["src_image"][index])) for index in range(batch_size)]
        else:
            if len(prompts) != batch_size:
                raise ValueError(f"prompts length {len(prompts)} does not match batch size {batch_size}")
            conditions = [
                self.source(pipe, dataset_image_to_pil(batch["src_image"][index]), prompt=prompts[index])
                for index in range(batch_size)
            ]
        targets = [self.target(pipe, dataset_image_to_pil(batch["tgt_image"][index])) for index in range(batch_size)]
        target_latent = torch.cat(targets, dim=0)
        tokens = target_latent.shape[1]
        if tokens != (self.resolution // 16) ** 2 or tokens % 4:
            raise ValueError(f"unexpected Qwen21 target token count: {tokens}")
        max_prompt = max(condition["prompt_embeds"].shape[1] for condition in conditions)
        prompt_embeds = torch.cat([
            F.pad(condition["prompt_embeds"], (0, 0, 0, max_prompt - condition["prompt_embeds"].shape[1]))
            for condition in conditions
        ], dim=0)
        prompt_mask = torch.cat([
            F.pad(condition["prompt_mask"], (0, max_prompt - condition["prompt_mask"].shape[1]), value=False)
            for condition in conditions
        ], dim=0)
        image_mask = torch.cat([
            torch.cat((
                F.pad(condition["image_mask"], (0, max_prompt - condition["image_mask"].shape[1]), value=False),
                torch.ones(1, tokens // 4, dtype=torch.bool),
            ), dim=1) for condition in conditions
        ], dim=0)
        return {
            "source_latent": torch.cat([condition["reference_latent"] for condition in conditions], dim=0).to(device),
            "target_latent": target_latent.to(device),
            "prompt_embeds": prompt_embeds.to(device),
            "prompt_mask": prompt_mask.to(device),
            "img_mask": image_mask.to(device),
            "resolution": self.resolution,
        }


def transformer_inputs(pair: dict[str, torch.Tensor], noisy_target: torch.Tensor, sigma: torch.Tensor):
    grid = pair['resolution'] // 16
    if noisy_target.shape[1] != grid * grid:
        raise ValueError('target latent token count does not match resolution')
    return {
        "hidden_states": torch.cat((pair["source_latent"], noisy_target), dim=1),
        "timestep": sigma,
        "encoder_hidden_states": pair["prompt_embeds"],
        "encoder_hidden_states_mask": pair["prompt_mask"],
        "img_shapes": [[(1, grid, grid)] * 2 for _ in range(noisy_target.shape[0])],
        "img_mask": pair["img_mask"],
        "return_dict": False,
    }

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class AdapterReasoningConfig:
    """Widths and attention layout for Adapter-internal reasoning."""

    condition_dim: int = 256
    hidden_dim: int = 512
    reasoning_downsample_factor: int = 2

    global_attention_heads: int = 8
    global_attention_layers: int = 1
    cross_person_heads: int = 8
    cross_person_layers: int = 2
    contact_attention_heads: int = 8
    contact_attention_layers: int = 1

    ffn_ratio: int = 4
    dropout: float = 0.0
    contact_gate_init: float = -4.0

    def __post_init__(self) -> None:
        if self.condition_dim != 256:
            raise ValueError("ConditionBundle fixes condition_dim at 256")
        if self.hidden_dim <= 0:
            raise ValueError("hidden_dim must be positive")
        if self.reasoning_downsample_factor != 2:
            raise ValueError("reasoning V1 supports downsample factor 2 only")
        for name in (
            "global_attention_heads",
            "cross_person_heads",
            "contact_attention_heads",
        ):
            heads = getattr(self, name)
            if heads <= 0 or self.hidden_dim % heads:
                raise ValueError(f"hidden_dim must be divisible by {name}")
        for name in (
            "global_attention_layers",
            "cross_person_layers",
            "contact_attention_layers",
            "ffn_ratio",
        ):
            if getattr(self, name) <= 0:
                raise ValueError(f"{name} must be positive")
        if not 0 <= self.dropout < 1:
            raise ValueError("dropout must be in [0, 1)")

from __future__ import annotations

from dataclasses import dataclass, fields

import torch

from ..conditions import _to_preserving_discrete_dtype


@dataclass
class InternalControlState:
    """Batch-safe output of Adapter reasoning before DeepGen projection."""

    geometry_feature: torch.Tensor
    geometry_highres: torch.Tensor
    interaction_feature: torch.Tensor
    interaction_highres: torch.Tensor
    person_tokens: torch.Tensor
    person_token_mask: torch.Tensor
    person_valid: torch.Tensor
    person_count: torch.Tensor
    interaction_valid: torch.Tensor

    @property
    def batch_size(self) -> int:
        return int(self.geometry_feature.shape[0])

    def validate(self) -> "InternalControlState":
        if self.geometry_feature.ndim != 4:
            raise ValueError("geometry_feature must have shape [B,C,H,W]")
        batch_size, channels, height, width = self.geometry_feature.shape
        expected_high = (batch_size, channels, height * 2, width * 2)
        if tuple(self.geometry_highres.shape) != expected_high:
            raise ValueError(f"geometry_highres must have shape {expected_high}")
        if tuple(self.interaction_feature.shape) != tuple(self.geometry_feature.shape):
            raise ValueError("interaction_feature must match geometry_feature")
        if tuple(self.interaction_highres.shape) != expected_high:
            raise ValueError("interaction_highres must match geometry_highres")
        token_shape = (batch_size, 2, height * width, channels)
        mask_shape = token_shape[:-1]
        if tuple(self.person_tokens.shape) != token_shape:
            raise ValueError(f"person_tokens must have shape {token_shape}")
        if tuple(self.person_token_mask.shape) != mask_shape or self.person_token_mask.dtype != torch.bool:
            raise ValueError(f"person_token_mask must have shape {mask_shape} and dtype bool")
        if tuple(self.person_valid.shape) != (batch_size, 2) or self.person_valid.dtype != torch.bool:
            raise ValueError("person_valid must have shape [B,2] and dtype bool")
        if tuple(self.person_count.shape) != (batch_size,) or self.person_count.dtype != torch.long:
            raise ValueError("person_count must have shape [B] and dtype int64")
        if tuple(self.interaction_valid.shape) != (batch_size,) or self.interaction_valid.dtype != torch.bool:
            raise ValueError("interaction_valid must have shape [B] and dtype bool")
        if not torch.equal(self.person_count, self.person_valid.sum(dim=1).long()):
            raise ValueError("person_count must equal person_valid.sum(dim=1)")
        if not torch.equal(self.interaction_valid, self.person_count == 2):
            raise ValueError("interaction_valid must identify exactly the dual-person rows")
        if torch.any(self.person_token_mask & ~self.person_valid[..., None]):
            raise ValueError("invalid person slots cannot contain valid tokens")

        single = ~self.interaction_valid
        if single.any():
            if torch.count_nonzero(self.person_tokens[single, 1]) != 0:
                raise ValueError("single-person rows must have zero Person-B tokens")
            if self.person_token_mask[single, 1].any():
                raise ValueError("single-person rows must mask every Person-B token")
            if torch.count_nonzero(self.interaction_feature[single]) != 0:
                raise ValueError("single-person rows must have zero interaction_feature")
            if torch.count_nonzero(self.interaction_highres[single]) != 0:
                raise ValueError("single-person rows must have zero interaction_highres")
        return self

    def index_select(self, indices: torch.Tensor) -> "InternalControlState":
        return type(self)(
            **{
                item.name: getattr(self, item.name).index_select(0, indices)
                for item in fields(self)
            }
        )

    def to(self, *args, **kwargs) -> "InternalControlState":
        return type(self)(
            **{
                item.name: _to_preserving_discrete_dtype(
                    getattr(self, item.name), *args, **kwargs
                )
                for item in fields(self)
            }
        )

from __future__ import annotations

from collections.abc import Mapping
from typing import Any

import torch
import torch.nn as nn


ARCHITECTURE_VERSION = "v6.6"
DETAIL_SCHEMA_VERSION = "1"
PREPROCESSING_SCHEMA_VERSION = "1"
FACE_SCHEMA_VERSION = "1"
BRANCH_NAMES = ["geometry", "interaction", "hand", "face"]
V66_BRANCH_NAMES = ["geometry", "interaction", "legacy_hand", "face", "hand"]
HAND_SCHEMA_VERSION = "1"
V64_BRANCH_NAMES = ["geometry", "interaction", "detail"]

DETAIL_ONLY_PREFIXES = (
    "detail_preparer.",
    "control_interface.control_core.detail_branch.",
    "control_interface.strength_controller.detail_log_group_scale",
)

FACE_ONLY_PREFIXES = (
    "face_preparer.",
    "control_interface.face_adapter.",
    "control_interface.strength_controller.face_",
)
HAND_ONLY_PREFIXES = (
    "hand_preparer.",
    "control_interface.hand_adapter.",
    "control_interface.strength_controller.hand_log_group_scale",
    "control_interface.strength_controller.hand_group_prior",
)


def _has_prefix(key: str, prefixes: tuple[str, ...]) -> bool:
    return any(key.startswith(prefix) for prefix in prefixes)


def _adapter_state(checkpoint: Mapping[str, Any]) -> Mapping[str, torch.Tensor]:
    state = checkpoint.get("adapter_state_dict", checkpoint)
    if not isinstance(state, Mapping):
        raise TypeError("checkpoint adapter_state_dict must be a mapping")
    return state


def _preflight_state(
    model: nn.Module,
    state: Mapping[str, Any],
    expected_keys: set[str],
) -> None:
    provided_keys = set(state)
    unexpected = sorted(provided_keys - expected_keys)
    missing = sorted(expected_keys - provided_keys)
    if unexpected:
        raise RuntimeError(f"unexpected checkpoint keys: {unexpected}")
    if missing:
        raise RuntimeError(f"checkpoint is missing keys: {missing}")
    expected_state = model.state_dict()
    for key in sorted(expected_keys):
        value = state[key]
        expected = expected_state[key]
        if not torch.is_tensor(value):
            raise RuntimeError(f"checkpoint value for {key!r} must be a tensor")
        if value.shape != expected.shape:
            raise RuntimeError(
                f"checkpoint tensor {key!r} has shape {tuple(value.shape)}; "
                f"expected {tuple(expected.shape)}"
            )
        if value.dtype != expected.dtype:
            raise RuntimeError(
                f"checkpoint tensor {key!r} has dtype {value.dtype}; "
                f"expected {expected.dtype}"
            )
        if value.layout != torch.strided or value.layout != expected.layout:
            raise RuntimeError(
                f"checkpoint tensor {key!r} has layout {value.layout}; "
                f"expected strided layout {expected.layout}"
            )


def _transactional_load(
    model: nn.Module,
    state: Mapping[str, torch.Tensor],
    *,
    strict: bool,
    after_load=None,
):
    snapshot = {
        key: value.detach().clone() for key, value in model.state_dict().items()
    }
    try:
        result = model.load_state_dict(state, strict=strict)
        if after_load is not None:
            after_load()
        return result
    except Exception:
        current = model.state_dict()
        with torch.no_grad():
            for key, value in snapshot.items():
                current[key].copy_(value)
        raise


def load_v63_checkpoint(
    model: nn.Module, checkpoint: Mapping[str, Any]
) -> torch.nn.modules.module._IncompatibleKeys:
    """Load V6.3 adapter weights while allowing only newly introduced detail keys."""

    if "optimizer_state_dict" in checkpoint:
        raise RuntimeError(
            "V6.3 optimizer state is incompatible with V6.4 and must not be restored"
        )
    metadata = checkpoint.get("metadata")
    if isinstance(metadata, Mapping) and metadata.get("architecture_version") in {
        "v6.4",
        "v6.5",
        "v6.6",
    }:
        version = metadata.get("architecture_version")
        raise RuntimeError(f"V6.3 loader rejects {version.upper()} metadata")
    state = _adapter_state(checkpoint)
    detail_keys = sorted(
        key
        for key in state
        if _has_prefix(key, DETAIL_ONLY_PREFIXES)
    )
    if detail_keys:
        raise RuntimeError(f"V6.3 checkpoint contains detail-only keys: {detail_keys}")
    face_keys = sorted(
        key for key in state if _has_prefix(key, FACE_ONLY_PREFIXES)
    )
    if face_keys:
        raise RuntimeError(f"V6.3 checkpoint contains face-only keys: {face_keys}")
    hand_keys = sorted(key for key in state if _has_prefix(key, HAND_ONLY_PREFIXES))
    if hand_keys:
        raise RuntimeError(f"V6.3 checkpoint contains hand-only keys: {hand_keys}")
    model_keys = set(model.state_dict())
    expected_keys = {
        key
        for key in model_keys
        if not _has_prefix(key, DETAIL_ONLY_PREFIXES + FACE_ONLY_PREFIXES + HAND_ONLY_PREFIXES)
    }
    _preflight_state(model, state, expected_keys)
    detail_branch = model.get_submodule("control_interface.control_core.detail_branch")

    def rezero_new_heads() -> None:
        with torch.no_grad():
            for head in detail_branch.zero_heads:
                nn.init.zeros_(head.weight)
                if head.bias is not None:
                    nn.init.zeros_(head.bias)
        _rezero_face_heads(model)
        _rezero_hand_heads(model)

    result = _transactional_load(
        model,
        state,
        strict=False,
        after_load=rezero_new_heads,
    )
    return result


def v64_checkpoint_metadata() -> dict[str, object]:
    return {
        "architecture_version": "v6.4",
        "branch_names": list(V64_BRANCH_NAMES),
        "detail_schema_version": DETAIL_SCHEMA_VERSION,
        "preprocessing_schema_version": PREPROCESSING_SCHEMA_VERSION,
    }


def build_v64_checkpoint(
    model: nn.Module, **extra: Any
) -> dict[str, Any]:
    reserved = {"metadata", "adapter_state_dict"} & set(extra)
    if reserved:
        raise ValueError(f"checkpoint extra keys are reserved: {sorted(reserved)}")
    checkpoint = {
        "adapter_state_dict": {
            key: value.detach().clone()
            for key, value in model.state_dict().items()
            if not _has_prefix(key, FACE_ONLY_PREFIXES + HAND_ONLY_PREFIXES)
        },
        "metadata": v64_checkpoint_metadata(),
    }
    checkpoint.update(extra)
    return checkpoint


def _rezero_face_heads(model: nn.Module) -> None:
    interface = getattr(model, "control_interface", None)
    face_adapter = getattr(interface, "face_adapter", None)
    if face_adapter is None:
        return
    with torch.no_grad():
        for head in face_adapter.zero_heads:
            nn.init.zeros_(head.weight)
            if head.bias is not None:
                nn.init.zeros_(head.bias)


def _rezero_hand_heads(model: nn.Module) -> None:
    interface = getattr(model, "control_interface", None)
    adapter = getattr(interface, "hand_adapter", None)
    if adapter is not None:
        with torch.no_grad():
            for head in adapter.zero_heads:
                nn.init.zeros_(head.weight)
                if head.bias is not None:
                    nn.init.zeros_(head.bias)


def load_v64_checkpoint(
    model: nn.Module, checkpoint: Mapping[str, Any]
) -> torch.nn.modules.module._IncompatibleKeys:
    if "optimizer_state_dict" in checkpoint:
        raise RuntimeError(
            "V6.4 optimizer state is incompatible with V6.5 and must not be restored"
        )
    metadata = checkpoint.get("metadata")
    if not isinstance(metadata, Mapping):
        raise RuntimeError("V6.4 checkpoint metadata is missing")
    expected = v64_checkpoint_metadata()
    for key, value in expected.items():
        if metadata.get(key) != value:
            raise RuntimeError(f"invalid V6.4 checkpoint metadata field {key!r}")
    state = _adapter_state(checkpoint)
    expected_keys = {
        key for key in model.state_dict() if not _has_prefix(key, FACE_ONLY_PREFIXES + HAND_ONLY_PREFIXES)
    }
    _preflight_state(model, state, expected_keys)
    return _transactional_load(
        model,
        state,
        strict=expected_keys == set(model.state_dict()),
        after_load=lambda: (_rezero_face_heads(model), _rezero_hand_heads(model)),
    )


def v65_checkpoint_metadata(
    *, feature_cache_fingerprint: str | None = None
) -> dict[str, object]:
    return {
        "architecture_version": "v6.5",
        "branch_names": list(BRANCH_NAMES),
        "detail_schema_version": DETAIL_SCHEMA_VERSION,
        "face_schema_version": FACE_SCHEMA_VERSION,
        "preprocessing_schema_version": PREPROCESSING_SCHEMA_VERSION,
        "feature_cache_fingerprint": feature_cache_fingerprint,
    }


def build_v65_checkpoint(
    model: nn.Module,
    *,
    feature_cache_fingerprint: str | None = None,
    **extra: Any,
) -> dict[str, Any]:
    reserved = {"metadata", "adapter_state_dict"} & set(extra)
    if reserved:
        raise ValueError(f"checkpoint extra keys are reserved: {sorted(reserved)}")
    checkpoint = {
        "adapter_state_dict": {
            key: value.detach().clone() for key, value in model.state_dict().items()
            if not _has_prefix(key, HAND_ONLY_PREFIXES)
        },
        "metadata": v65_checkpoint_metadata(
            feature_cache_fingerprint=feature_cache_fingerprint
        ),
    }
    checkpoint.update(extra)
    return checkpoint


def load_v65_checkpoint(model: nn.Module, checkpoint: Mapping[str, Any]) -> None:
    metadata = checkpoint.get("metadata")
    if not isinstance(metadata, Mapping):
        raise RuntimeError("V6.5 checkpoint metadata is missing")
    expected = v65_checkpoint_metadata(
        feature_cache_fingerprint=metadata.get("feature_cache_fingerprint")
    )
    for key, value in expected.items():
        if metadata.get(key) != value:
            raise RuntimeError(f"invalid V6.5 checkpoint metadata field {key!r}")
    state = _adapter_state(checkpoint)
    expected_keys = {key for key in model.state_dict() if not _has_prefix(key, HAND_ONLY_PREFIXES)}
    _preflight_state(model, state, expected_keys)
    _transactional_load(model, state, strict=expected_keys == set(model.state_dict()), after_load=lambda: _rezero_hand_heads(model))


def v66_checkpoint_metadata(*, feature_cache_fingerprint: str | None = None, hand_cache_fingerprint: str | None = None) -> dict[str, object]:
    return {
        "architecture_version": ARCHITECTURE_VERSION,
        "branch_names": list(V66_BRANCH_NAMES),
        "detail_schema_version": DETAIL_SCHEMA_VERSION,
        "face_schema_version": FACE_SCHEMA_VERSION,
        "hand_schema_version": HAND_SCHEMA_VERSION,
        "preprocessing_schema_version": PREPROCESSING_SCHEMA_VERSION,
        "feature_cache_fingerprint": feature_cache_fingerprint,
        "hand_cache_fingerprint": hand_cache_fingerprint,
    }


def build_v66_checkpoint(model: nn.Module, *, feature_cache_fingerprint: str | None = None, hand_cache_fingerprint: str | None = None, **extra: Any) -> dict[str, Any]:
    reserved = {"metadata", "adapter_state_dict"} & set(extra)
    if reserved:
        raise ValueError(f"checkpoint extra keys are reserved: {sorted(reserved)}")
    result = {"adapter_state_dict": {key: value.detach().clone() for key, value in model.state_dict().items()},
              "metadata": v66_checkpoint_metadata(feature_cache_fingerprint=feature_cache_fingerprint, hand_cache_fingerprint=hand_cache_fingerprint)}
    result.update(extra)
    return result


def load_v66_checkpoint(model: nn.Module, checkpoint: Mapping[str, Any]) -> None:
    metadata = checkpoint.get("metadata")
    if not isinstance(metadata, Mapping):
        raise RuntimeError("V6.6 checkpoint metadata is missing")
    expected = v66_checkpoint_metadata(feature_cache_fingerprint=metadata.get("feature_cache_fingerprint"), hand_cache_fingerprint=metadata.get("hand_cache_fingerprint"))
    for key, value in expected.items():
        if metadata.get(key) != value:
            raise RuntimeError(f"invalid V6.6 checkpoint metadata field {key!r}")
    state = _adapter_state(checkpoint)
    _preflight_state(model, state, set(model.state_dict()))
    _transactional_load(model, state, strict=True)


def freeze_for_hand_training(model: nn.Module, *, warmup: bool = False) -> tuple[nn.Parameter, ...]:
    """V6.6-only optimizer selection; warmup trains heads and group gate."""
    for parameter in model.parameters():
        parameter.requires_grad_(False)
    prefixes = ("control_interface.hand_adapter.zero_heads.", "control_interface.strength_controller.hand_log_group_scale") if warmup else HAND_ONLY_PREFIXES
    selected = []
    for name, parameter in model.named_parameters():
        if _has_prefix(name, prefixes):
            parameter.requires_grad_(True)
            selected.append(parameter)
    return tuple(selected)


def freeze_for_detail_training(model: nn.Module) -> tuple[nn.Parameter, ...]:
    """Freeze V6.3 and expose only V6.4 detail modules and detail group gates."""

    for parameter in model.parameters():
        parameter.requires_grad_(False)
    trainable_prefixes = (
        "detail_preparer.",
        "control_interface.control_core.detail_branch.",
        "control_interface.strength_controller.detail_log_group_scale",
    )
    selected = []
    for name, parameter in model.named_parameters():
        if any(name.startswith(prefix) for prefix in trainable_prefixes):
            parameter.requires_grad_(True)
            selected.append(parameter)
    return tuple(selected)


def freeze_for_face_training(model: nn.Module) -> tuple[nn.Parameter, ...]:
    """Freeze every old branch and expose only the independent V6.5 face path."""

    for parameter in model.parameters():
        parameter.requires_grad_(False)
    selected = []
    for name, parameter in model.named_parameters():
        if _has_prefix(name, FACE_ONLY_PREFIXES):
            parameter.requires_grad_(True)
            selected.append(parameter)
    return tuple(selected)


