"""Offline-only SMPL-X hand quality gate and conservative refinement merge."""
from __future__ import annotations

import torch


def hand_quality_gate(keypoints: torch.Tensor, boxes: torch.Tensor, *, min_side: float = .035, min_confidence: float = .35) -> torch.Tensor:
    """True means request 2D refinement; does not imply target RGB at inference."""
    if keypoints.shape[-2:] != (21, 3) or boxes.shape[-1] != 4:
        raise ValueError("expected hand keypoints [...,21,3] and boxes [...,4]")
    size = boxes[..., 2:] - boxes[..., :2]
    confidence = keypoints[..., 2].mean(-1)
    outside = ((keypoints[..., :2] < 0) | (keypoints[..., :2] > 1)).any(-1).float().mean(-1)
    return (size.amin(-1) < min_side) | (confidence < min_confidence) | (outside > .2)


def merge_vitpose_keypoints(smplx: torch.Tensor, vitpose: torch.Tensor, refine: torch.Tensor, *, min_confidence: float = .25) -> torch.Tensor:
    """Use a confident ViTPose result for flagged samples; preserve SMPL-X otherwise."""
    if vitpose.shape != smplx.shape or smplx.shape[-2:] != (21, 3) or refine.shape != smplx.shape[:-2]:
        raise ValueError("ViTPose refinement shapes must match 21-point SMPL-X hands")
    accept = refine & (vitpose[..., 2].mean(-1) >= min_confidence)
    return torch.where(accept[..., None, None], vitpose, smplx)

"""Shape-adapted VTON-HandFit Handprocessor and Perceiver Resampler primitives.

Upstream: VTON-HandFit/VTON-HandFit e69aaacc8285c2bd248ff9b1b6d8e9b92b1f8b5a
HandFit/pose_guider.py and HandFit/ip_adapter/resampler.py. The projection
topology and latent-query attention are retained; dimensions are exposed for
DeepGen's 512-wide hand stream. No UNet or CUDA-specific operation is imported.
"""
from __future__ import annotations

import torch
import torch.nn as nn
import torch.nn.functional as F


class FeatureEmbedderLN(nn.Module):
    def __init__(self, input_dim: int, hidden_dim: int, output_dim: int):
        super().__init__()
        self.linear = nn.Sequential(
            nn.Linear(input_dim, hidden_dim), nn.LayerNorm(hidden_dim), nn.ReLU(),
            nn.Linear(hidden_dim, hidden_dim), nn.LayerNorm(hidden_dim), nn.ReLU(),
            nn.Linear(hidden_dim, output_dim), nn.LayerNorm(output_dim),
        )

    def forward(self, x):
        return self.linear(x)


class OneLinearLN(nn.Module):
    def __init__(self, input_dim: int, output_dim: int):
        super().__init__()
        self.linear = nn.Sequential(nn.Linear(input_dim, output_dim), nn.LayerNorm(output_dim))

    def forward(self, x):
        return self.linear(x)


class HandStructureProjector(nn.Module):
    """VTON's separate BPS/6D/side/2D projectors with an explicit null BPS."""

    def __init__(self, dim: int = 512):
        super().__init__()
        self.mano_bps = FeatureEmbedderLN(1024, max(dim, 64), dim)
        self.mano_6d = OneLinearLN(96, dim)
        self.handtype = OneLinearLN(1, dim)
        self.mano_2d = FeatureEmbedderLN(42, max(dim, 64), dim)
        self.combined = OneLinearLN(dim * 3, dim)
        self.null_bps = nn.Parameter(torch.zeros(dim))

    def forward(self, bps, pose6d, points42, side, mesh_valid):
        bps_features = self.mano_bps(bps)
        bps_features = torch.where(mesh_valid[..., None], bps_features, self.null_bps)
        volume = self.combined(torch.cat((bps_features, self.mano_6d(pose6d), self.handtype(side)), -1))
        return volume, self.mano_2d(points42)


class PerceiverAttention(nn.Module):
    def __init__(self, dim: int, heads: int = 8):
        super().__init__()
        if dim % heads:
            raise ValueError("dim must divide heads")
        self.heads = heads
        self.dim_head = dim // heads
        self.norm1 = nn.LayerNorm(dim)
        self.norm2 = nn.LayerNorm(dim)
        self.to_q = nn.Linear(dim, dim, bias=False)
        self.to_kv = nn.Linear(dim, dim * 2, bias=False)
        self.to_out = nn.Linear(dim, dim, bias=False)

    def forward(self, x, latents):
        b, n, d = latents.shape
        q = self.to_q(self.norm2(latents)).reshape(b, n, self.heads, self.dim_head).transpose(1, 2)
        kv = self.to_kv(torch.cat((self.norm1(x), self.norm2(latents)), dim=1))
        k, v = (tensor.reshape(b, -1, self.heads, self.dim_head).transpose(1, 2) for tensor in kv.chunk(2, -1))
        scale = self.dim_head ** -.25
        weights = torch.softmax(((q * scale) @ (k * scale).transpose(-1, -2)).float(), dim=-1).to(q.dtype)
        return self.to_out((weights @ v).transpose(1, 2).reshape(b, n, d))


class HandResampler(nn.Module):
    def __init__(self, *, dim: int = 512, depth: int = 2, heads: int = 8, num_queries: int = 8):
        super().__init__()
        self.latents = nn.Parameter(torch.randn(1, num_queries, dim) / dim ** .5)
        self.proj_in = nn.Linear(dim, dim)
        self.proj_out = nn.Linear(dim, dim)
        self.norm_out = nn.LayerNorm(dim)
        self.layers = nn.ModuleList([
            nn.ModuleList([
                PerceiverAttention(dim, heads),
                nn.Sequential(nn.LayerNorm(dim), nn.Linear(dim, dim * 4), nn.GELU(), nn.Linear(dim * 4, dim)),
            ]) for _ in range(depth)
        ])

    def forward(self, x):
        latents = self.latents.expand(x.shape[0], -1, -1)
        x = self.proj_in(x)
        for attention, feed_forward in self.layers:
            latents = latents + attention(x, latents)
            latents = latents + feed_forward(latents)
        return self.norm_out(self.proj_out(latents))

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

import torch

from third_party.v65_face.xdyna import repeat_condition_batch

from ..conditions import _to_preserving_discrete_dtype
from ..control_core import BranchControlResiduals  # noqa: F401 - public re-export
from ..detail import PreparedFaceHandDetailConditioning
from ..face.conditions import PreparedFaceConditioning
from ..hand.conditions import PreparedHandConditioning
from ..reasoning import InternalControlState


@dataclass
class PreparedControlConditioning:
    """Static per-image conditions consumed by every denoising step."""

    geometry_condition: torch.Tensor
    interaction_condition: torch.Tensor
    adapter_tokens: torch.Tensor
    adapter_token_mask: torch.Tensor
    person_count: torch.Tensor
    interaction_valid: torch.Tensor
    control_state: InternalControlState
    detail: PreparedFaceHandDetailConditioning | None = None
    face: PreparedFaceConditioning | None = None
    hand: PreparedHandConditioning | None = None

    @property
    def batch_size(self) -> int:
        return int(self.geometry_condition.shape[0])

    def validate(self) -> "PreparedControlConditioning":
        if self.geometry_condition.ndim != 4:
            raise ValueError("geometry_condition must have shape [B,C,H,W]")
        if self.interaction_condition.shape != self.geometry_condition.shape:
            raise ValueError("interaction_condition must match geometry_condition")
        batch_size = self.batch_size
        if self.adapter_tokens.ndim != 3 or self.adapter_tokens.shape[0] != batch_size:
            raise ValueError("adapter_tokens must have shape [B,M,D]")
        if (
            self.adapter_token_mask.shape != self.adapter_tokens.shape[:2]
            or self.adapter_token_mask.dtype != torch.bool
        ):
            raise ValueError("adapter_token_mask must have shape [B,M] and dtype bool")
        if self.person_count.shape != (batch_size,) or self.person_count.dtype != torch.long:
            raise ValueError("person_count must have shape [B] and dtype int64")
        if (
            self.interaction_valid.shape != (batch_size,)
            or self.interaction_valid.dtype != torch.bool
        ):
            raise ValueError("interaction_valid must have shape [B] and dtype bool")
        if not torch.equal(self.interaction_valid, self.person_count == 2):
            raise ValueError("interaction_valid must identify exactly the dual-person rows")
        if self.control_state.batch_size != batch_size:
            raise ValueError("control_state batch does not match prepared conditions")
        if self.detail is not None:
            self.detail.validate()
            if self.detail.batch_size != batch_size:
                raise ValueError("detail batch does not match prepared conditions")
        if self.face is not None:
            self.face.validate()
            if self.face.batch_size != batch_size:
                raise ValueError("face batch does not match prepared conditions")
        if self.hand is not None:
            self.hand.validate()
            if self.hand.batch_size != batch_size:
                raise ValueError("hand batch does not match prepared conditions")
        invalid = ~self.interaction_valid
        if invalid.any() and torch.count_nonzero(self.interaction_condition[invalid]) != 0:
            raise ValueError("single-person interaction_condition must be exactly zero")
        if torch.count_nonzero(
            self.adapter_tokens * (~self.adapter_token_mask)[..., None]
        ) != 0:
            raise ValueError("masked adapter tokens must be exactly zero")
        return self

    def index_select(self, indices: torch.Tensor) -> "PreparedControlConditioning":
        return type(self)(
            geometry_condition=self.geometry_condition.index_select(0, indices),
            interaction_condition=self.interaction_condition.index_select(0, indices),
            adapter_tokens=self.adapter_tokens.index_select(0, indices),
            adapter_token_mask=self.adapter_token_mask.index_select(0, indices),
            person_count=self.person_count.index_select(0, indices),
            interaction_valid=self.interaction_valid.index_select(0, indices),
            control_state=self.control_state.index_select(indices),
            detail=None if self.detail is None else self.detail.index_select(indices),
            face=None if self.face is None else self.face.index_select(indices),
            hand=None if self.hand is None else self.hand.index_select(indices),
        )

    def expand_to_batch(self, batch_size: int) -> "PreparedControlConditioning":
        if batch_size % self.batch_size:
            raise ValueError("prepared batch cannot be expanded to transformer batch")
        factor = batch_size // self.batch_size
        indices = repeat_condition_batch(
            torch.arange(self.batch_size, device=self.geometry_condition.device),
            factor,
        )
        return self.index_select(indices).validate()

    def to(self, *args, **kwargs) -> "PreparedControlConditioning":
        return type(self)(
            geometry_condition=self.geometry_condition.to(*args, **kwargs),
            interaction_condition=self.interaction_condition.to(*args, **kwargs),
            adapter_tokens=self.adapter_tokens.to(*args, **kwargs),
            adapter_token_mask=_to_preserving_discrete_dtype(
                self.adapter_token_mask, *args, **kwargs
            ),
            person_count=_to_preserving_discrete_dtype(
                self.person_count, *args, **kwargs
            ),
            interaction_valid=_to_preserving_discrete_dtype(
                self.interaction_valid, *args, **kwargs
            ),
            control_state=self.control_state.to(*args, **kwargs),
            detail=None if self.detail is None else self.detail.to(*args, **kwargs),
            face=None if self.face is None else self.face.to(*args, **kwargs),
            hand=None if self.hand is None else self.hand.to(*args, **kwargs),
        )


@dataclass
class DeepGenControlOutput:
    """Six aligned residual groups and lightweight runtime diagnostics."""

    block_controlnet_hidden_states: tuple[torch.Tensor, ...]
    diagnostics: dict[str, Any]

    def validate(self) -> "DeepGenControlOutput":
        if len(self.block_controlnet_hidden_states) != 6:
            raise ValueError("DeepGen control output must contain six residuals")
        expected = None
        for index, residual in enumerate(self.block_controlnet_hidden_states):
            if residual.ndim != 3:
                raise ValueError(f"control residual {index} must have shape [B,N,D]")
            if expected is None:
                expected = residual.shape
            elif residual.shape != expected:
                raise ValueError("all DeepGen residuals must have the same shape")
        return self

