def build_index(directory):
    directory = Path(directory)

    out = {}

    if not directory.is_dir():
        return out

    for p in directory.iterdir():
        if not p.is_file():
            continue

        try:
            n = int(p.stem)
        except ValueError:
            continue

        out[n] = p

    return out


def resize_h(img, h=270):
    if img is None:
        return np.zeros(
            (h, int(h * 0.56), 3),
            dtype=np.uint8,
        )

    H, W = img.shape[:2]

    scale = h / H

    return cv2.resize(
        img,
        (
            max(1, int(W * scale)),
            h,
        ),
        interpolation=cv2.INTER_AREA,
    )


def fit_width(img, width):
    H, W = img.shape[:2]

    if W == width:
        return img

    if W > width:
        return cv2.resize(
            img,
            (width, H),
            interpolation=cv2.INTER_AREA,
        )

    canvas = np.zeros(
        (H, width, 3),
        dtype=np.uint8,
    )

    x = (width - W) // 2

    canvas[:, x:x+W] = img

    return canvas


def make_panel(row):
    current_path = Path(
        row["rgb"]
    )

    seq_dir = current_path.parent
    idx = build_index(seq_dir)

    try:
        frame_num = int(
            row["stem"]
        )
    except Exception:
        frame_num = int(
            current_path.stem
        )

    prev_img = read_bgr(
        idx.get(frame_num - 1)
    )

    cur_img = read_bgr(
        current_path
    )

    next_img = read_bgr(
        idx.get(frame_num + 1)
    )

    views = [
        resize_h(prev_img),
        resize_h(cur_img),
        resize_h(next_img),
    ]

    cell_w = max(
        x.shape[1]
        for x in views
    )

    views = [
        fit_width(x, cell_w)
        for x in views
    ]

    strip = np.concatenate(
        views,
        axis=1,
    )

    # current frame white border
    cv2.rectangle(
        strip,
        (cell_w, 0),
        (cell_w * 2 - 1, strip.shape[0] - 1),
        (255, 255, 255),
        4,
    )

    header_h = 72

    panel = np.zeros(
        (
            strip.shape[0] + header_h,
            strip.shape[1],
            3,
        ),
        dtype=np.uint8,
    )

    panel[
        header_h:,
        :
    ] = strip

    line1 = (
        f"{row['split']} "
        f"{row['sequence_id']}/{row['stem']}  "
        f"CURRENT = middle"
    )

    line2 = (
        f"recover={row['temporal_recovery_ratio']:.3f}  "
        f"seqEdgeP={row['seq_edge_percentile']:.3f}"
    )

    cv2.putText(
        panel,
        line1,
        (6, 25),
        cv2.FONT_HERSHEY_SIMPLEX,
        0.52,
        (255, 255, 255),
        1,
        cv2.LINE_AA,
    )

    cv2.putText(
        panel,
        line2,
        (6, 52),
        cv2.FONT_HERSHEY_SIMPLEX,
        0.52,
        (255, 255, 255),
        1,
        cv2.LINE_AA,
    )

    return panel


def save_pages(rows):
    OUT_ROOT.mkdir(
        parents=True,
        exist_ok=True,
    )

    panels = [
        make_panel(r)
        for r in rows
    ]

    outputs = []

    for start in range(
        0,
        len(panels),
        PER_PAGE,
    ):
        chunk = panels[
            start:start + PER_PAGE
        ]

        max_h = max(
            p.shape[0]
            for p in chunk
        )

        max_w = max(
            p.shape[1]
            for p in chunk
        )

        fixed = []

        for p in chunk:
            canvas = np.zeros(
                (
                    max_h,
                    max_w,
                    3,
                ),
                dtype=np.uint8,
            )

            canvas[
                :p.shape[0],
                :p.shape[1],
            ] = p

            fixed.append(canvas)

        rows_out = []

        for i in range(
            0,
            len(fixed),
            COLS,
        ):
            line = fixed[
                i:i + COLS
            ]

            while len(line) < COLS:
                line.append(
                    np.zeros_like(
                        fixed[0]
                    )
                )

            rows_out.append(
                np.concatenate(
                    line,
                    axis=1,
                )
            )

        sheet = np.concatenate(
            rows_out,
            axis=0,
        )

        page = start // PER_PAGE + 1

        out = (
            OUT_ROOT
            / f"global_hard_blur_review_{page:02d}.jpg"
        )

        cv2.imwrite(
            str(out),
            sheet,
            [
                cv2.IMWRITE_JPEG_QUALITY,
                94,
            ],
        )

        outputs.append(out)

    return outputs


def main():
    rows = read_jsonl(
        IN_JSONL
    )

    # strongest evidence first
    rows.sort(
        key=lambda x: (
            x[
                "temporal_recovery_ratio"
            ],
            -x[
                "seq_edge_percentile"
            ],
        ),
        reverse=True,
    )

    outputs = save_pages(
        rows
    )

    print("=" * 72)
    print("FINAL GLOBAL BLUR REVIEW")
    print("=" * 72)
    print("frames:", len(rows))

    for p in outputs:
        print(p)


if __name__ == "__main__":
    main()

"""CPU-only final audit of the completed experiment, independent of UI labels."""
import argparse
import csv
import json
import math
from pathlib import Path
from .common import quality_manifest,training_manifest,write_json,sha256

def audit(root):
    manifests=quality_manifest()+training_manifest()+training_manifest(True)
    contracts={c['id']:c for c in manifests}
    expected=list(contracts)
    expected += [f'STABLE_M_{r}_{i}' for r in (512,768,1024) for i in range(3)]
    expected += [f'ADAPTER_INFER_{r}_{t}' for r in (512,768,1024) for t in ('S0','D0')]
    expected += [f'Q4_{t}_{r}_{s}' for t in ('S2','D1') for r in (768,1024) for s in (42,1024)]
    errors=[];status_counts={};checked=[]
    for name in expected:
        d=root/'runs'/name
        if not (d/'summary.json').exists():errors.append(f'Missing run {name}');continue
        c=json.loads((d/'config.json').read_text(encoding='utf-8'));s=json.loads((d/'summary.json').read_text(encoding='utf-8'))
        if name in contracts and any(c.get(k)!=value for k,value in contracts[name].items()):errors.append(f'{name}: manifest configuration mismatch')
        status_counts[s['status']]=status_counts.get(s['status'],0)+1
        if s['status']!='PASS':errors.append(f'{name}: {s["status"]}');continue
        if s.get('nvml_error'):errors.append(f'{name}: NVML error')
        with (d/'gpu_samples.csv').open() as f:
            values=[float(r['used_gib']) for r in csv.DictReader(f)]
        if not values or abs(max(values)-s['peak_nvml_gib'])>1e-6:errors.append(f'{name}: NVML summary mismatch')
        if c['kind']=='train':
            v=json.loads((d/'validation.json').read_text(encoding='utf-8'))
            if v['backbone_before']!=v['backbone_after']:errors.append(f'{name}: base weights changed')
            module_keys={'transformer','vae','lmm','connector'} if c['encoding']=='online' else {'transformer','vae'}
            if set(v['backbone_before'])!=module_keys:errors.append(f'{name}: incomplete frozen-module evidence')
            if not s.get('validation_passed') or v.get('zero_max_abs_diff') is None or not 0<=v['zero_max_abs_diff']<=.01 or v['gradients'].get('backbone_gradients_absent') is not True:errors.append(f'{name}: frozen/zero equivalence gate failed')
            if v['gradients']['heads_nonzero']!=[True]*6 or not v['gradients']['body_nonzero']:errors.append(f'{name}: gradient gate failed')
            if v['optimizer_dtypes']!=['torch.float32']:errors.append(f'{name}: optimizer precision mismatch')
            updates=json.loads((d/'updates.json').read_text())
            expected_count=100 if c['group']=='stable' else 25
            if len(updates)!=expected_count or s['train_steps']!=expected_count:errors.append(f'{name}: update count mismatch')
            if c['checkpointing'] and min(v['recomputation'].values())<2:errors.append(f'{name}: no actual checkpoint recomputation')
            if not c['checkpointing'] and v['recomputation']!={'dit':1,'adapter':1}:errors.append(f'{name}: unexpected recomputation')
            shapes=s.get('semantic_shapes',{})
            if set(shapes)!=set(c.get('training_tasks',[c['task']])):errors.append(f'{name}: missing semantic evidence')
            for task,shape in shapes.items():
                if set(shape)!={'seq','pooled','ref','target'} or shape['seq'][1]<=64 or shape['ref'][-2:]!=[c['resolution']//8]*2 or shape['target']!=shape['ref']:errors.append(f'{name}: invalid real condition shapes')
            if c['encoding']=='online':
                comparison=v.get('cached_online_comparison') or {}
                if set(comparison)!={'seq','pooled','ref','target'} or not all(x.get('allclose') is True for x in comparison.values()):errors.append(f'{name}: cache comparison failed')
            if any(not math.isfinite(u[k]) for u in updates for k in ('loss','gradient_norm')):errors.append(f'{name}: nonfinite optimization record')
            if c.get('alternate'):
                if [u['task'] for u in updates]!=['S0','D0']*50:errors.append(f'{name}: alternation incorrect')
                for task in ('S0','D0'):
                    if not (d/'task_evidence'/task/'control_metadata.json').exists():errors.append(f'{name}: {task} controls missing')
        if c['kind'] in ('quality','adapter_infer'):
            if not (d/'output.png').exists() or not (d/'output_content.png').exists():errors.append(f'{name}: output missing')
        checked.append(name)
    a=root/'runs/Q0_S0_42_stretch_35_4.5/output.png';b=root/'runs/REPRO_Q0_S0_42/output.png'
    repro=a.exists() and b.exists() and sha256(a)==sha256(b)
    if not repro:errors.append('Reproduction output hashes do not match')
    capacity=json.loads((root/'capacity.json').read_text()) if (root/'capacity.json').exists() else []
    if len(capacity)!=3 or {r.get('resolution') for r in capacity}!={512,768,1024}:errors.append('All three resolution capacity gates not yet passed')
    for r in capacity:
        numeric=('stable_peak_nvml_gib','steady_peak_allocated_gib','steady_peak_reserved_gib','lifecycle_peak_nvml_gib','suggested_capacity_gib','repeat_variation','step_p50_seconds')
        if any(not isinstance(r.get(k),(int,float)) or not math.isfinite(r[k]) for k in numeric):errors.append('Invalid capacity numeric fields');continue
        res=r['resolution'];stable=[];lifecycle=[];cache_tasks=set();infer_tasks=set()
        for p in (root/'runs').glob('*/summary.json'):
            cfg=json.loads((p.parent/'config.json').read_text(encoding='utf-8'));summary=json.loads(p.read_text())
            if cfg.get('resolution')!=res or summary['status']!='PASS':continue
            if cfg.get('group')=='stable':stable.append(summary);lifecycle.append(summary)
            if cfg.get('kind')=='cache':
                if summary.get('cache_roundtrip_exact'):cache_tasks.add(cfg['task'])
                lifecycle.append(summary)
            if cfg.get('kind')=='adapter_infer':infer_tasks.add(cfg['task']);lifecycle.append(summary)
        if len(stable)!=3 or cache_tasks!={'S0','D0'} or infer_tasks!={'S0','D0'}:errors.append(f'{res}: capacity prerequisite evidence missing');continue
        peak=max(s['peak_nvml_gib'] for s in lifecycle);peaks=[s['peak_nvml_gib'] for s in stable]
        variation=(max(peaks)-min(peaks))/min(peaks)
        if r['lifecycle_peak_nvml_gib']!=peak or r['stable_peak_nvml_gib']!=max(peaks) or variation>.05 or abs(r['repeat_variation']-variation)>1e-8 or r['suggested_capacity_gib']!=math.ceil(peak+max(2,.1*peak)):errors.append(f'{res}: capacity calculation mismatch')
    scores=json.loads((root/'scores.json').read_text(encoding='utf-8')) if (root/'scores.json').exists() else {}
    quality_ids=[name for name in expected if name.startswith('Q')]
    if any(name not in scores for name in quality_ids):errors.append('Some native editing images lack visual scores')
    for name in quality_ids:
        score=scores.get(name,{})
        for key in ('action','identity','clothing','background','anatomy'):
            value=score.get(key)
            if key not in score or not (key=='identity' and value is None) and (type(value) is not int or value not in (0,1,2)):errors.append(f'{name}: invalid score {key}')
        if any(type(score.get(k)) is not bool for k in ('added_person','missing_person','wrong_person')) or not score.get('reviewer') or not score.get('note'):errors.append(f'{name}: incomplete score provenance/flags')
    selection_path=root/'quality_selection.json'
    if not selection_path.exists():errors.append('Quality selection missing')
    else:
        selection=json.loads(selection_path.read_text(encoding='utf-8'))
        for name in quality_ids:
            if name.startswith('Q4_') and (root/'runs'/name/'config.json').exists():
                cfg=json.loads((root/'runs'/name/'config.json').read_text(encoding='utf-8'))
                if any(cfg.get(k)!=v for k,v in selection['parameters'].items()):errors.append(f'{name}: selected parameters mismatch')
    result=dict(passed=not errors,expected_primary_runs=len(expected),checked_primary_runs=len(checked),status_counts=status_counts,
                errors=errors,reproducible_output_exact=repro,quality_score_source='AI visual initial review; human review pending',
                interpretation='Acceptance of experiment implementation and resource measurement, not pose-edit capability')
    write_json(root/'ACCEPTANCE.json',result)
    return result

def main():
    p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);a=p.parse_args();result=audit(a.root)
    print(json.dumps(result,ensure_ascii=False,indent=2))
    raise SystemExit(0 if result['passed'] else 1)
if __name__=='__main__':main()

"""Build a dependency-free, evidence-backed CPU-only experiment report."""
from __future__ import annotations

import argparse
import csv
import io
import json
import math
import struct
from collections import Counter
from datetime import datetime, timezone
from pathlib import Path
from urllib.parse import quote

SCORE_FIELDS = ("action", "identity", "clothing", "background", "anatomy")
FLAG_FIELDS = ("added_person", "missing_person", "wrong_person")
PROVENANCE_FIELDS = ("reviewer", "note")
STATUSES = {"PASS", "OOM", "INVALID", "TIMEOUT", "CANCELLED", "NOT_RUN"}
METRICS = ("wall_seconds", "peak_allocated_gib", "peak_reserved_gib", "peak_nvml_gib", "step_p50_seconds", "step_p95_seconds", "adapter_parameters")
CSV_FIELDS = ("id", "kind", "group", "task", "seed", "cfg", "steps", "resolution", "preprocess", "status", "validation_passed", *METRICS, *SCORE_FIELDS, *FLAG_FIELDS, *PROVENANCE_FIELDS)
IMAGE_NAMES = ("input_original", "input_model", "output", "output_content", "normal", "depth", "skeleton", "contact")


def read_json(path: Path, default=None):
    try:
        return json.loads(path.read_text(encoding="utf-8-sig"), parse_constant=lambda _: None)
    except (OSError, ValueError):
        return default


def number(value):
    """Missing/non-finite values remain missing, never become zero."""
    if isinstance(value, bool):
        return None
    try:
        result = float(value)
        return result if math.isfinite(result) and result >= 0 else None
    except (TypeError, ValueError):
        return None


def png_dimensions(path: Path):
    try:
        with path.open("rb") as stream:
            head = stream.read(24)
        if len(head) == 24 and head[:8] == b"\x89PNG\r\n\x1a\n" and head[12:16] == b"IHDR":
            width, height = struct.unpack(">II", head[16:24])
            return {"width": width, "height": height}
    except OSError:
        pass
    return None


def normalize_scores(raw):
    raw = raw if isinstance(raw, dict) else {}
    return {
        **{key: raw.get(key) if type(raw.get(key)) in (int, float) and raw.get(key) in (0, 1, 2) else None for key in SCORE_FIELDS},
        **{key: raw.get(key) if isinstance(raw.get(key), bool) else None for key in FLAG_FIELDS},
        **{key: raw.get(key) if isinstance(raw.get(key), str) else None for key in PROVENANCE_FIELDS},
    }


def load_task_evidence(directory: Path, config: dict, prefix: str):
    """Keep alternating task inputs and controls together without changing run config."""
    entries = config.get("task_evidence", {})
    if not isinstance(entries, dict):
        return {}
    result = {}
    for task, relative in entries.items():
        if not isinstance(relative, str):
            continue
        path = (directory / relative).resolve()
        if not path.is_relative_to(directory.resolve()) or not path.is_dir():
            continue
        rel = path.relative_to(directory.resolve()).as_posix()
        task_prefix = prefix + quote(rel, safe="/") + "/"
        evidence = {p.name: task_prefix + quote(p.name, safe="") for p in path.iterdir() if p.is_file()}
        images = {name: {"url": evidence[name + ".png"], "dimensions": png_dimensions(path / (name + ".png"))}
                  for name in IMAGE_NAMES if name + ".png" in evidence}
        result[str(task)] = {"relative_path": rel, "images": images, "evidence": evidence,
                             "control_metadata": read_json(path / "control_metadata.json", {}),
                             "config": read_json(path / "config.json", {})}
    return result


def timeline_phases(events):
    """Group consecutive stage starts for display; leave source events untouched."""
    ordered = sorted((event for event in events if isinstance(event, dict)
                      and number(event.get("elapsed_seconds")) is not None),
                     key=lambda event: number(event["elapsed_seconds"]))
    phases = []
    for event in ordered:
        stage = event.get("stage")
        if not isinstance(stage, str) or not stage:
            continue
        elapsed = number(event["elapsed_seconds"])
        if event.get("event") == "start":
            if not phases or phases[-1]["stage"] != stage:
                phases.append({"stage": stage, "start_seconds": elapsed, "last_start_seconds": elapsed,
                               "end_seconds": None, "count": 1, "closed": False})
            else:
                phases[-1]["count"] += 1
                phases[-1]["last_start_seconds"] = elapsed
                phases[-1]["closed"] = False
        elif event.get("event") == "end":
            for phase in reversed(phases):
                if phase["stage"] == stage and not phase["closed"]:
                    phase["end_seconds"] = elapsed
                    phase["closed"] = True
                    break
    return phases


def load_run(directory: Path, root: Path, overrides: dict):
    config = read_json(directory / "config.json", {})
    config = config if isinstance(config, dict) else {}
    summary = read_json(directory / "summary.json")
    present = isinstance(summary, dict)
    summary = summary if present else {}
    run_id = str(config.get("id") or directory.name)
    status = str(summary.get("status", "NOT_RUN")).upper()
    warning = None
    if not present:
        warning = "summary.json 缺失或无法解析；未确认运行结果"
    elif status not in STATUSES:
        warning = "summary.json 中状态无法识别"
        status = "INVALID"
    prefix = "runs/" + quote(directory.name, safe="") + "/"
    evidence = {p.name: prefix + quote(p.name, safe="") for p in directory.iterdir() if p.is_file()}
    images = {}
    for name in IMAGE_NAMES:
        if name + ".png" in evidence:
            images[name] = {"url": evidence[name + ".png"], "dimensions": png_dimensions(directory / (name + ".png"))}
    events = []
    try:
        for line in (directory / "events.jsonl").read_text(encoding="utf-8-sig").splitlines():
            try:
                event = json.loads(line, parse_constant=lambda _: None)
                if isinstance(event, dict):
                    events.append(event)
            except ValueError:
                continue
    except OSError:
        pass
    samples = []
    try:
        with (directory / "gpu_samples.csv").open(encoding="utf-8-sig", newline="") as stream:
            for sample in csv.DictReader(stream):
                samples.append({"elapsed_seconds": number(sample.get("elapsed_seconds")), "used_gib": number(sample.get("used_gib")), "stage": sample.get("stage")})
    except (OSError, csv.Error):
        pass
    original_scores = summary.get("scores", {})
    original_scores = original_scores if isinstance(original_scores, dict) else {}
    override = overrides.get(run_id, {})
    if isinstance(override, dict) and isinstance(override.get("scores"), dict):
        override = {**override, **override["scores"]}
    scores = normalize_scores({**original_scores, **(override if isinstance(override, dict) else {})})
    return {
        "id": run_id, "directory": directory.name, "config": config, "summary": summary,
        "status": status, "summary_present": present, "warning": warning,
        **{field: number(summary.get(field)) for field in METRICS},
        "stages": summary.get("stages") if isinstance(summary.get("stages"), list) else [],
        "validation_passed": summary.get("validation_passed") if isinstance(summary.get("validation_passed"), bool) else None,
        "control_metadata": read_json(directory / "control_metadata.json", {}),
        "task_evidence": load_task_evidence(directory, config, prefix),
        "source_version": read_json(directory / "source_version.json", summary.get("source_version", config.get("source_version"))),
        "scores": scores, "images": images, "evidence": evidence, "events": events, "gpu_samples": samples,
        "timeline_phases": timeline_phases(events),
    }


def aggregate(runs):
    """Aggregate only real observations; failure rows are included in counts."""
    counts = Counter(run["status"] for run in runs)
    completed = [run for run in runs if run["status"] == "PASS"]
    means = {}
    for field in METRICS:
        values = [run[field] for run in completed if run[field] is not None]
        means[field] = {"mean": sum(values) / len(values) if values else None, "n": len(values)}
    score_means = {}
    for field in SCORE_FIELDS:
        values = [run["scores"][field] for run in completed if run["scores"][field] is not None]
        score_means[field] = {"mean": sum(values) / len(values) if values else None, "n": len(values)}
    return {"total": len(runs), "counts": dict(counts), "pass_metrics": means, "pass_scores": score_means}


def csv_text(runs):
    output = io.StringIO(newline="")
    writer = csv.DictWriter(output, fieldnames=CSV_FIELDS)
    writer.writeheader()
    for run in runs:
        row = {key: run["config"].get(key) for key in CSV_FIELDS}
        row.update({key: run.get(key) for key in ("id", "status", "validation_passed", *METRICS)})
        row.update(run["scores"])
        for key, value in row.items():
            if isinstance(value, (dict, list)):
                row[key] = json.dumps(value, ensure_ascii=False)
            elif isinstance(value, str) and value.startswith(("=", "+", "-", "@")):
                row[key] = "'" + value
        writer.writerow(row)
    return output.getvalue()


def build_report(root):
    root = Path(root).resolve()
    root.mkdir(parents=True, exist_ok=True)
    overrides = read_json(root / "scores.json", {})
    overrides = overrides if isinstance(overrides, dict) else {}
    run_root = root / "runs"
    runs = [load_run(path, root, overrides) for path in sorted(run_root.iterdir()) if path.is_dir()] if run_root.is_dir() else []
    data = {"schema_version": 1, "generated_at": datetime.now(timezone.utc).isoformat(), "runs": runs, "aggregate": aggregate(runs),
            "capacity": read_json(root / "capacity.json"),
            "root_evidence": {name: name for name in ("capacity.json", "MEMORY_REPORT.md") if (root / name).is_file()}}
    serialized = json.dumps(data, ensure_ascii=False, allow_nan=False, default=str)
    # The payload is a non-executable JSON script; escaping '<' prevents closing it.
    inline = serialized.replace("&", "\\u0026").replace("<", "\\u003c").replace(">", "\\u003e").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    template = Path(__file__).with_name("demo.html").read_text(encoding="utf-8")
    (root / "index.html").write_text(template.replace("__REPORT_DATA__", inline), encoding="utf-8")
    (root / "results.json").write_text(serialized + "\n", encoding="utf-8")
    (root / "summary.csv").write_text(csv_text(runs), encoding="utf-8-sig")
    return data


def main(argv=None):
    parser = argparse.ArgumentParser(description="从已有实验记录生成中文 CPU-only HTML 报告")
    parser.add_argument("--root", required=True, type=Path, help="实验根目录，内含 runs/<id>/")
    args = parser.parse_args(argv)
    report = build_report(args.root)
    print(f"Report: {args.root.resolve() / 'index.html'} | {len(report['runs'])} runs")


if __name__ == "__main__":
    main()

"""Serial, resumable experiment controller. A completed run is immutable."""
import argparse
import contextlib
import json
import os
from pathlib import Path
import shutil
import signal
import subprocess
import sys
import time

from .common import MODEL, PROJECT, TASKS, quality_manifest, training_manifest, sha256, write_json

def preflight(root):
    from .common import environment
    expected={
      'transformer/diffusion_pytorch_model.safetensors':'54078ee51ab477275e94b610249ea912d6f80d24256c4197fe48945eef706883',
      'connector/model.safetensors':'425ce59f596eeb573f9cd52138b775df47ce69c60d2782fb32cac5498ed208f3',
      'vae/diffusion_pytorch_model.safetensors':'5a170129752b4ad4ab98996d2e59097c8c693afc31a5964bd2ad60896686c1e2',
      'vlm/model-00001-of-00002.safetensors':'d6f11cc9c30184ce92605f25ac1e6b6644ee217e7b86a28282b3c9b17de3e609',
      'vlm/model-00002-of-00002.safetensors':'c675c19a231b0ead141d8d3a05fe930892ddf17f1324d75bb94d2a42a79f7ebc'}
    actual={name:sha256(MODEL/name) for name in expected}
    result=dict(environment=environment(),weights=actual,weights_valid=actual==expected,
                source_hashes={p.name:sha256(p) for p in Path(__file__).parent.glob('*.py')})
    write_json(root/'preflight.json',result)
    assert result['weights_valid'],'Weight hash mismatch'
    print(json.dumps(result),flush=True)

def idle():
    # nvidia-smi subprocess cannot create a CUDA context in the controller.
    p=subprocess.run(['nvidia-smi','--query-compute-apps=pid','--format=csv,noheader,nounits'],capture_output=True,text=True,check=True)
    return not p.stdout.strip()

def used_budget(root,quality=False):
    offset=root/'budget_carryover.json'
    total=json.loads(offset.read_text()).get('quality_seconds' if quality else 'total_seconds',0) if offset.exists() else 0
    for path in (root/'runs').glob('*/summary.json'):
        config=json.loads((path.parent/'config.json').read_text())
        if not quality or config['kind']=='quality':
            total+=json.loads(path.read_text()).get('process_wall_seconds',0)
    return total

def execute(root,config,timeout=2700):
    root.mkdir(parents=True,exist_ok=True)
    run=root/'runs'/config['id']
    if (run/'summary.json').exists():
        previous=json.loads((run/'summary.json').read_text())
        if previous['status']=='NOT_RUN':
            archive=root/'attempts';archive.mkdir(exist_ok=True)
            run.rename(archive/(run.name+'_'+str(time.time_ns())))
        else:
            saved=json.loads((run/'config.json').read_text())
            if any(saved.get(k)!=v for k,v in config.items()):
                raise ValueError(f'Run ID {config["id"]} already exists with different configuration')
            return previous
    if run.exists():
        raise RuntimeError(f'Incomplete previous run: {run}; inspect before retry under a new ID')
    if used_budget(root)>72*3600 or (config['kind']=='quality' and used_budget(root,True)>6*3600):
        run.mkdir(parents=True)
        write_json(run/'config.json',config)
        write_json(run/'summary.json',dict(status='NOT_RUN',reason='GPU budget exhausted',process_wall_seconds=0))
        return json.loads((run/'summary.json').read_text())
    started_wait=time.time()
    while not idle():
        if time.time()-started_wait>6*3600:
            raise RuntimeError('GPU remained busy for 6 hours; no other processes were stopped')
        print('Waiting for existing GPU task to finish',flush=True)
        time.sleep(30)
    cfg=root/'configs'/(config['id']+'.json')
    write_json(cfg,config)
    logs=root/'logs';logs.mkdir(exist_ok=True)
    log_out=logs/(config['id']+'.stdout.log');log_err=logs/(config['id']+'.stderr.log')
    print('RUN',config['id'],flush=True)
    start=time.perf_counter()
    remaining=72*3600-used_budget(root)
    if config['kind']=='quality':
        remaining=min(remaining,6*3600-used_budget(root,True))
    timeout=max(1,min(timeout,remaining))
    with log_out.open('w') as fout,log_err.open('w') as ferr:
        env=dict(os.environ,PYTHONUNBUFFERED='1',HF_HUB_OFFLINE='1',TOKENIZERS_PARALLELISM='false')
        proc=subprocess.Popen([sys.executable,'-m','vram_lab.worker','--root',str(root),'--config',str(cfg)],
                              stdout=fout,stderr=ferr,env=env,start_new_session=True)
        try:
            proc.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            os.killpg(proc.pid,signal.SIGTERM)
            try: proc.wait(timeout=20)
            except subprocess.TimeoutExpired:
                os.killpg(proc.pid,signal.SIGKILL);proc.wait()
            run.mkdir(parents=True,exist_ok=True)
            write_json(run/'config.json',config)
            write_json(run/'summary.json',dict(status='TIMEOUT',process_wall_seconds=time.perf_counter()-start))
        except KeyboardInterrupt:
            os.killpg(proc.pid,signal.SIGTERM)
            try:proc.wait(timeout=20)
            except subprocess.TimeoutExpired:
                os.killpg(proc.pid,signal.SIGKILL);proc.wait()
            run.mkdir(parents=True,exist_ok=True)
            write_json(run/'config.json',config)
            write_json(run/'summary.json',dict(status='CANCELLED',process_wall_seconds=time.perf_counter()-start))
            shutil.copy2(log_out,run/'stdout.log');shutil.copy2(log_err,run/'stderr.log')
            raise
    run.mkdir(parents=True,exist_ok=True)
    shutil.copy2(log_out,run/'stdout.log');shutil.copy2(log_err,run/'stderr.log')
    if not (run/'summary.json').exists():
        write_json(run/'config.json',config)
        write_json(run/'summary.json',dict(status='INVALID',error=f'worker exit {proc.returncode}',process_wall_seconds=time.perf_counter()-start))
    result=json.loads((run/'summary.json').read_text())
    print('RESULT',config['id'],result['status'],result.get('peak_nvml_gib'),flush=True)
    return result

def caches(root,resolutions):
    from .worker import cache_key
    for res in resolutions:
        for task in ('S0','D0'):
            config=dict(id=f'CACHE_{res}_{task}',kind='cache',group='cache',task=task,resolution=res,seed=1701,
                        preprocess='letterbox',prompt=TASKS[task],control_injected=False)
            config['id']+='_'+cache_key(config)[0][:10]
            result=execute(root,config)
            if result['status']!='PASS':
                raise RuntimeError(f'Cache failed: {config["id"]}')

def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('command',choices=['preflight','quality','cache','smoke','main','stable','sensitivity','q4','infer','reproduce'])
    parser.add_argument('--root',type=Path,required=True)
    parser.add_argument('--groups',default='Q0,Q1,Q2,Q3')
    parser.add_argument('--resolution',type=int,nargs='+',default=[512,768,1024])
    parser.add_argument('--limit',type=int)
    args=parser.parse_args();root=args.root.resolve();root.mkdir(parents=True,exist_ok=True)
    import fcntl
    with (PROJECT/'vram_lab_gpu.lock').open('a') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        if args.command=='preflight':
            preflight(root);return
        if not (root/'preflight.json').exists():
            raise RuntimeError('Run preflight first')
        if not json.loads((root/'preflight.json').read_text()).get('weights_valid'):
            raise RuntimeError('Preflight weight validation failed')
        if args.command=='cache':
            caches(root,args.resolution);return
        if args.command=='quality':
            configs=[c for c in quality_manifest() if c['group'] in args.groups.split(',')]
        elif args.command=='reproduce':
            configs=[dict(quality_manifest()[0],id='REPRO_Q0_S0_42',group='reproducibility')]
        elif args.command=='infer':
            configs=[]
            for res in args.resolution:
                checkpoint=root/'runs'/f'STABLE_M_{res}_0'/'adapter.pt'
                for task in ('S0','D0'):
                    if not checkpoint.exists():
                        missing=root/'runs'/f'ADAPTER_INFER_{res}_{task}'
                        if not (missing/'summary.json').exists():
                            write_json(missing/'config.json',dict(id=missing.name,kind='adapter_infer',group='adapter_infer',task=task,resolution=res))
                            write_json(missing/'summary.json',dict(status='NOT_RUN',reason='No stable adapter checkpoint',process_wall_seconds=0))
                        continue
                    configs.append(dict(id=f'ADAPTER_INFER_{res}_{task}',kind='adapter_infer',group='adapter_infer',task=task,
                                        seed=42,resolution=res,preprocess='letterbox',prompt=TASKS[task],negative_prompt='',
                                        cfg=4.5,steps=35,adapter_checkpoint=str(checkpoint),control_injected=True))
        elif args.command=='q4':
            selected=json.loads((root/'quality_selection.json').read_text())
            configs=[]
            for task in ('S2','D1'):
                for res in (768,1024):
                    for seed in (42,1024):
                        params=selected['parameters']
                        configs.append(dict(id=f'Q4_{task}_{res}_{seed}',kind='quality',group='Q4',task=task,seed=seed,
                                            resolution=res,preprocess='letterbox',prompt=TASKS[task],control_injected=False,**params))
        elif args.command=='stable':
            configs=[]
            for res in args.resolution:
                candidates=[]
                for enc in ('cache','online'):
                    for ckpt in (True,False):
                        pair=[]
                        for task in ('S0','D0'):
                            path=root/'runs'/f'T_M_{res}_{enc}_{int(ckpt)}_{task}'/'summary.json'
                            if path.exists():
                                s=json.loads(path.read_text())
                                if s['status']=='PASS' and s.get('validation_passed') and not s.get('nvml_error') and (s.get('peak_nvml_gib') or 0)>0: pair.append(s['peak_nvml_gib'])
                        if len(pair)==2:candidates.append((max(pair),enc,ckpt))
                if not candidates:
                    for repeat in range(3):
                        missing=root/'runs'/f'STABLE_M_{res}_{repeat}'
                        if (missing/'summary.json').exists():continue
                        write_json(missing/'config.json',dict(id=missing.name,kind='train',group='stable',resolution=res,adapter_size='M'))
                        write_json(missing/'summary.json',dict(status='NOT_RUN',reason='No eligible main configuration for both photos',process_wall_seconds=0))
                    print(f'No valid configuration at {res}',flush=True);continue
                _,enc,ckpt=min(candidates)
                for repeat in range(3):
                    configs.append(dict(id=f'STABLE_M_{res}_{repeat}',kind='train',group='stable',task='S0',seed=42+repeat,
                                        resolution=res,encoding=enc,checkpointing=ckpt,adapter_size='M',alternate=True,
                                        preprocess='letterbox',prompt=TASKS['S0'],warmup=5,updates=95,control_injected=True))
        else:
            configs=[c for c in training_manifest(args.command=='sensitivity') if c['resolution'] in args.resolution]
            if args.command=='smoke':
                configs=[dict(configs[0],id='SMOKE_M_512',resolution=512,warmup=0,updates=3,group='smoke')]
        if args.limit:configs=configs[:args.limit]
        write_json(root/(args.command+'_manifest.json'),configs)
        for config in configs:
            result=execute(root,config,timeout=7200 if config.get('alternate') else 2700)
            if result['status']=='INVALID':
                raise RuntimeError(f'Invalid job {config["id"]}; repair before continuing matrix')

if __name__=='__main__':main()

